/* ============ TURBO STRIKE — UI SYSTEM ============ */
:root {
  --bg: #04060b;
  --bg-2: #080d17;
  --panel: rgba(8, 13, 24, 0.86);
  --panel-soft: rgba(13, 20, 35, 0.72);
  --line: rgba(120, 170, 230, 0.16);
  --line-bright: rgba(120, 220, 255, 0.4);
  --text: #e9f2ff;
  --muted: #8190ab;
  --dim: #59667d;
  --cyan: #35f0ff;
  --cyan-soft: rgba(53, 240, 255, 0.14);
  --blue: #2b8cff;
  --orange: #ff7a1a;
  --orange-soft: rgba(255, 122, 26, 0.15);
  --gold: #ffce4d;
  --danger: #ff4560;
  --green: #3cf0a4;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.65);
  --display: "Arial Black", "Arial Bold", "Segoe UI", Impact, sans-serif;
  --body: "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; overflow: hidden; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  overscroll-behavior: none;
  touch-action: manipulation;
}
button, input, select { font-family: inherit; color: inherit; }
button { cursor: pointer; border: none; background: none; }
canvas { display: block; }

#app { position: fixed; inset: 0; overflow: hidden; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; outline: none; }

#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 45%, rgba(1, 3, 8, 0.55) 100%),
    linear-gradient(180deg, rgba(2, 4, 9, 0.35), transparent 22%, transparent 78%, rgba(2, 4, 9, 0.5));
  mix-blend-mode: multiply;
}
#flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 20; opacity: 0;
  background: radial-gradient(circle at 50% 55%, rgba(255,255,255,.9), rgba(120,220,255,.25) 45%, transparent 70%);
  transition: opacity 0.4s ease;
}
#flash.on { opacity: 1; transition: opacity 0.04s; }

/* ---------- LOADING ---------- */
#loading {
  position: fixed; inset: 0; z-index: 100; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 14px;
  background:
    radial-gradient(circle at 50% 35%, rgba(21, 45, 74, 0.55), transparent 55%),
    linear-gradient(160deg, #060a13, #03050a);
  transition: opacity 0.6s ease, visibility 0.6s;
}
#loading.done { opacity: 0; visibility: hidden; }
.load-mark { animation: floaty 3s ease-in-out infinite; filter: drop-shadow(0 0 22px rgba(53, 240, 255, 0.35)); }
.load-spin { transform-origin: 50% 50%; animation: spin 1.1s linear infinite; }
.load-title { font-family: var(--display); font-size: 30px; letter-spacing: 7px; font-style: italic; }
.load-sub { color: var(--muted); font-size: 11px; letter-spacing: 4px; font-weight: 600; }
.load-track { width: 220px; height: 3px; background: rgba(255,255,255,.08); margin-top: 10px; overflow: hidden; }
.load-track i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--orange)); transition: width .3s; box-shadow: 0 0 12px var(--cyan); }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes floaty { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }

/* ---------- TOUCH ---------- */
#rotate-hint { display: none; }

/* ---------- SCREENS ---------- */
#screen-root { position: absolute; inset: 0; z-index: 30; pointer-events: none; }
.screen {
  position: absolute; inset: 0; pointer-events: auto;
  opacity: 0; visibility: hidden; transform: scale(1.015);
  transition: opacity 0.35s ease, visibility 0.35s, transform 0.5s cubic-bezier(.2,.8,.2,1);
  display: flex; flex-direction: column; overflow: hidden;
}
.screen.active { opacity: 1; visibility: visible; transform: none; }
.screen.home { background: linear-gradient(100deg, rgba(3,5,11,.97) 0%, rgba(3,5,11,.88) 28%, rgba(3,5,11,.3) 60%, rgba(3,5,11,.55) 100%); }
.screen.panel-screen { background: radial-gradient(ellipse at 20% 0%, rgba(37, 72, 120, 0.22), transparent 55%), rgba(3, 6, 12, 0.82); backdrop-filter: blur(9px); }
.screen::before {
  content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .35;
  background-image: linear-gradient(rgba(100,170,255,.045) 1px, transparent 1px), linear-gradient(90deg, rgba(100,170,255,.045) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse at 50% 50%, black 10%, transparent 78%);
}

/* ---------- BRAND ---------- */
.brand { display: flex; flex-direction: column; gap: 2px; }
.brand-line { display: flex; align-items: center; gap: 12px; }
.brand-mark {
  width: 44px; height: 44px; border: 2px solid rgba(53,240,255,.55); border-radius: 12px;
  display: grid; place-items: center; position: relative; background: rgba(6, 16, 27, 0.7);
  box-shadow: 0 0 24px rgba(53, 240, 255, 0.18), inset 0 0 18px rgba(53, 240, 255, 0.1);
  transform: rotate(-4deg);
}
.brand-mark svg { width: 26px; height: 26px; }
.brand-title { font-family: var(--display); font-style: italic; font-size: 24px; letter-spacing: 2px; line-height: 1; }
.brand-title em { color: var(--orange); font-style: italic; }
.brand-sub { font-size: 9px; letter-spacing: 4.5px; color: var(--muted); font-weight: 700; margin-left: 56px; }

.home-inner {
  position: relative; z-index: 2; height: 100%; display: grid;
  grid-template-columns: minmax(360px, 480px) 1fr; padding: clamp(22px, 3.4vw, 46px) clamp(22px, 4vw, 64px);
}
.home-left { display: flex; flex-direction: column; justify-content: space-between; gap: 18px; min-height: 0; }
.hero-block { margin-top: clamp(10px, 6vh, 64px); }
.eyebrow {
  display: inline-flex; align-items: center; gap: 8px; font-size: 10px; font-weight: 800;
  letter-spacing: 3.5px; color: var(--cyan); text-transform: uppercase; margin-bottom: 14px;
}
.eyebrow::before { content: ""; width: 26px; height: 2px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.hero-title {
  font-family: var(--display); font-style: italic; font-weight: 900;
  font-size: clamp(52px, 6.2vw, 92px); line-height: .84; letter-spacing: -2px;
  text-transform: uppercase; filter: drop-shadow(0 8px 40px rgba(0,0,0,.6));
}
.hero-title span { display: block; }
.hero-title .line-2 {
  background: linear-gradient(93deg, #fff 0%, #8fe9ff 34%, var(--cyan) 52%, #ff9a4d 78%, var(--orange) 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 26px rgba(53, 240, 255, 0.28));
}
.hero-desc { max-width: 380px; margin-top: 16px; color: #aab8cf; font-size: 13.5px; line-height: 1.6; }
.hero-desc strong { color: var(--text); }

.menu-stack { display: flex; flex-direction: column; gap: 9px; width: min(100%, 400px); margin-top: 26px; }
.menu-btn {
  position: relative; display: flex; align-items: center; gap: 14px; width: 100%;
  padding: 14px 18px; text-align: left; color: #d8e6f8;
  background: linear-gradient(90deg, rgba(16, 27, 45, 0.86), rgba(10, 18, 31, 0.5));
  border: 1px solid rgba(120, 170, 230, 0.16);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  transition: all .22s ease; overflow: hidden;
}
.menu-btn::after {
  content: ""; position: absolute; inset: 0; opacity: 0;
  background: linear-gradient(90deg, rgba(53,240,255,.13), transparent 70%);
  transition: opacity .25s;
}
.menu-btn:hover { color: #fff; border-color: rgba(53, 240, 255, .45); transform: translateX(5px); background: linear-gradient(90deg, rgba(18, 38, 60, .95), rgba(10, 18, 31, .5)); }
.menu-btn:hover::after { opacity: 1; }
.menu-btn:active { transform: translateX(3px) scale(.995); }
.menu-btn .mb-icon { width: 34px; height: 34px; display: grid; place-items: center; flex: 0 0 34px; background: rgba(53,240,255,.07); border: 1px solid rgba(53,240,255,.2); border-radius: 8px; color: var(--cyan); }
.menu-btn .mb-icon svg { width: 17px; height: 17px; }
.menu-btn .mb-text { flex: 1; min-width: 0; }
.menu-btn .mb-title { display: block; font-family: var(--display); font-style: italic; font-size: 16px; letter-spacing: .8px; text-transform: uppercase; }
.menu-btn .mb-sub { display: block; font-size: 10px; letter-spacing: .5px; color: var(--dim); margin-top: 2px; font-weight: 600; }
.menu-btn .mb-tag { font-size: 9px; font-weight: 800; letter-spacing: 1.5px; padding: 4px 7px; border: 1px solid rgba(255,122,26,.4); color: var(--orange); background: rgba(255,122,26,.08); text-transform: uppercase; }
.menu-btn.primary { background: linear-gradient(100deg, rgba(255,122,26,.92), rgba(227,75,12,.86)); border-color: rgba(255,170,90,.7); color: #fff; box-shadow: 0 8px 32px rgba(255, 100, 20, .18); }
.menu-btn.primary .mb-icon { background: rgba(0,0,0,.16); border-color: rgba(255,255,255,.28); color: #fff; }
.menu-btn.primary .mb-sub { color: rgba(255,255,255,.72); }
.menu-btn.primary:hover { background: linear-gradient(100deg, #ff8b35, #f0530c); border-color: #ffc08a; }
.menu-btn.primary::after { background: linear-gradient(90deg, rgba(255,255,255,.18), transparent 60%); }
.menu-btn.primary .mb-tag { border-color: rgba(255,255,255,.25); color: #fff; background: rgba(0,0,0,.15); }
.menu-btn.compact { padding: 10px 14px; }
.menu-btn.compact .mb-icon { width: 28px; height: 28px; flex-basis: 28px; }
.menu-btn.compact .mb-title { font-size: 13px; }

.home-right { position: relative; display: flex; flex-direction: column; justify-content: flex-end; align-items: flex-end; padding-bottom: 8px; }
.rank-mini {
  width: min(320px, 100%); padding: 16px 18px; background: var(--panel); border: 1px solid var(--line);
  backdrop-filter: blur(12px); position: relative;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}
.rank-mini-head { display: flex; justify-content: space-between; align-items: center; font-size: 9px; letter-spacing: 2.5px; color: var(--muted); font-weight: 800; margin-bottom: 10px; }
.rank-mini-body { display: flex; align-items: center; gap: 14px; }
.rank-emblem { width: 54px; height: 54px; flex: 0 0 54px; display: grid; place-items: center; position: relative; }
.rank-emblem svg { width: 100%; height: 100%; filter: drop-shadow(0 0 12px rgba(53,240,255,.4)); }
.rank-info { flex: 1; min-width: 0; }
.rank-name { font-family: var(--display); font-style: italic; font-size: 19px; letter-spacing: .5px; text-transform: uppercase; }
.rank-mmr { font-size: 10px; color: var(--muted); letter-spacing: 1px; font-weight: 700; margin-top: 2px; }
.rank-progress { height: 4px; background: rgba(255,255,255,.08); margin-top: 8px; overflow: hidden; }
.rank-progress i { display: block; height: 100%; background: linear-gradient(90deg, var(--cyan), #b9fbff); box-shadow: 0 0 10px var(--cyan); }
.home-footer { display: flex; align-items: center; gap: 18px; font-size: 10px; color: var(--dim); letter-spacing: .5px; flex-wrap: wrap; }
.home-footer .chip { display: inline-flex; align-items: center; gap: 6px; }
.home-footer .dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }

.profile-bar {
  display: flex; align-items: center; gap: 14px; padding: 10px 14px; background: rgba(8,14,25,.75);
  border: 1px solid var(--line); backdrop-filter: blur(10px); align-self: flex-start; flex-wrap: wrap;
}
.profile-avatar {
  width: 36px; height: 36px; border-radius: 8px; display: grid; place-items: center;
  background: linear-gradient(135deg, #123047, #0a1726); border: 1px solid rgba(53,240,255,.3);
  font-family: var(--display); font-style: italic; font-size: 15px; color: var(--cyan); flex: 0 0 36px;
}
.profile-meta { display: flex; flex-direction: column; gap: 1px; }
.profile-name { font-size: 12px; font-weight: 800; letter-spacing: .4px; }
.profile-level { font-size: 9px; color: var(--dim); font-weight: 700; letter-spacing: 1.2px; }
.profile-xp { width: 92px; height: 3px; background: rgba(255,255,255,.08); margin-top: 3px; }
.profile-xp i { display: block; height: 100%; background: var(--cyan); }
.profile-credits { margin-left: auto; display: flex; align-items: center; gap: 6px; padding: 6px 10px; background: rgba(255,206,77,.06); border: 1px solid rgba(255,206,77,.2); }
.profile-credits svg { width: 13px; height: 13px; }
.profile-credits b { font-size: 13px; color: var(--gold); letter-spacing: .5px; }
.profile-credits span { font-size: 8px; letter-spacing: 1.5px; color: rgba(255,206,77,.6); font-weight: 800; }

/* ---------- TOP BAR / PANEL SHELL ---------- */
.shell { position: relative; z-index: 2; height: 100%; display: flex; flex-direction: column; padding: clamp(16px, 2.5vw, 28px) clamp(16px, 3.5vw, 48px); gap: 18px; min-height: 0; }
.shell-head { display: flex; align-items: center; gap: 16px; flex-shrink: 0; }
.back-btn {
  width: 40px; height: 40px; flex: 0 0 40px; display: grid; place-items: center; color: var(--muted);
  border: 1px solid var(--line); background: rgba(9,15,26,.7); transition: all .2s;
  clip-path: polygon(0 0, 100% 0, 100% 70%, 70% 100%, 0 100%);
}
.back-btn:hover { color: #fff; border-color: var(--cyan); background: rgba(53,240,255,.08); }
.shell-title { display: flex; flex-direction: column; gap: 2px; flex: 1; min-width: 0; }
.shell-title h1 { font-family: var(--display); font-style: italic; font-size: clamp(22px, 3vw, 34px); letter-spacing: 1px; text-transform: uppercase; line-height: 1; }
.shell-title p { color: var(--muted); font-size: 10px; letter-spacing: 2.4px; font-weight: 700; text-transform: uppercase; }
.shell-head-right { display: flex; align-items: center; gap: 10px; }
.wallet-pill { display: flex; align-items: center; gap: 7px; padding: 8px 13px; background: rgba(8,14,25,.8); border: 1px solid rgba(255,206,77,.22); font-size: 12px; font-weight: 800; color: var(--gold); letter-spacing: .5px; }
.shell-body { flex: 1; min-height: 0; display: flex; flex-direction: column; }

/* cards */
.card {
  background: var(--panel); border: 1px solid var(--line); position: relative;
  backdrop-filter: blur(12px);
  clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 0 100%);
}
.card-pad { padding: 20px; }
.card-title { font-family: var(--display); font-style: italic; font-size: 13px; letter-spacing: 1.6px; text-transform: uppercase; color: #cfe4ff; display: flex; align-items: center; gap: 8px; }
.card-title::before { content: ""; width: 3px; height: 14px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.card-sub { font-size: 10.5px; color: var(--muted); margin-top: 5px; line-height: 1.5; }
.divider { height: 1px; background: var(--line); margin: 14px 0; }

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  padding: 12px 20px; font-family: var(--display); font-style: italic; font-size: 13px;
  letter-spacing: 1.1px; text-transform: uppercase; color: var(--text);
  background: rgba(20, 33, 52, 0.8); border: 1px solid rgba(120, 170, 230, 0.22);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  transition: all .2s;
}
.btn:hover { border-color: var(--cyan); background: rgba(53, 240, 255, 0.1); color: #fff; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn.primary { background: linear-gradient(100deg, #ff8a2e, #ea5a0c); border-color: rgba(255,170,110,.7); color: #fff; box-shadow: 0 6px 26px rgba(255, 100, 20, .22); }
.btn.primary:hover { background: linear-gradient(100deg, #ffa04d, #ff6a10); }
.btn.ghost { background: transparent; }
.btn.danger { border-color: rgba(255,69,96,.4); color: #ff8a9c; }
.btn.danger:hover { background: rgba(255,69,96,.12); border-color: #ff4560; }
.btn:disabled { opacity: .35; cursor: not-allowed; transform: none; }
.btn.sm { padding: 8px 13px; font-size: 11px; }
.btn.full { width: 100%; }
.btn .ic { width: 15px; height: 15px; }

/* ---------- PLAY SCREEN ---------- */
.play-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 1fr minmax(280px, 340px); gap: 16px; overflow: auto; align-content: start; }
.play-main { display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.mode-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.mode-card {
  position: relative; padding: 16px; text-align: left; background: rgba(9,16,28,.65);
  border: 1px solid var(--line); transition: all .22s; overflow: hidden; min-height: 112px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}
.mode-card:hover { border-color: rgba(120,220,255,.4); background: rgba(13,24,40,.8); transform: translateY(-2px); }
.mode-card.active { border-color: var(--cyan); background: linear-gradient(145deg, rgba(53,240,255,.12), rgba(8,16,28,.85)); box-shadow: inset 0 0 30px rgba(53,240,255,.06); }
.mode-card.active::after { content: ""; position: absolute; top: 0; left: 0; width: 100%; height: 2px; background: linear-gradient(90deg, var(--cyan), transparent); }
.mode-icon { width: 30px; height: 30px; display: grid; place-items: center; color: var(--cyan); margin-bottom: 10px; border: 1px solid rgba(53,240,255,.24); background: rgba(53,240,255,.06); }
.mode-icon svg { width: 16px; height: 16px; }
.mode-name { font-family: var(--display); font-style: italic; font-size: 14px; letter-spacing: .8px; text-transform: uppercase; }
.mode-desc { font-size: 10px; color: var(--muted); margin-top: 3px; line-height: 1.45; }
.mode-card .mode-check { position: absolute; top: 12px; right: 12px; width: 15px; height: 15px; border: 1px solid var(--line); border-radius: 50%; }
.mode-card.active .mode-check { border-color: var(--cyan); background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.mode-card.active .mode-check::after { content: ""; position: absolute; inset: 4px; background: #041018; border-radius: 50%; }

.opt-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.opt-label { font-size: 9px; letter-spacing: 2px; font-weight: 800; color: var(--muted); width: 76px; flex: 0 0 auto; text-transform: uppercase; }
.seg { display: flex; gap: 5px; flex-wrap: wrap; }
.seg button {
  padding: 8px 14px; font-size: 11px; font-weight: 800; letter-spacing: .8px; color: var(--muted);
  border: 1px solid var(--line); background: rgba(8,14,25,.6); transition: all .18s; text-transform: uppercase;
}
.seg button:hover { color: #fff; border-color: rgba(120,220,255,.4); }
.seg button.active { color: #041018; background: var(--cyan); border-color: var(--cyan); box-shadow: 0 0 16px rgba(53,240,255,.25); }
.seg.orange button.active { background: var(--orange); border-color: var(--orange); box-shadow: 0 0 16px rgba(255,122,26,.25); }
.opt-card { padding: 16px 18px; }

.play-side { display: flex; flex-direction: column; gap: 12px; }
.teams-lineup { display: flex; flex-direction: column; gap: 10px; }
.lineup-team { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.lineup-dot { width: 8px; height: 8px; border-radius: 50%; }
.lineup-dot.blue { background: var(--blue); box-shadow: 0 0 8px var(--blue); }
.lineup-dot.orange { background: var(--orange); box-shadow: 0 0 8px var(--orange); }
.lineup-label { font-size: 9px; font-weight: 800; letter-spacing: 1.5px; color: var(--muted); width: 64px; }
.lineup-chips { display: flex; gap: 5px; flex-wrap: wrap; }
.lineup-chip { font-size: 9.5px; font-weight: 700; padding: 4px 8px; border: 1px solid var(--line); color: #b8c9e0; background: rgba(255,255,255,.03); }
.lineup-chip.you { border-color: rgba(53,240,255,.45); color: var(--cyan); }
.lineup-chip.bot { color: var(--dim); }
.arena-preview {
  height: 104px; border: 1px solid var(--line); position: relative; overflow: hidden;
  background: linear-gradient(180deg, #0a2030, #071019);
}
.arena-preview .pitch {
  position: absolute; left: 50%; bottom: -26px; transform: translateX(-50%) perspective(300px) rotateX(52deg);
  width: 200px; height: 150px; border: 1px solid rgba(53,240,255,.4);
  background: repeating-linear-gradient(90deg, rgba(53,240,255,.06) 0 18px, transparent 18px 36px);
}
.arena-preview .pitch::after { content: ""; position: absolute; inset: 24px 34px; border: 1px solid rgba(53,240,255,.3); border-radius: 50%; }
.arena-preview .tag { position: absolute; top: 8px; left: 10px; font-size: 8px; letter-spacing: 2px; color: rgba(180,220,255,.7); font-weight: 800; }
.arena-preview .tag2 { position: absolute; bottom: 8px; right: 10px; font-size: 9px; letter-spacing: 1px; color: #9fd9ff; font-weight: 700; }
.select-input {
  width: 100%; padding: 10px 12px; background: rgba(8,14,25,.8); border: 1px solid var(--line);
  color: var(--text); font-size: 12px; outline: none;
}
.select-input:focus { border-color: var(--cyan); }
.input-field {
  width: 100%; padding: 11px 13px; background: rgba(6,11,20,.9); border: 1px solid var(--line);
  color: var(--text); font-size: 13px; outline: none; letter-spacing: 1px;
}
.input-field:focus { border-color: var(--cyan); box-shadow: 0 0 0 2px rgba(53,240,255,.08); }
.input-field::placeholder { color: #4d5a70; }

/* ---------- ONLINE ---------- */
.online-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 1.15fr .85fr; gap: 16px; overflow: auto; align-content: start; }
.online-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.online-card { padding: 20px; display: flex; flex-direction: column; gap: 12px; }
.online-card h3 { font-family: var(--display); font-style: italic; font-size: 16px; letter-spacing: .8px; text-transform: uppercase; }
.online-card p { font-size: 11px; color: var(--muted); line-height: 1.55; }
.room-code {
  font-family: var(--mono); font-size: 32px; letter-spacing: 8px; color: var(--cyan);
  text-align: center; padding: 14px; background: rgba(53,240,255,.05); border: 1px dashed rgba(53,240,255,.35);
  text-shadow: 0 0 22px rgba(53,240,255,.35); user-select: all;
}
.room-code.waiting { animation: pulseCode 1.8s ease-in-out infinite; }
@keyframes pulseCode { 50% { opacity: .5; } }
.code-input { font-family: var(--mono) !important; font-size: 24px !important; letter-spacing: 10px !important; text-align: center; text-transform: uppercase; }
.tips-list { display: flex; flex-direction: column; gap: 12px; }
.tip-item { display: flex; gap: 10px; font-size: 11px; color: var(--muted); line-height: 1.5; }
.tip-num { font-family: var(--display); font-style: italic; font-size: 13px; color: var(--orange); flex: 0 0 18px; }
.status-line { display: flex; align-items: center; gap: 8px; font-size: 10.5px; font-weight: 700; letter-spacing: 1px; color: var(--muted); padding: 9px 12px; background: rgba(255,255,255,.02); border: 1px solid var(--line); }
.status-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--dim); }
.status-dot.on { background: var(--green); box-shadow: 0 0 8px var(--green); animation: pulseDot 1.4s infinite; }
.status-dot.warn { background: var(--orange); box-shadow: 0 0 8px var(--orange); }
@keyframes pulseDot { 50% { opacity: .4; } }
.net-workout { background: rgba(255,122,26,.06); border: 1px solid rgba(255,122,26,.2); padding: 14px; }

/* ---------- GARAGE ---------- */
.garage-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(280px, 360px) 1fr; gap: 16px; overflow: hidden; }
.car-list { overflow-y: auto; display: flex; flex-direction: column; gap: 7px; padding-right: 6px; scrollbar-width: thin; scrollbar-color: rgba(53,240,255,.3) transparent; }
.car-list::-webkit-scrollbar { width: 5px; }
.car-list::-webkit-scrollbar-thumb { background: rgba(53,240,255,.25); }
.car-item {
  display: flex; align-items: center; gap: 11px; padding: 10px 12px; text-align: left;
  background: rgba(9, 16, 28, .6); border: 1px solid var(--line); transition: all .18s;
  clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 10px, 100% 100%, 0 100%);
}
.car-item:hover { border-color: rgba(120,220,255,.35); background: rgba(13,24,40,.8); }
.car-item.active { border-color: var(--cyan); background: linear-gradient(90deg, rgba(53,240,255,.12), rgba(9,16,28,.7)); }
.car-item.selected { border-color: rgba(255,122,26,.5); }
.car-swatch { width: 34px; height: 34px; flex: 0 0 34px; border-radius: 50%; position: relative; background: radial-gradient(circle at 35% 30%, var(--swatch-a), var(--swatch-b)); border: 2px solid rgba(255,255,255,.15); }
.car-item.active .car-swatch { border-color: var(--cyan); box-shadow: 0 0 14px rgba(53,240,255,.35); }
.car-swatch.locked { filter: grayscale(.8) brightness(.7); }
.car-item-main { flex: 1; min-width: 0; }
.car-item-name { font-size: 12px; font-weight: 800; letter-spacing: .3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.car-item-sub { font-size: 9px; color: var(--dim); letter-spacing: .7px; margin-top: 1px; text-transform: uppercase; font-weight: 700; }
.car-item-side { text-align: right; flex: 0 0 auto; }
.car-price { font-size: 10.5px; font-weight: 800; color: var(--gold); letter-spacing: .3px; }
.car-price.free { color: var(--green); }
.car-owned { font-size: 8.5px; color: var(--cyan); font-weight: 800; letter-spacing: 1px; }
.car-lock { font-size: 11px; opacity: .6; }
.garage-view { display: flex; flex-direction: column; gap: 12px; min-width: 0; min-height: 0; }
.preview-card { flex: 1; min-height: 240px; position: relative; display: flex; flex-direction: column; overflow: hidden; }
#car-preview-canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.preview-vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at 50% 45%, transparent 35%, rgba(4,7,12,.7) 100%); }
.preview-floor {
  position: absolute; left: 50%; bottom: 0; transform: translateX(-50%); width: 85%; height: 32%;
  background: radial-gradient(ellipse at 50% 100%, rgba(53,240,255,.16), transparent 70%);
  pointer-events: none;
}
.preview-badge { position: absolute; top: 14px; left: 16px; font-size: 8px; letter-spacing: 3px; font-weight: 800; color: rgba(150,190,230,.65); }
.preview-rarity { position: absolute; top: 12px; right: 14px; font-size: 9px; font-weight: 800; letter-spacing: 1.5px; padding: 4px 8px; border: 1px solid currentColor; }
.preview-name { position: absolute; left: 18px; bottom: 14px; }
.preview-name h2 { font-family: var(--display); font-style: italic; font-size: clamp(26px, 3.4vw, 44px); letter-spacing: -.5px; line-height: .9; text-transform: uppercase; text-shadow: 0 6px 30px rgba(0,0,0,.6); }
.preview-name p { font-size: 9.5px; letter-spacing: 2.5px; color: var(--muted); font-weight: 800; margin-top: 4px; text-transform: uppercase; }
.preview-actions { position: absolute; right: 16px; bottom: 16px; display: flex; gap: 8px; align-items: center; }
.garage-detail { display: grid; grid-template-columns: 1.2fr 1fr; gap: 12px; }
.stat-list { display: flex; flex-direction: column; gap: 9px; }
.stat-row { display: flex; align-items: center; gap: 10px; }
.stat-name { font-size: 9px; letter-spacing: 1.2px; font-weight: 800; color: var(--muted); width: 66px; text-transform: uppercase; }
.stat-track { flex: 1; height: 5px; background: rgba(255,255,255,.06); overflow: hidden; position: relative; }
.stat-track i { display: block; height: 100%; background: linear-gradient(90deg, rgba(53,240,255,.4), var(--cyan)); box-shadow: 0 0 8px rgba(53,240,255,.4); transition: width .5s cubic-bezier(.2,.8,.2,1); }
.stat-val { font-size: 9px; font-weight: 800; color: #b8cce4; width: 22px; text-align: right; }
.garage-buy { display: flex; flex-direction: column; justify-content: space-between; gap: 10px; }
.price-big { font-family: var(--display); font-style: italic; font-size: 26px; color: var(--gold); letter-spacing: .5px; display: flex; align-items: baseline; gap: 5px; }
.price-big small { font-family: var(--body); font-size: 8px; letter-spacing: 2px; color: var(--dim); font-style: normal; font-weight: 800; }
.price-big.free { color: var(--green); }
.hint-text { font-size: 9.5px; color: var(--dim); line-height: 1.5; }
.owned-tag { display: inline-flex; align-items: center; gap: 5px; font-size: 9px; letter-spacing: 1.5px; font-weight: 800; color: var(--cyan); }

/* ---------- LEADERBOARD ---------- */
.board-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 1fr minmax(260px, 320px); gap: 16px; overflow: hidden; }
.board-card { display: flex; flex-direction: column; overflow: hidden; }
.board-tabs { display: flex; gap: 0; border-bottom: 1px solid var(--line); flex-shrink: 0; }
.board-tab { padding: 13px 18px; font-size: 10px; font-weight: 800; letter-spacing: 1.5px; color: var(--muted); border-bottom: 2px solid transparent; text-transform: uppercase; }
.board-tab.active { color: var(--cyan); border-bottom-color: var(--cyan); background: rgba(53,240,255,.04); }
.board-table { flex: 1; overflow-y: auto; padding: 6px 10px 12px; }
.board-row { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-bottom: 1px solid rgba(255,255,255,.04); transition: background .2s; }
.board-row:hover { background: rgba(53,240,255,.035); }
.board-row.me { background: linear-gradient(90deg, rgba(53,240,255,.12), transparent); border-left: 2px solid var(--cyan); }
.board-rank { font-family: var(--display); font-style: italic; font-size: 14px; color: var(--dim); width: 30px; flex: 0 0 30px; text-align: center; }
.board-row.me .board-rank { color: var(--cyan); }
.board-row:nth-child(1) .board-rank { color: var(--gold); }
.board-row:nth-child(2) .board-rank { color: #cfd8e5; }
.board-row:nth-child(3) .board-rank { color: #d08a55; }
.board-name { flex: 1; min-width: 0; font-size: 12px; font-weight: 700; letter-spacing: .2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.board-tier { font-size: 8.5px; letter-spacing: 1px; color: var(--muted); font-weight: 800; text-transform: uppercase; }
.board-mmr { font-family: var(--mono); font-size: 12px; font-weight: 700; color: #b7d6f0; width: 52px; text-align: right; flex: 0 0 52px; }
.board-mmr small { font-size: 8px; color: var(--dim); }
.board-side { display: flex; flex-direction: column; gap: 12px; overflow-y: auto; }
.my-rank-card { text-align: center; padding: 22px 18px; }
.my-rank-emblem { width: 92px; height: 92px; margin: 4px auto 10px; }
.my-rank-emblem svg { width: 100%; height: 100%; filter: drop-shadow(0 0 22px rgba(53,240,255,.35)); }
.my-rank-title { font-family: var(--display); font-style: italic; font-size: 22px; letter-spacing: .5px; text-transform: uppercase; }
.my-rank-mmr { font-family: var(--mono); color: var(--cyan); font-size: 12px; margin-top: 3px; }
.my-rank-next { font-size: 9.5px; color: var(--dim); margin-top: 10px; letter-spacing: .5px; }
.progress-wide { height: 6px; background: rgba(255,255,255,.08); margin-top: 8px; overflow: hidden; }
.progress-wide i { display: block; height: 100%; background: linear-gradient(90deg, var(--cyan), #b9fbff); box-shadow: 0 0 12px rgba(53,240,255,.5); transition: width .6s; }
.profile-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.pstat { padding: 12px; background: rgba(255,255,255,.025); border: 1px solid var(--line); }
.pstat b { display: block; font-family: var(--display); font-style: italic; font-size: 21px; letter-spacing: .5px; }
.pstat span { font-size: 8.5px; letter-spacing: 1.3px; color: var(--dim); font-weight: 800; text-transform: uppercase; }

/* ---------- SETTINGS ---------- */
.settings-layout { flex: 1; min-height: 0; overflow-y: auto; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-content: start; }
.setting-item { display: flex; flex-direction: column; gap: 9px; padding: 15px 0; border-bottom: 1px solid rgba(255,255,255,.05); }
.setting-item:last-child { border-bottom: none; }
.setting-top { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.setting-name { font-size: 12px; font-weight: 700; }
.setting-hint { font-size: 9.5px; color: var(--dim); margin-top: 2px; }
input[type=range] { -webkit-appearance: none; width: 100%; height: 4px; background: rgba(255,255,255,.1); outline: none; }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 15px; height: 15px; background: var(--cyan); border-radius: 50%; cursor: pointer; box-shadow: 0 0 10px rgba(53,240,255,.6); }
input[type=range]::-moz-range-thumb { width: 15px; height: 15px; background: var(--cyan); border: none; border-radius: 50%; cursor: pointer; }
.control-table { display: grid; grid-template-columns: auto 1fr; gap: 9px 14px; font-size: 11px; align-items: center; }
.control-table kbd {
  display: inline-block; padding: 4px 7px; font-family: var(--mono); font-size: 10px; color: #cfe6ff;
  background: rgba(255,255,255,.05); border: 1px solid rgba(255,255,255,.14); border-bottom-width: 2px; border-radius: 4px;
  min-width: 26px; text-align: center;
}
kbd { font-family: var(--mono); }

/* ---------- HOW TO ---------- */
.howto-grid { flex: 1; min-height: 0; overflow-y: auto; display: grid; grid-template-columns: 1.1fr .9fr; gap: 16px; align-content: start; }
.howto-card { padding: 20px; }
.howto-card h3 { font-family: var(--display); font-style: italic; font-size: 14px; letter-spacing: 1px; margin-bottom: 12px; text-transform: uppercase; }
.howto-list { display: flex; flex-direction: column; gap: 13px; }
.howto-item { display: flex; gap: 12px; }
.howto-ic { width: 32px; height: 32px; flex: 0 0 32px; display: grid; place-items: center; color: var(--cyan); background: rgba(53,240,255,.06); border: 1px solid rgba(53,240,255,.2); }
.howto-ic svg { width: 16px; height: 16px; }
.howto-item b { font-size: 11.5px; display: block; margin-bottom: 2px; }
.howto-item p { font-size: 10.5px; color: var(--muted); line-height: 1.5; }
.tip-card { border-left: 2px solid var(--orange); background: rgba(255,122,26,.05); padding: 14px 16px; margin-top: 12px; }
.tip-card b { color: var(--orange); font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; display: block; margin-bottom: 4px; }
.tip-card p { font-size: 10.5px; color: #c9b6a4; line-height: 1.55; }

/* ---------- RESULTS / PAUSE / OVERLAYS ---------- */
.overlay {
  position: absolute; inset: 0; z-index: 60; display: flex; align-items: center; justify-content: center;
  padding: 20px; background: radial-gradient(ellipse at 50% 40%, rgba(9,20,36,.55), rgba(2,5,10,.86));
  backdrop-filter: blur(6px); opacity: 0; visibility: hidden; transition: opacity .35s, visibility .35s;
}
.overlay.active { opacity: 1; visibility: visible; }
.result-card {
  width: min(560px, 100%); background: linear-gradient(160deg, rgba(14,24,40,.97), rgba(6,11,19,.98));
  border: 1px solid rgba(120,180,235,.25); position: relative; padding: 26px 28px 24px;
  box-shadow: var(--shadow); transform: translateY(14px) scale(.98); transition: transform .4s cubic-bezier(.2,.9,.2,1);
  clip-path: polygon(0 0, calc(100% - 28px) 0, 100% 28px, 100% 100%, 0 100%);
}
.overlay.active .result-card { transform: none; }
.result-card::before { content: ""; position: absolute; top: 0; left: 0; width: 60%; height: 2px; background: linear-gradient(90deg, var(--cyan), transparent); }
.result-top { display: flex; justify-content: space-between; align-items: flex-start; }
.result-eyebrow { font-size: 9px; letter-spacing: 3px; font-weight: 800; color: var(--muted); text-transform: uppercase; }
.result-title { font-family: var(--display); font-style: italic; font-size: clamp(38px, 6vw, 54px); line-height: .9; letter-spacing: -1px; text-transform: uppercase; margin-top: 4px; }
.result-title.win { background: linear-gradient(90deg, #b9fbff, var(--cyan) 55%, #4cc9ff); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 0 24px rgba(53,240,255,.3)); }
.result-title.loss { background: linear-gradient(90deg, #ffd2d8, #ff6b7f 60%, #ff4560); -webkit-background-clip: text; background-clip: text; color: transparent; }
.result-title.draw { color: #d8e4f4; }
.result-score { font-family: var(--display); font-style: italic; font-size: 40px; display: flex; gap: 8px; align-items: center; letter-spacing: 1px; }
.result-score .b { color: #6fc4ff; } .result-score .o { color: #ffa45c; } .result-score .x { color: var(--dim); font-size: 22px; }
.result-tag { font-size: 10px; letter-spacing: 1.5px; color: var(--orange); font-weight: 800; }
.result-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 20px; }
.result-stat { display: flex; align-items: center; gap: 10px; padding: 11px 12px; background: rgba(255,255,255,.025); border: 1px solid var(--line); }
.result-stat .rs-ic { width: 30px; height: 30px; flex: 0 0 30px; display: grid; place-items: center; border: 1px solid rgba(255,206,77,.25); color: var(--gold); background: rgba(255,206,77,.05); }
.result-stat .rs-ic.cyan { color: var(--cyan); border-color: rgba(53,240,255,.25); background: rgba(53,240,255,.05); }
.result-stat .rs-ic svg { width: 15px; height: 15px; }
.result-stat b { display: block; font-size: 14px; }
.result-stat span { font-size: 8.5px; letter-spacing: 1.2px; color: var(--dim); font-weight: 700; }
.rank-delta { margin-top: 14px; padding: 14px; background: rgba(53,240,255,.035); border: 1px solid rgba(53,240,255,.16); }
.rank-delta-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.rank-delta-top .rd-label { font-size: 9px; letter-spacing: 2px; font-weight: 800; color: var(--muted); }
.rank-delta-top .rd-value { font-family: var(--display); font-style: italic; font-size: 18px; }
.rank-delta-top .rd-value.up { color: var(--green); }
.rank-delta-top .rd-value.down { color: var(--danger); }
.rank-track { height: 6px; background: rgba(255,255,255,.07); margin-top: 9px; position: relative; overflow: hidden; }
.rank-track .old { position: absolute; inset: 0 auto 0 0; background: rgba(255,255,255,.14); }
.rank-track .new { position: absolute; top: 0; bottom: 0; left: 0; background: linear-gradient(90deg, var(--cyan), #b9fbff); box-shadow: 0 0 12px rgba(53,240,255,.5); transition: width 1s cubic-bezier(.2,.8,.2,1); }
.rank-sub { display: flex; justify-content: space-between; font-size: 9px; color: var(--dim); margin-top: 6px; font-weight: 700; letter-spacing: .5px; }
.result-actions { display: flex; gap: 9px; margin-top: 18px; flex-wrap: wrap; }
.result-actions .btn { flex: 1; min-width: 120px; }
.level-up { margin-top: 10px; text-align: center; font-size: 10px; color: var(--gold); font-weight: 800; letter-spacing: 2px; text-transform: uppercase; display: none; }
