.pause-card { width: min(420px, 100%); text-align: center; }
.pause-card .result-title { font-size: 42px; }
.pause-menu { display: flex; flex-direction: column; gap: 8px; margin-top: 20px; }
.pause-menu .btn { width: 100%; }

/* ---------- TOASTS ---------- */
#toast-root { position: absolute; z-index: 90; right: 22px; top: 22px; display: flex; flex-direction: column; gap: 8px; pointer-events: none; }
.toast {
  min-width: 240px; max-width: 340px; padding: 12px 15px; background: rgba(10,17,29,.96);
  border: 1px solid rgba(120,200,255,.25); border-left: 3px solid var(--cyan);
  box-shadow: var(--shadow); animation: toastIn .35s cubic-bezier(.2,.9,.2,1);
  display: flex; gap: 10px; align-items: center;
}
.toast.gold { border-left-color: var(--gold); }
.toast.orange { border-left-color: var(--orange); }
.toast .t-icon { font-size: 17px; }
.toast b { display: block; font-size: 11.5px; letter-spacing: .2px; }
.toast span { font-size: 9.5px; color: var(--muted); line-height: 1.4; display: block; margin-top: 1px; }
.toast.out { animation: toastOut .3s forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateX(30px); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(30px); } }
@keyframes popIn { from { opacity: 0; transform: scale(.8); } }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; transition: opacity .3s; }
#hud.hidden { opacity: 0; visibility: hidden; }
.hud-top { position: absolute; top: max(16px, env(safe-area-inset-top)); left: 50%; transform: translateX(-50%); display: flex; align-items: flex-start; gap: 12px; padding: 0 16px; width: min(760px, 100%); }
.scoreboard {
  flex: 1; display: flex; align-items: stretch; justify-content: center; gap: 4px;
  background: linear-gradient(180deg, rgba(8,14,24,.9), rgba(8,14,24,.55));
  border: 1px solid rgba(120,170,230,.16); backdrop-filter: blur(8px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
  padding: 7px 12px;
}
.team-block { display: flex; align-items: center; gap: 9px; flex: 1; min-width: 0; }
.team-block.orange { justify-content: flex-end; }
.team-badge { width: 30px; height: 30px; flex: 0 0 30px; display: grid; place-items: center; font-family: var(--display); font-style: italic; font-size: 13px; border: 1px solid; }
.team-block.blue .team-badge { color: #6fc4ff; border-color: rgba(70,160,255,.45); background: rgba(43,140,255,.1); text-shadow: 0 0 10px rgba(70,160,255,.5); }
.team-block.orange .team-badge { color: #ffb271; border-color: rgba(255,140,60,.45); background: rgba(255,122,26,.1); text-shadow: 0 0 10px rgba(255,140,60,.5); }
.team-meta { display: flex; flex-direction: column; min-width: 0; }
