.team-block.blue .score { color: #8fd0ff; text-shadow: 0 0 20px rgba(70,160,255,.35); }
.team-block.orange .score { color: #ffb887; text-shadow: 0 0 20px rgba(255,140,60,.35); }
.clock-block { text-align: center; padding: 0 10px; display: flex; flex-direction: column; justify-content: center; min-width: 96px; }
.clock { font-family: var(--display); font-style: italic; font-size: 22px; letter-spacing: 1.5px; line-height: 1; }
.clock.overtime { color: var(--orange); animation: pulseCode 1.2s infinite; }
