  boostMax: 100,
  jumpImpulse: 13.2,
  doubleJumpImpulse: 9.6,
};

import * as THREE from 'three';
import { ARENA } from './constants.js';
import { radialGlowTexture } from './carModel.js';

function makeFieldTexture(theme) {
  const W = 1024;
  const H = 1536;
  const canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');
  const px = (x) => ((x / ARENA.halfW / 2) + 0.5) * W;
  const pz = (z) => ((z / ARENA.halfL / 2) + 0.5) * H;
  const sx = W / (ARENA.halfW * 2);
  const sz = H / (ARENA.halfL * 2);

  // base turf with mowing stripes
  ctx.fillStyle = theme.turfA;
  ctx.fillRect(0, 0, W, H);
  const stripe = 12;
  for (let z = -ARENA.halfL; z < ARENA.halfL; z += stripe * 2) {
    ctx.fillStyle = theme.turfB;
    ctx.fillRect(0, pz(z), W, stripe * sz);
  }
  // team tinted halves
  const blueGrad = ctx.createLinearGradient(0, pz(-ARENA.halfL), 0, pz(0));
  blueGrad.addColorStop(0, 'rgba(43,140,255,.12)');
  blueGrad.addColorStop(1, 'rgba(43,140,255,0)');
  ctx.fillStyle = blueGrad; ctx.fillRect(0, pz(-ARENA.halfL), W, H / 2);
  const orangeGrad = ctx.createLinearGradient(0, pz(ARENA.halfL), 0, pz(0));
  orangeGrad.addColorStop(0, 'rgba(255,106,16,.12)');
  orangeGrad.addColorStop(1, 'rgba(255,106,16,0)');
  ctx.fillStyle = orangeGrad; ctx.fillRect(0, pz(0), W, H / 2);

  // turf grain
  for (let i = 0; i < 9000; i++) {
    const gx = Math.random() * W;
    const gy = Math.random() * H;
    ctx.fillStyle = Math.random() > 0.5 ? 'rgba(255,255,255,.016)' : 'rgba(0,0,0,.05)';
    ctx.fillRect(gx, gy, 2 + Math.random() * 3, 1);
  }

  // faint hex grid
  ctx.strokeStyle = 'rgba(255,255,255,.025)';
  ctx.lineWidth = 1;
  for (let x = 0; x < W; x += 64) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();
  }
  for (let y = 0; y < H; y += 64) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
  }

  const lineColor = theme.line;
  ctx.strokeStyle = lineColor;
  ctx.fillStyle = lineColor;
  ctx.shadowColor = lineColor;
  ctx.shadowBlur = 10;
  ctx.lineWidth = 5;
  // boundary
  ctx.strokeRect(px(-ARENA.halfW + 1.5), pz(-ARENA.halfL + 1.5), (ARENA.halfW * 2 - 3) * sx, (ARENA.halfL * 2 - 3) * sz);
  ctx.lineWidth = 3;
  // midline
  ctx.beginPath(); ctx.moveTo(px(-ARENA.halfW), pz(0)); ctx.lineTo(px(ARENA.halfW), pz(0)); ctx.stroke();
  // center circle
  ctx.beginPath(); ctx.ellipse(px(0), pz(0), 13 * sx, 13 * sz, 0, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.ellipse(px(0), pz(0), 2 * sx, 2 * sz, 0, 0, Math.PI * 2); ctx.fill();

  // goal boxes
  for (const end of [-1, 1]) {
    const zEdge = end * ARENA.halfL;
    const zBox = end * (ARENA.halfL - 15);
    ctx.strokeRect(px(-19), pz(Math.min(zEdge, zBox)), 38 * sx, 15 * sz);
    ctx.strokeRect(px(-ARENA.goalHalfW - 2), pz(Math.min(zEdge, zEdge - end * 5)), (ARENA.goalHalfW * 2 + 4) * sx, 5 * sz);
    // penalty arc
    ctx.beginPath();
    ctx.ellipse(px(0), pz(end * (ARENA.halfL - 15)), 15 * sx, 8 * sz, 0, end > 0 ? Math.PI : 0, end > 0 ? Math.PI * 2 : Math.PI);
    ctx.stroke();
  }

  // corners
  for (const x of [-1, 1]) {
    for (const z of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(px(x * (ARENA.halfW - 1.5)), pz(z * (ARENA.halfL - 1.5)), 4 * sx, 4 * sz, 0, 0, Math.PI * 2);
      ctx.stroke();
    }
  }

  // center emblem
  ctx.save();
  ctx.translate(px(0), pz(0));
  ctx.globalAlpha = 0.78;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.shadowBlur = 24;
  ctx.font = 'italic 900 64px "Arial Black", Arial, sans-serif';
  ctx.fillStyle = lineColor;
  ctx.fillText('TURBO', 0, -28);
  ctx.fillText('STRIKE', 0, 40);
  ctx.font = '700 17px "Segoe UI", Arial, sans-serif';
  ctx.globalAlpha = 0.5;
  ctx.fillText('A R E N A   D E   C A R R O S', 0, 96);
  ctx.restore();

  // sideline labels
  ctx.save();
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = lineColor;
  ctx.font = '700 20px "Segoe UI", Arial, sans-serif';
  ctx.textAlign = 'center';
  for (const z of [-32, 32]) {
    ctx.save();
    ctx.translate(px(-ARENA.halfW + 4.5), pz(z));
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('TURBO STRIKE', 0, 0);
    ctx.restore();
  }
  ctx.restore();

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function makeGlowLineTexture(theme) {
  const W = 1024; const H = 1536;
  const canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000'; ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = theme.line;
  ctx.lineWidth = 3;
  ctx.globalAlpha = 0.7;
  const px = (x) => ((x / ARENA.halfW / 2) + 0.5) * W;
  const pz = (z) => ((z / ARENA.halfL / 2) + 0.5) * H;
  const sx = W / (ARENA.halfW * 2);
  const sz = H / (ARENA.halfL * 2);
  ctx.strokeRect(px(-ARENA.halfW + 1.5), pz(-ARENA.halfL + 1.5), (ARENA.halfW * 2 - 3) * sx, (ARENA.halfL * 2 - 3) * sz);
  ctx.beginPath(); ctx.moveTo(0, pz(0)); ctx.lineTo(W, pz(0)); ctx.stroke();
  ctx.beginPath(); ctx.ellipse(px(0), pz(0), 13 * sx, 13 * sz, 0, 0, Math.PI * 2); ctx.stroke();
  for (const end of [-1, 1]) {
    const zEdge = end * ARENA.halfL;
    const zBox = end * (ARENA.halfL - 15);
    ctx.strokeRect(px(-19), pz(Math.min(zEdge, zBox)), 38 * sx, 15 * sz);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function addGoal(scene, end, theme) {
  const group = new THREE.Group();
  const zLine = end * ARENA.halfL;
  const zBack = end * (ARENA.halfL + ARENA.goalDepth);
  const halfW = ARENA.goalHalfW;
  const h = ARENA.goalHeight;
  const teamColor = end > 0 ? '#ff8a2e' : '#35c8ff';
  const frameMat = new THREE.MeshStandardMaterial({
    color: '#dff6ff', metalness: 0.5, roughness: 0.3,
    emissive: new THREE.Color(teamColor), emissiveIntensity: 1.5,
  });
  const postGeo = new THREE.CylinderGeometry(0.36, 0.42, h + 1.2, 10);
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(postGeo, frameMat);
    post.position.set(side * halfW, (h + 1.2) / 2, zLine);
    group.add(post);
    const glide = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, ARENA.goalDepth, 8), frameMat);
    glide.rotation.x = Math.PI / 2;
    glide.position.set(side * halfW, h + 0.6, zLine + end * ARENA.goalDepth / 2);
    group.add(glide);
    const backPost = postGeo.clone();
    const bp = new THREE.Mesh(backPost, frameMat);
    bp.position.set(side * halfW, (h + 1.2) / 2, zBack);
    bp.scale.y = 0.92;
    group.add(bp);
  }
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.36, halfW * 2 + 0.8, 10), frameMat);
  bar.rotation.z = Math.PI / 2;
  bar.position.set(0, h + 1.2, zLine);
  group.add(bar);
  const backBar = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.28, halfW * 2 + 0.4, 8), frameMat);
  backBar.rotation.z = Math.PI / 2;
  backBar.position.set(0, h + 0.3, zBack);
  group.add(backBar);
  for (const side of [-1, 1]) {
    const topRail = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, ARENA.goalDepth, 8), frameMat);
    topRail.rotation.x = Math.PI / 2;
    topRail.position.set(side * halfW, h + 0.4, zLine + end * ARENA.goalDepth / 2);
    group.add(topRail);
  }

  // net lines
  const netMat = new THREE.LineBasicMaterial({ color: teamColor, transparent: true, opacity: 0.2 });
  const netGeo = new THREE.BufferGeometry();
  const verts = [];
  const step = 1.8;
  for (let x = -halfW; x <= halfW; x += step) {
    verts.push(x, 0.5, zBack, x, h, zBack);
    verts.push(x, h, zBack, x, h, zLine);
  }
  for (let y = 0.5; y <= h; y += step) {
    verts.push(-halfW, y, zBack, halfW, y, zBack);
    verts.push(-halfW, y, zLine, -halfW, y, zBack);
    verts.push(halfW, y, zLine, halfW, y, zBack);
  }
  for (let z = Math.min(zLine, zBack); z <= Math.max(zLine, zBack); z += step) {
    verts.push(-halfW, h, z, halfW, h, z);
  }
  netGeo.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  group.add(new THREE.LineSegments(netGeo, netMat));

  // goal back panel (dark, slight glow)
  const backPanel = new THREE.Mesh(
    new THREE.PlaneGeometry(halfW * 2 + 2, h + 1),
    new THREE.MeshStandardMaterial({
      color: '#060b14', transparent: true, opacity: 0.88, roughness: 0.8, metalness: 0.3,
      emissive: new THREE.Color(teamColor), emissiveIntensity: 0.12,
    }),
  );
  backPanel.position.set(0, h / 2 + 0.5, zBack + end * 0.03);
  if (end > 0) backPanel.rotation.y = Math.PI;
  group.add(backPanel);

  // goal ground glow
  const glow = new THREE.Mesh(
    new THREE.PlaneGeometry(halfW * 2 + 8, 10),
    new THREE.MeshBasicMaterial({
      map: radialGlowTexture(teamColor), color: teamColor, transparent: true, opacity: 0.22,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }),
  );
  glow.rotation.x = -Math.PI / 2;
  glow.position.set(0, 0.06, zLine + end * 3);
  group.add(glow);

  scene.add(group);
  return group;
}

function buildStands(theme) {
  const group = new THREE.Group();
  const crowdColors = ['#29425c', '#5c3a2a', '#2a4f4a', '#4b3b6b', '#777f8c', '#2b8cff', '#ff6a10', '#a8c4e0'];
  const palette = crowdColors.map((c) => new THREE.Color(c));
  const positions = [];
  const colors = [];
  const tierMat = new THREE.MeshStandardMaterial({ color: theme.stand, roughness: 0.85, metalness: 0.15 });
  const rows = 5;
  const pushCrowd = (x, y, z, rotation) => {
    positions.push({ x, y, z, rotation, s: 0.42 + Math.random() * 0.22 });
    const c = palette[Math.floor(Math.random() * palette.length)].clone();
    c.multiplyScalar(0.55 + Math.random() * 0.8);
    colors.push(c);
  };

  // side stands (left/right of field)
  for (const side of [-1, 1]) {
    for (let row = 0; row < rows; row++) {
      const x = side * (ARENA.halfW + 9 + row * 3.6);
      const y = 4 + row * 3.3;
      const tier = new THREE.Mesh(new THREE.BoxGeometry(3.6, 3.3, 150), tierMat);
      tier.position.set(x, y - 1.65, 0);
      group.add(tier);
      const strip = new THREE.Mesh(
        new THREE.BoxGeometry(0.18, 0.14, 150),
        new THREE.MeshBasicMaterial({ color: theme.accent, transparent: true, opacity: 0.28 }),
      );
      strip.position.set(x - side * 1.8, y + 0.02, 0);
      group.add(strip);
      for (let z = -71; z <= 71; z += 2.1) {
        if (Math.random() < 0.12) continue;
        pushCrowd(x - side * 0.2 + (Math.random() - 0.5) * 1.4, y + 0.55, z + (Math.random() - 0.5) * 0.8, side * -Math.PI / 2);
      }
    }
  }
  // end stands
  for (const end of [-1, 1]) {
    for (let row = 0; row < rows; row++) {
      const z = end * (ARENA.halfL + 9 + row * 3.6);
      const y = 4 + row * 3.3;
      const tier = new THREE.Mesh(new THREE.BoxGeometry(150, 3.3, 3.6), tierMat);
      tier.position.set(0, y - 1.65, z);
      group.add(tier);
      const strip = new THREE.Mesh(
        new THREE.BoxGeometry(150, 0.14, 0.18),
        new THREE.MeshBasicMaterial({ color: theme.accent, transparent: true, opacity: 0.28 }),
      );
      strip.position.set(0, y + 0.02, z - end * 1.8);
      group.add(strip);
      for (let x = -71; x <= 71; x += 2.1) {
        if (Math.random() < 0.12) continue;
        pushCrowd(x + (Math.random() - 0.5) * 0.8, y + 0.55, z - end * 0.2 + (Math.random() - 0.5) * 1.4, end > 0 ? Math.PI : 0);
      }
    }
  }

  const crowdGeo = new THREE.BoxGeometry(0.62, 1.1, 0.5);
  const crowdMat = new THREE.MeshStandardMaterial({ roughness: 0.9, metalness: 0.05 });
  const crowd = new THREE.InstancedMesh(crowdGeo, crowdMat, positions.length);
  const dummy = new THREE.Object3D();
  positions.forEach((p, i) => {
    dummy.position.set(p.x, p.y, p.z);
    dummy.rotation.set(0, p.rotation, 0);
    dummy.scale.setScalar(p.s * 1.5);
    dummy.updateMatrix();
    crowd.setMatrixAt(i, dummy.matrix);
    crowd.setColorAt(i, colors[i]);
  });
  crowd.instanceMatrix.needsUpdate = true;
  if (crowd.instanceColor) crowd.instanceColor.needsUpdate = true;
  group.add(crowd);

  // outer wall ring behind stands
  const outerMat = new THREE.MeshStandardMaterial({ color: '#050a11', roughness: 0.95, metalness: 0.2 });
  for (const side of [-1, 1]) {
    const wall = new THREE.Mesh(new THREE.BoxGeometry(2, 26, 170), outerMat);
    wall.position.set(side * (ARENA.halfW + 27), 13, 0);
    group.add(wall);
    const wall2 = new THREE.Mesh(new THREE.BoxGeometry(170, 26, 2), outerMat);
    wall2.position.set(0, 13, side * (ARENA.halfL + 27));
    group.add(wall2);
  }
  return group;
}

function buildFloodlights(theme) {
  const group = new THREE.Group();
  const metal = new THREE.MeshStandardMaterial({ color: '#1a2330', metalness: 0.7, roughness: 0.45 });
  const panelMat = new THREE.MeshStandardMaterial({
    color: '#ffffff', emissive: '#eaf7ff', emissiveIntensity: 3.2, roughness: 0.2,
  });
  for (const x of [-1, 1]) {
    for (const z of [-1, 1]) {
      const tower = new THREE.Group();
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.8, 34, 8), metal);
      pole.position.y = 17;
      tower.add(pole);
      const frame = new THREE.Mesh(new THREE.BoxGeometry(9, 3.4, 0.8), metal);
      frame.position.y = 33.5;
      tower.add(frame);
      for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 2; j++) {
          const lamp = new THREE.Mesh(new THREE.BoxGeometry(2.4, 1.1, 0.22), panelMat);
          lamp.position.set(-3 + i * 3, 32.8 + j * 1.3, x * z > 0 ? 0.45 : -0.45);
          lamp.lookAt(0, 0, 0);
          tower.add(lamp);
        }
      }
      const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
        map: radialGlowTexture('#dff8ff'), color: '#dff8ff', transparent: true, opacity: 0.35,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      sprite.scale.set(26, 26, 1);
      sprite.position.y = 33.5;
      tower.add(sprite);
      // beam cone toward center
      const beam = new THREE.Mesh(
        new THREE.ConeGeometry(17, 62, 16, 1, true),
        new THREE.MeshBasicMaterial({ color: theme.accent, transparent: true, opacity: 0.022, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
      );
      beam.position.y = 4;
      beam.rotation.x = Math.PI;
      tower.add(beam);
      tower.position.set(x * (ARENA.halfW + 26), 0, z * (ARENA.halfL + 26));
      group.add(tower);
    }
  }
  return group;
}

function buildSkyline(theme) {
  const group = new THREE.Group();
  const colors = ['#0b1a2a', '#0a1420', '#101b2b', '#0e2233'];
  for (let i = 0; i < 26; i++) {
    const angle = (i / 26) * Math.PI * 2 + Math.random() * 0.1;
    const radius = 150 + Math.random() * 60;
    const h = 20 + Math.random() * 60;
    const w = 10 + Math.random() * 16;
    const mat = new THREE.MeshStandardMaterial({ color: colors[i % colors.length], roughness: 0.9, metalness: 0.3, emissive: theme.accent, emissiveIntensity: 0.015 });
    const tower = new THREE.Mesh(new THREE.BoxGeometry(w, h, w), mat);
    tower.position.set(Math.cos(angle) * radius, h / 2 - 2, Math.sin(angle) * radius);
    tower.rotation.y = Math.random();
    group.add(tower);
    // window strips
    const stripMat = new THREE.MeshBasicMaterial({ color: i % 3 === 0 ? '#ffb26b' : theme.accent, transparent: true, opacity: 0.5 });
    for (let s = 0; s < 3; s++) {
      const strip = new THREE.Mesh(new THREE.BoxGeometry(w * 0.9, 0.3, 0.1), stripMat);
      strip.position.set(tower.position.x, 6 + Math.random() * (h - 12), tower.position.z + w / 2 + 0.06);
      group.add(strip);
    }
  }
  return group;
}

export class Arena {
  constructor(scene, theme) {
    this.scene = scene;
    this.theme = theme;
    this.group = new THREE.Group();
    this.group.name = 'arena';
    scene.add(this.group);
    this.screenCanvas = document.createElement('canvas');
    this.screenCanvas.width = 1024;
    this.screenCanvas.height = 360;
    this.screenCtx = this.screenCanvas.getContext('2d');
    this.screenTexture = new THREE.CanvasTexture(this.screenCanvas);
    this.screenTexture.colorSpace = THREE.SRGBColorSpace;
    this.screens = [];
    this.state = { blue: 0, orange: 0, time: 180, phase: 'countdown', overtime: false };
    this.build();
    this.updateScreens(this.state);
  }

  build() {
    const theme = this.theme;
    // floor
    const floorMat = new THREE.MeshStandardMaterial({
      map: makeFieldTexture(theme),
      roughness: 0.78,
      metalness: 0.15,
      emissive: new THREE.Color(theme.line),
      emissiveIntensity: 0.035,
      emissiveMap: makeGlowLineTexture(theme),
    });
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(ARENA.halfW * 2, ARENA.halfL * 2), floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0;
    this.group.add(floor);

    // outer apron
    const apron = new THREE.Mesh(
      new THREE.PlaneGeometry(240, 240),
      new THREE.MeshStandardMaterial({ color: '#05090f', roughness: 0.95, metalness: 0.2 }),
    );
    apron.rotation.x = -Math.PI / 2;
    apron.position.y = -0.06;
    this.group.add(apron);

    // glass walls / barriers
    const barrierMat = new THREE.MeshStandardMaterial({
      color: theme.line, transparent: true, opacity: 0.055, roughness: 0.1, metalness: 0.9,
      side: THREE.DoubleSide, depthWrite: false,
    });
    const trimMat = new THREE.MeshBasicMaterial({ color: theme.accent, transparent: true, opacity: 0.6 });
    const baseMat = new THREE.MeshStandardMaterial({ color: '#0c1622', metalness: 0.6, roughness: 0.5 });

    const addWall = (w, h, d, x, y, z) => {
      const glass = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), barrierMat);
      glass.position.set(x, y, z);
      this.group.add(glass);
      const base = new THREE.Mesh(new THREE.BoxGeometry(w, 1.5, d), baseMat);
      base.position.set(x, 0.75, z);
      this.group.add(base);
    };
    addWall(0.35, ARENA.wallH, ARENA.halfL * 2, -ARENA.halfW, ARENA.wallH / 2, 0);
    addWall(0.35, ARENA.wallH, ARENA.halfL * 2, ARENA.halfW, ARENA.wallH / 2, 0);
    for (const end of [-1, 1]) {
      const z = end * ARENA.halfL;
      const sideW = ARENA.halfW - ARENA.goalHalfW;
      addWall(sideW, ARENA.wallH, 0.35, -(ARENA.goalHalfW + sideW / 2), ARENA.wallH / 2, z);
      addWall(sideW, ARENA.wallH, 0.35, ARENA.goalHalfW + sideW / 2, ARENA.wallH / 2, z);
      addWall(ARENA.goalHalfW * 2, ARENA.wallH - ARENA.goalHeight, 0.35, 0, ARENA.goalHeight + (ARENA.wallH - ARENA.goalHeight) / 2, z);
    }

    // neon top trim
    const trimPieces = [
      [-ARENA.halfW, ARENA.wallH, 0, 0.24, 0.24, ARENA.halfL * 2],
      [ARENA.halfW, ARENA.wallH, 0, 0.24, 0.24, ARENA.halfL * 2],
    ];
    for (const [x, y, z, w, h, d] of trimPieces) {
      const trim = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), trimMat);
      trim.position.set(x, y, z);
      this.group.add(trim);
    }
    for (const end of [-1, 1]) {
      const trim = new THREE.Mesh(new THREE.BoxGeometry(ARENA.halfW * 2, 0.24, 0.24), trimMat);
      trim.position.set(0, ARENA.wallH, end * ARENA.halfL);
      this.group.add(trim);
    }
    // wall vertical ribs
    const ribMat = new THREE.MeshStandardMaterial({ color: '#16283a', metalness: 0.75, roughness: 0.35, emissive: theme.accent, emissiveIntensity: 0.05 });
    for (let z = -ARENA.halfL + 10; z <= ARENA.halfL - 10; z += 10) {
      for (const side of [-1, 1]) {
        const rib = new THREE.Mesh(new THREE.BoxGeometry(0.16, ARENA.wallH, 0.7), ribMat);
        rib.position.set(side * ARENA.halfW, ARENA.wallH / 2, z);
        this.group.add(rib);
      }
    }

    // goals
    addGoal(this.group, -1, theme);
    addGoal(this.group, 1, theme);

    // corner pylons
    for (const x of [-1, 1]) {
      for (const z of [-1, 1]) {
        const pylon = new THREE.Mesh(
          new THREE.CylinderGeometry(0.7, 1.1, ARENA.wallH + 3, 8),
          new THREE.MeshStandardMaterial({ color: '#14202e', metalness: 0.55, roughness: 0.4, emissive: theme.accent, emissiveIntensity: 0.12 }),
        );
        pylon.position.set(x * ARENA.halfW, (ARENA.wallH + 3) / 2, z * ARENA.halfL);
        this.group.add(pylon);
        const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.85, 0.85, 0.4, 8), trimMat);
        cap.position.set(x * ARENA.halfW, ARENA.wallH + 3, z * ARENA.halfL);
        this.group.add(cap);
      }
    }

    // stands + crowd
    this.group.add(buildStands(theme));
    this.group.add(buildFloodlights(theme));
    if (theme.id !== 'sunset') this.group.add(buildSkyline(theme));

    // big screens
    for (const end of [-1, 1]) {
      const screenMat = new THREE.MeshBasicMaterial({ map: this.screenTexture, toneMapped: false });
      const screen = new THREE.Mesh(new THREE.PlaneGeometry(30, 10.5), screenMat);
      screen.position.set(0, 21, end * (ARENA.halfL + 12));
      if (end > 0) screen.rotation.y = Math.PI;
      this.group.add(screen);
      const frame = new THREE.Mesh(
        new THREE.BoxGeometry(32.4, 12.6, 1),
        new THREE.MeshStandardMaterial({ color: '#0a111c', metalness: 0.7, roughness: 0.4, emissive: theme.accent, emissiveIntensity: 0.09 }),
      );
      frame.position.set(0, 21, end * (ARENA.halfL + 12.6));
      this.group.add(frame);
      const gl = new THREE.Sprite(new THREE.SpriteMaterial({
        map: radialGlowTexture(theme.accent), color: theme.accent, transparent: true, opacity: 0.18,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      gl.scale.set(44, 22, 1);
      gl.position.set(0, 21, end * (ARENA.halfL + 11));
      this.group.add(gl);
      this.screens.push(screen);
    }

    // sky dome
    const skyGeo = new THREE.SphereGeometry(420, 32, 18);
    const skyMat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(theme.skyTop) },
        bottom: { value: new THREE.Color(theme.skyBottom) },
      },
      vertexShader: `varying vec3 vPos; void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `varying vec3 vPos; uniform vec3 top; uniform vec3 bottom;
        void main(){ float h = clamp(normalize(vPos).y * 1.4 + 0.15, 0.0, 1.0); vec3 c = mix(bottom, top, pow(h, 0.75)); gl_FragColor = vec4(c, 1.0); }`,
    });
    const sky = new THREE.Mesh(skyGeo, skyMat);
    this.group.add(sky);
    this.sky = sky;

    if (theme.id === 'neon' || theme.id === 'frost') {
      const stars = new THREE.BufferGeometry();
      const starPos = [];
      for (let i = 0; i < 400; i++) {
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.random() * Math.PI * 0.42;
        const r = 380;
        starPos.push(Math.cos(theta) * Math.sin(phi) * r, Math.cos(phi) * r + 20, Math.sin(theta) * Math.sin(phi) * r);
      }
      stars.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
      this.group.add(new THREE.Points(stars, new THREE.PointsMaterial({ color: '#cfeeff', size: 1.5, transparent: true, opacity: 0.7, depthWrite: false, sizeAttenuation: true })));
    } else {
      const sun = new THREE.Mesh(
        new THREE.SphereGeometry(22, 20, 20),
        new THREE.MeshBasicMaterial({ color: '#ffd9a0', transparent: true, opacity: 0.9 }),
      );
      sun.position.set(-120, 55, -260);
      this.group.add(sun);
      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: radialGlowTexture('#ffb26b'), color: '#ffb26b', transparent: true, opacity: 0.35,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      halo.scale.set(160, 160, 1);
      halo.position.copy(sun.position);
      this.group.add(halo);
    }

    // ambient floating dust
    const dustGeo = new THREE.BufferGeometry();
    const dustPos = [];
    for (let i = 0; i < 160; i++) dustPos.push((Math.random() - 0.5) * 150, Math.random() * 30, (Math.random() - 0.5) * 150);
    dustGeo.setAttribute('position', new THREE.Float32BufferAttribute(dustPos, 3));
    this.dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
      color: theme.accent, size: 0.28, transparent: true, opacity: 0.35, depthWrite: false,
      blending: THREE.AdditiveBlending,
    }));
    this.group.add(this.dust);
  }

  updateScreens(state) {
    this.state = { ...this.state, ...state };
    const { blue, orange, time, phase, overtime } = this.state;
    const ctx = this.screenCtx;
    const W = this.screenCanvas.width;
    const H = this.screenCanvas.height;
    ctx.fillStyle = '#050b14';
    ctx.fillRect(0, 0, W, H);
    const grd = ctx.createLinearGradient(0, 0, W, H);
    grd.addColorStop(0, 'rgba(43,140,255,.28)');
    grd.addColorStop(0.5, 'rgba(5,11,20,0)');
    grd.addColorStop(1, 'rgba(255,106,16,.25)');
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, W, H);

    // frame lines
    ctx.strokeStyle = 'rgba(120,200,255,.28)';
    ctx.lineWidth = 3;
    ctx.strokeRect(10, 10, W - 20, H - 20);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'italic 900 46px "Arial Black", Arial, sans-serif';
    ctx.fillStyle = '#8fd0ff';
    ctx.fillText('AZUL', W * 0.22, 70);
    ctx.fillStyle = '#ffb887';
    ctx.fillText('LARANJA', W * 0.78, 70);
    ctx.font = 'italic 900 150px "Arial Black", Arial, sans-serif';
    ctx.fillStyle = '#eaf7ff';
    ctx.fillText(String(blue), W * 0.22, 200);
    ctx.fillText(String(orange), W * 0.78, 200);
    ctx.font = 'italic 700 52px "Arial Black", Arial, sans-serif';
    const m = Math.floor(Math.max(0, time) / 60);
    const s = Math.floor(Math.max(0, time) % 60);
    ctx.fillStyle = overtime ? '#ff8a2e' : '#bfe8ff';
    ctx.fillText(phase === 'ended' ? 'FIM' : overtime ? 'OT' : `${m}:${String(s).padStart(2, '0')}`, W / 2, 130);
    ctx.font = '700 24px "Segoe UI", Arial, sans-serif';
    ctx.fillStyle = 'rgba(160,200,235,.7)';
    ctx.fillText('TURBO STRIKE  •  ARENA DE CARROS', W / 2, 205);
    ctx.font = 'italic 900 30px "Arial Black", Arial, sans-serif';
    ctx.fillStyle = '#7fe4ff';
    ctx.fillText('VS', W / 2, 250);

    // bottom ticker
    ctx.fillStyle = 'rgba(53,240,255,.08)';
    ctx.fillRect(0, H - 58, W, 46);
    ctx.font = '700 20px "Segoe UI", Arial, sans-serif';
    ctx.fillStyle = 'rgba(200,235,255,.75)';
    ctx.fillText(overtime ? 'PRORROGAÇÃO — PRÓXIMO GOL VENCE' : phase === 'countdown' ? 'PREPARE-SE PARA O KICKOFF' : 'TURBO STRIKE • RANQUEADA ONLINE', W / 2, H - 35);
    this.screenTexture.needsUpdate = true;
  }

  update(dt, elapsed) {
    if (this.dust) {
      const pos = this.dust.geometry.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let y = pos.getY(i) + dt * (0.4 + (i % 5) * 0.12);
        if (y > 32) y = 0;
        pos.setY(i, y);
      }
      pos.needsUpdate = true;
      this.dust.rotation.y = elapsed * 0.004;
    }
    if (this.sky) this.sky.rotation.y = elapsed * 0.002;
  }

  dispose() {
    this.group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          if (m.map) m.map.dispose();
          m.dispose();
        }
      }
    });
    this.scene.remove(this.group);
  }
}

import * as THREE from 'three';
import { ARENA, PHYS } from './constants.js';
import { carPhysicalStats, BODY_DIMS } from '../data/cars.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const tmpV = new THREE.Vector3();
const tmpV2 = new THREE.Vector3();
const tmpQ = new THREE.Quaternion();
const tmpE = new THREE.Euler();
const tmpM = new THREE.Matrix4();

const BIG_PADS = [
  [-31, -42], [31, -42], [-31, 42], [31, 42], [0, -22], [0, 22],
];
const SMALL_PADS = [
  [-17, -30], [17, -30], [-17, 30], [17, 30],
  [-28, -8], [28, -8], [-28, 8], [28, 8],
  [-9, -16], [9, -16], [-9, 16], [9, 16],
  [-20, 0], [20, 0],
];

export function spawnPositions(teamSize) {
  const layouts = {
    1: [[[0, -31]], [[0, 31]]],
    2: [[[-7, -29], [7, -39]], [[7, 29], [-7, 39]]],
    3: [[[-12, -38], [0, -29], [12, -38]], [[12, 38], [0, 29], [-12, 38]]],
  };
  return layouts[teamSize] || layouts[1];
}

let nextId = 1;

export class World {
  constructor({
    carSetups = [],
    theme,
    mode = 'ai',
    duration = 180,
    teamSize = 1,
    onEvent = null,
    authorative = true,
  } = {}) {
    this.theme = theme;
    this.mode = mode;
    this.duration = duration;
    this.teamSize = teamSize;
    this.onEvent = onEvent;
    this.authorative = authorative && mode !== 'online-guest';
    this.elapsed = 0;
    this.events = [];
    this.phase = 'countdown';
    this.countdown = ARENA.kickoffTime;
    this.matchTime = duration;
    this.overtime = false;
    this.score = [0, 0];
    this.goalTimer = 0;
    this.lastScorer = null;
    this.winner = null;
    this.demo = mode === 'demo';
    this.finished = false;
    this.ball = {
      pos: new THREE.Vector3(0, ARENA.ballRadius + 0.05, 0),
      vel: new THREE.Vector3(),
      radius: ARENA.ballRadius,
      lastTouch: null,
      lastHitTime: -1,
      hitSeq: 0,
    };
    this.cars = [];
    this.pads = [];
    this.padLayout();
    this.spawnCars(carSetups);
    this.resetKickoff(true);
    this.controllers = new Map();
  }

  padLayout() {
    for (const [x, z] of BIG_PADS) {
      this.pads.push({ x, z, big: true, active: true, timer: 0, radius: 4.2, respawn: 10 });
    }
    for (const [x, z] of SMALL_PADS) {
      this.pads.push({ x, z, big: false, active: true, timer: 0, radius: 2.6, respawn: 4 });
    }
  }

  spawnCars(setups) {
    const layout = spawnPositions(this.teamSize);
    const counts = [0, 0];
    setups.forEach((setup, i) => {
      const team = setup.team ?? (i % 2);
      const spawns = layout[Math.min(this.teamSize, 3)];
      const slot = counts[team]++;
      const [x, z] = spawns[team][slot % spawns[team].length];
      const stats = carPhysicalStats(setup.def);
      const dims = BODY_DIMS[setup.def.style] || BODY_DIMS.octane;
      const car = {
        id: setup.id || `car-${nextId++}`,
        def: setup.def,
        stats,
        team,
        name: setup.name || 'Piloto',
        isBot: !!setup.isBot,
        isLocal: !!setup.isLocal,
        isGuest: !!setup.isGuest,
        difficulty: setup.difficulty || 2,
        pos: new THREE.Vector3(x, 0, z),
        vel: new THREE.Vector3(),
        quat: new THREE.Quaternion(),
        yaw: team === 0 ? 0 : Math.PI,
        pitch: 0,
        roll: 0,
        boost: 33,
        onGround: true,
        jumps: 0,
        stun: 0,
        respawnAt: 0,
        hidden: false,
        boostActive: false,
        drifting: false,
        wheelSpin: 0,
        flip: null,
        hitCooldown: 0,
        lastInput: { throttle: 0, steer: 0, boost: false, drift: false, jumpPressed: false, airRoll: 0 },
        dims,
        centerY: clamp(dims.h * 0.52, 0.7, 1.05),
        halfW: dims.w / 2 + 0.06,
        halfL: dims.l / 2 + 0.06,
        spawn: new THREE.Vector3(x, 0, z),
        goals: 0,
        touches: 0,
        demos: 0,
        surface: 'ground',
        ai: setup.ai || null,
        aiTimer: 0,
        _dirty: true,
      };
      car.quat.setFromEuler(tmpE.set(car.pitch, car.yaw, car.roll, 'YXZ'));
      this.cars.push(car);
    });
  }

  setController(carId, fn) {
    this.controllers.set(carId, fn);
  }

  getCar(id) {
    return this.cars.find((c) => c.id === id);
  }

  localCar() {
    return this.cars.find((c) => c.isLocal);
  }

  emit(event) {
    this.events.push(event);
    this.onEvent?.(event);
  }

  resetKickoff(initial = false) {
    const layout = spawnPositions(this.teamSize);
    const counts = [0, 0];
    const spawns = layout[Math.min(this.teamSize, 3)];
    for (const car of this.cars) {
      const slot = counts[car.team]++;
      const [x, z] = spawns[car.team][slot % spawns[car.team].length];
      car.pos.set(x, 0, z);
      car.spawn.set(x, 0, z);
      car.vel.set(0, 0, 0);
      car.yaw = car.team === 0 ? 0 : Math.PI;
      car.pitch = 0; car.roll = 0;
      car.quat.setFromEuler(tmpE.set(0, car.yaw, 0, 'YXZ'));
      car.boost = 33;
      car.onGround = true;
      car.jumps = 0;
      car.stun = 0;
      car.respawnAt = 0;
      car.hidden = false;
      car.flip = null;
      car.boostActive = false;
      car.drifting = false;
      car.hitCooldown = 0;
    }
    this.ball.pos.set(0, ARENA.ballRadius + 0.04, 0);
    this.ball.vel.set(0, 0, 0);
    this.ball.lastTouch = null;
    for (const pad of this.pads) { pad.active = true; pad.timer = 0; }
    this.phase = initial ? 'countdown' : 'countdown';
    this.countdown = initial ? ARENA.kickoffTime : 2.5;
    this.goalTimer = 0;
  }

  startOvertime() {
    this.overtime = true;
    this.matchTime = 0;
    this.phase = 'play';
    this.emit({ type: 'overtime' });
  }

  scoreGoal(team, scorer) {
    if (this.phase !== 'play') return;
    if (!this.authorative) return;
    this.score[team] += 1;
    const ownGoal = scorer && scorer.team !== team;
    this.lastScorer = { team, carId: scorer?.id || null, name: scorer?.name || '', ownGoal };
    if (scorer) scorer.goals += 1;
    this.phase = 'goal';
    this.goalTimer = 2.7;
    this.emit({ type: 'goal', team, scorer: this.lastScorer, overtime: this.overtime, ownGoal });
    this.ball.vel.multiplyScalar(0.35);
  }

  endMatch() {
    if (this.phase === 'ended') return;
    this.phase = 'ended';
    this.finished = true;
    this.winner = this.score[0] === this.score[1] ? null : (this.score[0] > this.score[1] ? 0 : 1);
    this.emit({ type: 'end', winner: this.winner, score: [...this.score], overtime: this.overtime });
  }

  step(dt) {
    dt = Math.min(dt, 1 / 30);
    this.elapsed += dt;
    if (this.phase === 'countdown') {
      const before = Math.ceil(this.countdown);
      this.countdown -= dt;
      const after = Math.ceil(this.countdown);
      if (after !== before && after >= 0) this.emit({ type: 'countdown', n: after });
      if (this.countdown <= 0) {
        this.phase = 'play';
        this.countdown = 0;
        this.emit({ type: 'go' });
        this.ball.vel.set((Math.random() - 0.5) * 1.5, 0, (Math.random() - 0.5) * 1.5);
      }
    } else if (this.phase === 'play') {
      if (!this.overtime) {
        this.matchTime -= dt;
        if (this.matchTime <= 0) {
          this.matchTime = 0;
          if (this.score[0] === this.score[1]) this.startOvertime();
          else this.endMatch();
        }
      }
    } else if (this.phase === 'goal') {
      this.goalTimer -= dt;
      if (this.goalTimer <= 0) {
        if (this.overtime) {
          this.endMatch();
        } else if (this.matchTime <= 0) {
          this.endMatch();
        } else {
          this.resetKickoff(false);
        }
      }
    }

    const canControl = this.phase === 'play' && !this.demo;
    for (const car of this.cars) {
      this.updateCar(car, dt, canControl);
    }
    if (this.phase !== 'countdown') this.updateBall(dt);
    this.carCarCollisions(dt);
    this.updatePads(dt);
    if (this.phase === 'play' && this.authorative) this.checkGoal();
  }

  updateCar(car, dt, canControl) {
    car._dirty = true;
    if (car.stun > 0) {
      car.stun -= dt;
      car.vel.y -= ARENA.gravity * dt;
      car.pos.addScaledVector(car.vel, dt);
      car.vel.multiplyScalar(1 - dt * 0.4);
      if (car.pos.y < 0) { car.pos.y = 0; car.vel.y = 0; }
      if (car.stun <= 0) this.respawnCar(car);
      car._dirty = true;
      this.integrateRotation(car, dt);
      return;
    }
    if (car.hidden) return;

    let input = car.lastInput;
    if (car.respawnAt > 0) return;
    const controller = this.controllers.get(car.id);
    if (controller && canControl) {
      const result = controller(car, this, dt);
      if (result) input = result;
    } else if (!canControl) {
      input = { throttle: 0, steer: 0, boost: false, drift: false, jumpPressed: false, airRoll: 0 };
    }
    car.lastInput = input;

    const forward = tmpV.set(Math.sin(car.yaw), 0, Math.cos(car.yaw));
    const right = tmpV2.set(Math.cos(car.yaw), 0, -Math.sin(car.yaw));
    const speedF = car.vel.x * forward.x + car.vel.z * forward.z;
    const speedR = car.vel.x * right.x + car.vel.z * right.z;
    car.boostActive = false;
    car.drifting = false;

    if (car.onGround) {
      // steering
      const steerBoost = input.drift ? 1.42 : 1;
      const speedFactor = clamp(Math.abs(speedF) / 7 + 0.08, 0.08, 1);
      const direction = speedF < -0.5 ? -1 : 1;
      car.yaw += (input.steer || 0) * 2.9 * car.stats.handling * steerBoost * speedFactor * direction * dt;
      car.yaw = ((car.yaw + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;

      // engine
      const throttle = input.throttle || 0;
      if (throttle !== 0) {
        const a = car.stats.accel * (throttle > 0 ? 1 : 0.66);
        car.vel.x += forward.x * throttle * a * dt;
        car.vel.z += forward.z * throttle * a * dt;
      }
      // boost
      if (input.boost && car.boost > 0) {
        car.boost = Math.max(0, car.boost - PHYS.boostConsume * dt);
        car.vel.x += forward.x * car.stats.boostPower * dt;
        car.vel.z += forward.z * car.stats.boostPower * dt;
        car.boostActive = true;
        if (Math.random() < dt * 22) this.emit({ type: 'exhaust', carId: car.id, team: car.team });
      }
      // tire grip
      const grip = input.drift ? 2.4 : 10;
      const gripFactor = Math.min(1, grip * dt);
      car.vel.x -= right.x * speedR * gripFactor;
      car.vel.z -= right.z * speedR * gripFactor;
      // drag
      const drag = 0.42 + Math.abs(speedF) * 0.006;
      car.vel.x *= 1 - drag * dt;
      car.vel.z *= 1 - drag * dt;
      // lateral drift detection
      if (input.drift && Math.abs(speedF) > 9) {
        car.drifting = true;
        if (Math.random() < dt * 30) this.emit({ type: 'drift', carId: car.id, pos: car.pos.clone() });
      }
      // speed limiter
      const maxSpeed = car.stats.topSpeed + (car.boostActive ? 7 : 0);
      const horiz = Math.hypot(car.vel.x, car.vel.z);
      if (horiz > maxSpeed) {
        const k = maxSpeed / horiz;
        car.vel.x *= k; car.vel.z *= k;
      }
      // jump
      if (input.jumpPressed) {
        car.vel.y = PHYS.jumpImpulse;
        car.onGround = false;
        car.jumps = 1;
        car.pitch = 0; car.roll = 0;
        this.emit({ type: 'jump', carId: car.id, pos: car.pos.clone(), team: car.team });
      }
      car.pitch *= 1 - Math.min(1, dt * 14);
      car.roll *= 1 - Math.min(1, dt * 14);
    } else {
      // airborne
      car.vel.y -= ARENA.gravity * dt;
      car.pitch += (input.throttle || 0) * 2.35 * dt;
      car.yaw += (input.steer || 0) * 1.7 * dt;
      if (input.airRoll) car.roll += input.airRoll * 2.8 * dt;
      else if (input.drift) car.roll -= (input.steer || 0) * 2.4 * dt;
      car.pitch = clamp(car.pitch, -1.25, 1.25);
      car.roll = clamp(car.roll, -1.35, 1.35);
      // boost with 3D direction
      const q = car.quat;
      const f3 = tmpV.set(0, 0, 1).applyQuaternion(q);
      if (input.boost && car.boost > 0) {
        car.boost = Math.max(0, car.boost - PHYS.boostConsume * dt);
        car.vel.addScaledVector(f3, car.stats.boostPower * 0.92 * dt);
        car.boostActive = true;
        if (Math.random() < dt * 26) this.emit({ type: 'exhaust', carId: car.id, team: car.team });
      }
      if (input.jumpPressed && car.jumps === 1 && !car.flip) {
        car.jumps = 2;
        const hasDir = Math.abs(input.throttle) > 0.2 || Math.abs(input.steer) > 0.2;
        if (hasDir) {
          const dir = tmpV2.set(0, 0, 1).applyQuaternion(car.quat).multiplyScalar(Math.max(0, input.throttle));
          const side = new THREE.Vector3(1, 0, 0).applyQuaternion(car.quat).multiplyScalar(-input.steer);
          dir.add(side);
          dir.y = 0;
          if (dir.lengthSq() < 0.01) dir.set(Math.sin(car.yaw), 0, Math.cos(car.yaw));
          dir.normalize();
          car.vel.addScaledVector(dir, 11.5);
          car.vel.y = Math.max(car.vel.y, 3.5);
          car.flip = { axis: Math.abs(input.steer) > Math.abs(input.throttle) ? 'z' : 'x', t: 0, dir: Math.sign(input.steer) || 1, duration: 0.42 };
          this.emit({ type: 'flip', carId: car.id, pos: car.pos.clone() });
        } else {
          car.vel.y += PHYS.doubleJumpImpulse;
          this.emit({ type: 'flip', carId: car.id, pos: car.pos.clone() });
        }
      }
      // faster alignment when not flipping
      car.pitch *= 1 - dt * 0.15;
      car.roll *= 1 - dt * 0.15;
    }

    car.pos.addScaledVector(car.vel, dt);
    this.collideCarArena(car);
    this.integrateRotation(car, dt);
    if (car.onGround) {
      car.pos.y = 0;
      car.vel.y = 0;
    }
    if (car.flip) {
      car.flip.t += dt;
      if (car.flip.t > car.flip.duration) car.flip = null;
    }
  }

  integrateRotation(car, dt) {
    car.quat.setFromEuler(tmpE.set(car.pitch, car.yaw, car.roll, 'YXZ'));
    const horiz = Math.hypot(car.vel.x, car.vel.z);
    car.wheelSpin += horiz * dt * 2.2;
    // landing detection handled by arena collision
  }

  collideCarArena(car) {
    const marginX = car.halfW;
    const marginL = car.halfL * 0.9;
    // side walls
    const limit = ARENA.halfW - marginX;
    if (car.pos.x > limit) { car.pos.x = limit; car.vel.x *= -0.22; }
    if (car.pos.x < -limit) { car.pos.x = -limit; car.vel.x *= -0.22; }
    // z walls / goals
    const inGoalX = Math.abs(car.pos.x) < ARENA.goalHalfW - 1.2;
    const inGoalHeight = car.pos.y < ARENA.goalHeight - 1.6;
    const zLimit = ARENA.halfL - marginL;
    if (car.pos.z > zLimit) {
      if (inGoalX && inGoalHeight) {
        const back = ARENA.halfL + ARENA.goalDepth - marginL;
        if (car.pos.z > back) { car.pos.z = back; car.vel.z *= -0.25; }
        const gx = ARENA.goalHalfW - 1.2;
        if (car.pos.x > gx) { car.pos.x = gx; car.vel.x *= -0.2; }
        if (car.pos.x < -gx) { car.pos.x = -gx; car.vel.x *= -0.2; }
      } else {
        car.pos.z = zLimit; car.vel.z *= -0.22;
      }
    }
    if (car.pos.z < -zLimit) {
      if (inGoalX && inGoalHeight) {
        const back = ARENA.halfL + ARENA.goalDepth - marginL;
        if (car.pos.z < -back) { car.pos.z = -back; car.vel.z *= -0.25; }
        const gx = ARENA.goalHalfW - 1.2;
        if (car.pos.x > gx) { car.pos.x = gx; car.vel.x *= -0.2; }
        if (car.pos.x < -gx) { car.pos.x = -gx; car.vel.x *= -0.2; }
      } else {
        car.pos.z = -zLimit; car.vel.z *= -0.22;
      }
    }
    // ground
    if (car.pos.y <= 0) {
      if (!car.onGround && car.vel.y < -8) {
        this.emit({ type: 'land', carId: car.id, power: -car.vel.y });
      }
      car.pos.y = 0;
      if (car.vel.y < 0) car.vel.y = 0;
      car.onGround = true;
      car.jumps = 0;
      car.pitch *= 0.4;
      car.roll *= 0.4;
    } else if (car.pos.y > 0.25) {
      car.onGround = false;
    }
    // ceiling
    if (car.pos.y > ARENA.height - 2) { car.pos.y = ARENA.height - 2; car.vel.y = Math.min(0, car.vel.y); }
    // carrier bounce off other surfaces
    if (car.pos.y < 0.02 && car.onGround) { car.pitch = 0; car.roll = 0; }
  }

  updateBall(dt) {
    const ball = this.ball;
    ball.vel.y -= ARENA.gravity * dt;
    ball.pos.addScaledVector(ball.vel, dt);
    const r = ball.radius;
    // floor
    if (ball.pos.y < r) {
      ball.pos.y = r;
      if (ball.vel.y < 0) {
        if (ball.vel.y < -3) this.emit({ type: 'ballBounce', power: -ball.vel.y, pos: ball.pos.clone() });
        ball.vel.y = -ball.vel.y * 0.62;
      }
      const friction = Math.exp(-1.1 * dt);
      ball.vel.x *= friction;
      ball.vel.z *= friction;
    }
    // ceiling
    if (ball.pos.y > ARENA.height - r) {
      ball.pos.y = ARENA.height - r;
      ball.vel.y = -Math.abs(ball.vel.y) * 0.6;
    }
    // side walls
    if (Math.abs(ball.pos.x) > ARENA.halfW - r) {
      const sign = Math.sign(ball.pos.x);
      ball.pos.x = sign * (ARENA.halfW - r);
      ball.vel.x = -ball.vel.x * 0.68;
      this.emit({ type: 'wallHit', power: Math.abs(ball.vel.x), pos: ball.pos.clone() });
    }
    const inGoalX = Math.abs(ball.pos.x) < ARENA.goalHalfW - r * 0.1;
    const inGoalY = ball.pos.y < ARENA.goalHeight - r * 0.1;
    // z ends
    for (const end of [-1, 1]) {
      const line = end * ARENA.halfL;
      const front = end * (ARENA.halfL - r);
      if ((ball.pos.z - front) * end < 0) continue;
      if (inGoalX && inGoalY) {
        // inside goal, handle net boundaries
        const back = end * (ARENA.halfL + ARENA.goalDepth - r);
        if ((ball.pos.z - back) * end > 0) {
          ball.pos.z = back;
          ball.vel.z *= -0.38;
        }
        if (Math.abs(ball.pos.x) > ARENA.goalHalfW - r) {
          const s = Math.sign(ball.pos.x);
          ball.pos.x = s * (ARENA.goalHalfW - r);
          ball.vel.x *= -0.4;
        }
        if (ball.pos.y > ARENA.goalHeight - r) {
          ball.pos.y = ARENA.goalHeight - r;
          ball.vel.y = -Math.abs(ball.vel.y) * 0.4;
        }
      } else {
        // bounced off wall beside/above goal
        if ((ball.pos.z - front) * end > 0) {
          ball.pos.z = front;
          ball.vel.z = -ball.vel.z * 0.66;
          this.emit({ type: 'wallHit', power: Math.abs(ball.vel.z), pos: ball.pos.clone() });
        }
      }
    }
    // clamp ball speed
    const speed = ball.vel.length();
    if (speed > PHYS.maxBallSpeed) ball.vel.multiplyScalar(PHYS.maxBallSpeed / speed);
    // ball-car collisions
    for (const car of this.cars) {
      if (car.hidden || car.stun > 0) continue;
      this.carBallCollision(car);
    }
    // ball spin visual
    ball.spin = ball.vel.length() * dt;
  }

  carBallCollision(car) {
    const ball = this.ball;
    const center = tmpV.set(car.pos.x, car.pos.y + car.centerY, car.pos.z);
    const rel = tmpV2.copy(ball.pos).sub(center);
    const inv = tmpQ.copy(car.quat).invert();
    rel.applyQuaternion(inv);
    const hw = car.halfW + ball.radius * 0.15;
    const hh = car.centerY + ball.radius * 0.05;
    const hl = car.halfL + ball.radius * 0.15;
    const closest = new THREE.Vector3(
      clamp(rel.x, -hw, hw),
      clamp(rel.y, -0.2, car.centerY + 0.55),
      clamp(rel.z, -hl, hl),
    );
    const delta = rel.clone().sub(closest);
    const dist = delta.length();
    if (dist > ball.radius) return;
    if (dist < 0.0001) delta.set(0, 1, 0);
    const normalLocal = delta.clone().normalize();
    const normal = normalLocal.clone().applyQuaternion(car.quat).normalize();
    const closestWorld = closest.clone().applyQuaternion(car.quat).add(center);
    const push = ball.radius - dist;
    ball.pos.addScaledVector(normal, push + 0.05);

    const now = this.elapsed;
    const carSpeed = car.vel.length();
    const relSpeed = ball.vel.clone().sub(car.vel);
    const closing = -relSpeed.dot(normal);
    const boostBonus = car.boostActive ? 6.5 : 0;
    const power = (3.8 + carSpeed * 0.62 + boostBonus) * (closing > 0 ? 1.08 : 0.8);
    ball.vel.addScaledVector(normal, power);
    ball.vel.addScaledVector(car.vel, 0.34);
    ball.vel.y += Math.max(0, power) * 0.12;

    const speed = ball.vel.length();
    if (speed > PHYS.maxBallSpeed) ball.vel.multiplyScalar(PHYS.maxBallSpeed / speed);
    if (ball.pos.y < ball.radius) { ball.pos.y = ball.radius; ball.vel.y = Math.abs(ball.vel.y) * 0.4; }

    if (car.hitCooldown <= 0 && now - ball.lastHitTime > 0.06) {
      const p = clamp(power / 16, 0.35, 1.7);
      ball.hitSeq += 1;
      car.hitCooldown = 0.14;
      ball.lastHitTime = now;
      car.touches += 1;
      ball.lastTouch = car;
      // save detection
      const ownGoalZ = car.team === 0 ? -ARENA.halfL : ARENA.halfL;
      const nearOwn = Math.abs(ball.pos.z - ownGoalZ) < 28;
      if (nearOwn && ball.vel.z * (car.team === 0 ? -1 : 1) > 9) {
        this.emit({ type: 'save', carId: car.id, team: car.team, pos: ball.pos.clone() });
      }
      this.emit({ type: 'hit', carId: car.id, team: car.team, power: p, pos: ball.pos.clone(), speed: ball.vel.length() });
    }
  }

  carCarCollisions() {
    for (let i = 0; i < this.cars.length; i++) {
      for (let j = i + 1; j < this.cars.length; j++) {
        const a = this.cars[i];
        const b = this.cars[j];
        if (a.hidden || b.hidden) continue;
        const pa = tmpV.set(a.pos.x, a.pos.y + a.centerY * 0.7, a.pos.z);
        const pb = tmpV2.set(b.pos.x, b.pos.y + b.centerY * 0.7, b.pos.z);
        const dx = pb.x - pa.x, dy = pb.y - pa.y, dz = pb.z - pa.z;
        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
        const minDist = 2.3;
        if (dist < minDist && dist > 0.001) {
          const nx = dx / dist, ny = dy / dist, nz = dz / dist;
          const overlap = minDist - dist;
          const relV = a.vel.x * nx + a.vel.y * ny + a.vel.z * nz - (b.vel.x * nx + b.vel.y * ny + b.vel.z * nz);
          if (a.stun <= 0 && b.stun <= 0) {
            if (a.boostActive && !b.boostActive && Math.abs(relV) > 27 && a.team !== b.team) {
              this.demolish(b, a);
            } else if (b.boostActive && !a.boostActive && Math.abs(relV) > 27 && a.team !== b.team) {
              this.demolish(a, b);
            } else {
              const imp = Math.max(0, relV) * 0.48;
              a.vel.x -= nx * imp * 0.6; a.vel.z -= nz * imp * 0.6;
              b.vel.x += nx * imp * 0.6; b.vel.z += nz * imp * 0.6;
              a.pos.x -= nx * overlap * 0.5; a.pos.z -= nz * overlap * 0.5;
              b.pos.x += nx * overlap * 0.5; b.pos.z += nz * overlap * 0.5;
              a.vel.y += Math.max(0, imp * 0.1);
              b.vel.y += Math.max(0, imp * 0.1);
              if (Math.abs(relV) > 6 && this.elapsed - (this.lastBump || 0) > 0.25) {
                this.lastBump = this.elapsed;
                this.emit({ type: 'bump', power: Math.abs(relV) / 30, pos: new THREE.Vector3((a.pos.x + b.pos.x) / 2, a.pos.y + 1, (a.pos.z + b.pos.z) / 2) });
              }
            }
          }
        }
      }
    }
  }

  demolish(victim, attacker) {
    if (victim.stun > 0) return;
    victim.stun = 2.1;
    victim.hidden = true;
    victim.vel.set(0, 9, 0);
    victim.boost = 0;
    attacker.demos += 1;
    this.emit({ type: 'demolish', carId: victim.id, attackerId: attacker.id, pos: victim.pos.clone(), team: victim.team, byTeam: attacker.team });
  }

  respawnCar(car) {
    car.hidden = false;
    car.stun = 0;
    car.vel.set(0, 0, 0);
    const z = car.team === 0 ? -ARENA.halfL + 14 : ARENA.halfL - 14;
    car.pos.set(car.team === 0 ? -8 : 8, 0, z);
    car.yaw = car.team === 0 ? 0 : Math.PI;
    car.pitch = 0; car.roll = 0;
    car.quat.setFromEuler(tmpE.set(0, car.yaw, 0, 'YXZ'));
    car.boost = 33;
    car.onGround = true;
    car.jumps = 0;
    car.flip = null;
  }

  updatePads(dt) {
    for (const pad of this.pads) {
      if (!pad.active) {
        pad.timer -= dt;
        if (pad.timer <= 0) { pad.active = true; pad.timer = 0; }
        continue;
      }
      for (const car of this.cars) {
        if (car.hidden || car.stun > 0) continue;
        const dx = car.pos.x - pad.x;
        const dz = car.pos.z - pad.z;
        if (dx * dx + dz * dz < pad.radius * pad.radius && car.pos.y < 2) {
          if (car.boost < PHYS.boostMax - 0.5) {
            car.boost = Math.min(PHYS.boostMax, car.boost + (pad.big ? 100 : 12));
            pad.active = false;
            pad.timer = pad.respawn;
            this.emit({ type: 'boost', carId: car.id, big: pad.big, pos: new THREE.Vector3(pad.x, 0.5, pad.z) });
          }
        }
      }
    }
  }

  checkGoal() {
    const ball = this.ball;
    if (Math.abs(ball.pos.z) < ARENA.halfL + ball.radius * 0.7) return;
    if (Math.abs(ball.pos.x) > ARENA.goalHalfW - 0.2) return;
    if (ball.pos.y > ARENA.goalHeight - 0.2) return;
    const scoringTeam = ball.pos.z > 0 ? 0 : 1;
    const scorer = ball.lastTouch;
    this.scoreGoal(scoringTeam, scorer);
  }

  getSnapshot(extra = {}) {
    return {
      t: this.matchTime,
      phase: this.phase,
      countdown: this.countdown,
      score: [...this.score],
      overtime: this.overtime,
      elapsed: this.elapsed,
      ball: {
        p: [this.ball.pos.x, this.ball.pos.y, this.ball.pos.z],
        v: [this.ball.vel.x, this.ball.vel.y, this.ball.vel.z],
      },
      cars: this.cars.map((c) => ({
        id: c.id,
        p: [c.pos.x, c.pos.y, c.pos.z],
        v: [c.vel.x, c.vel.y, c.vel.z],
        q: [c.quat.x, c.quat.y, c.quat.z, c.quat.w],
        yaw: c.yaw, pitch: c.pitch, roll: c.roll,
        boost: c.boost,
        hidden: c.hidden,
        stun: c.stun,
      })),
      pads: this.pads.map((p) => p.active),
      ...extra,
    };
  }

  applySnapshot(snap, localCarId, { hostInput = null, guestInputHandler = null } = {}) {
    if (!snap) return;
    if (snap.phase) this.phase = snap.phase;
    if (typeof snap.t === 'number' && !this.overtime) this.matchTime = snap.t;
    if (typeof snap.countdown === 'number') this.countdown = snap.countdown;
    if (snap.overtime) this.overtime = true;
    if (snap.score) {
      if (snap.score[0] !== this.score[0] || snap.score[1] !== this.score[1]) {
        this.score = [...snap.score];
      }
    }
    // ball correction
    if (snap.ball) {
      const target = tmpV.fromArray(snap.ball.p);
      const diff = target.distanceTo(this.ball.pos);
      if (diff > 0.03) {
        const k = diff > 2.5 ? 0.6 : 0.25;
        this.ball.pos.lerp(target, k);
        this.ball.vel.lerp(tmpV2.fromArray(snap.ball.v), diff > 2.5 ? 0.5 : 0.2);
      }
    }
    // cars
    if (snap.cars) {
      for (const data of snap.cars) {
        const car = this.cars.find((c) => c.id === data.id);
        if (!car) continue;
        if (car.isLocal && car.id === localCarId) {
          const target = tmpV.fromArray(data.p);
          const err = target.distanceTo(car.pos);
          if (err > 4.5) {
            car.pos.copy(target);
            car.vel.fromArray(data.v);
            car.yaw = data.yaw; car.pitch = data.pitch; car.roll = data.roll;
            car.quat.setFromEuler(tmpE.set(car.pitch, car.yaw, car.roll, 'YXZ'));
          } else if (err > 1.2) {
            car.pos.lerp(target, 0.05);
          }
          if (typeof data.boost === 'number' && Math.abs(car.boost - data.boost) > 8) car.boost = data.boost;
        } else if (!car.isBot || this.mode !== 'online-guest') {
          const target = tmpV.fromArray(data.p);
          const err = target.distanceTo(car.pos);
          if (err > 3.5) {
            car.pos.copy(target);
            car.vel.fromArray(data.v);
          } else {
            car.pos.lerp(target, 0.55);
            car.vel.lerp(tmpV2.fromArray(data.v), 0.45);
          }
          car.yaw = data.yaw; car.pitch = data.pitch; car.roll = data.roll;
          car.quat.setFromEuler(tmpE.set(car.pitch, car.yaw, car.roll, 'YXZ'));
          car.boost = data.boost;
          car.hidden = data.hidden;
          car.stun = data.stun;
          car.onGround = car.pos.y <= 0.1;
        } else {
          const target = tmpV.fromArray(data.p);
          car.pos.lerp(target, 0.5);
          car.vel.fromArray(data.v);
          car.yaw = data.yaw; car.pitch = data.pitch; car.roll = data.roll;
          car.quat.setFromEuler(tmpE.set(car.pitch, car.yaw, car.roll, 'YXZ'));
          car.hidden = data.hidden;
          car.boost = data.boost;
        }
      }
    }
    if (snap.pads && snap.pads.length === this.pads.length) {
      snap.pads.forEach((active, i) => {
        if (this.pads[i].active !== active) {
          this.pads[i].active = active;
          if (!active) this.pads[i].timer = this.pads[i].respawn;
        }
      });
    }
    if (hostInput) {
      const hostCar = this.cars.find((c) => !c.isLocal && !c.isBot);
      if (hostCar) hostCar.lastInput = hostInput;
    }
    this._dirty = true;
  }
}

import * as THREE from 'three';
import { ARENA } from './constants.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const wrap = (a) => {
  while (a > Math.PI) a -= Math.PI * 2;
  while (a < -Math.PI) a += Math.PI * 2;
  return a;
};

const DIFFICULTY = [
  { reaction: 0.34, noise: 0.42, boostChance: 0.28, aggression: 0.55, lead: 0.12, aerial: 0.15, speed: 0.82 },
  { reaction: 0.24, noise: 0.26, boostChance: 0.5, aggression: 0.72, lead: 0.2, aerial: 0.35, speed: 0.9 },
  { reaction: 0.15, noise: 0.14, boostChance: 0.72, aggression: 0.86, lead: 0.28, aerial: 0.6, speed: 0.96 },
  { reaction: 0.09, noise: 0.07, boostChance: 0.9, aggression: 0.95, lead: 0.36, aerial: 0.82, speed: 1 },
  { reaction: 0.05, noise: 0.03, boostChance: 1, aggression: 1, lead: 0.44, aerial: 1, speed: 1.04 },
];

export function difficultyLabel(level) {
  return ['Iniciante', 'Amador', 'Profissional', 'All-Star', 'Lenda'][clamp(level, 0, 4)];
}

export function makeBotController(difficulty = 2, role = 'attacker', seed = 0) {
  const cfg = DIFFICULTY[clamp(difficulty, 0, 4)];
  const rng = (() => {
    let s = (seed + 1) * 9301 + 49297;
    return () => { s = (s * 9301 + 49297) % 233280; return s / 233280; };
  })();
  const state = {
    timer: 0,
    target: new THREE.Vector3(),
    hasTarget: false,
    jumpCooldown: 0,
    mistake: 0,
    mistakeTimer: 3 + rng() * 4,
    padTarget: null,
    strafeDir: rng() > 0.5 ? 1 : -1,
  };

  return (car, world, dt) => {
    state.jumpCooldown = Math.max(0, state.jumpCooldown - dt);
    state.timer -= dt;
    state.mistakeTimer -= dt;
    if (state.mistakeTimer <= 0) {
      state.mistakeTimer = 3 + rng() * 4;
      state.mistake = rng() < 0.3 ? (rng() - 0.5) * cfg.noise * 8 : 0;
    }

    const ball = world.ball;
    const attackZ = car.team === 0 ? ARENA.halfL : -ARENA.halfL;
    const ownZ = car.team === 0 ? -ARENA.halfL : ARENA.halfL;
    const ownDir = Math.sign(ownZ);
    const ballDist = Math.hypot(ball.pos.x - car.pos.x, ball.pos.z - car.pos.z);
    const ballToOwn = Math.abs(ball.pos.z - ownZ);
    const danger = ballToOwn < 30 && ball.vel.z * ownDir < -4;
    const kickoff = Math.abs(ball.pos.z) < 2 && Math.abs(ball.vel.length()) < 2 && Math.abs(car.pos.z) > 20;
    const behindBall = (ball.pos.z - car.pos.z) * Math.sign(attackZ) < 0;

    if (state.timer <= 0) {
      state.timer = cfg.reaction * (0.7 + rng() * 0.6);
      const lead = clamp(ballDist / 34, 0.04, 0.65) * (0.35 + cfg.lead);
      const pred = new THREE.Vector3(
        ball.pos.x + ball.vel.x * lead,
        Math.max(ball.radius, ball.pos.y + ball.vel.y * lead * 0.5),
        ball.pos.z + ball.vel.z * lead,
      );
      const goal = new THREE.Vector3(0, 1.5, attackZ);
      const dirGoal = new THREE.Vector3(goal.x - pred.x, 0, goal.z - pred.z).normalize();
      const perp = new THREE.Vector3(-dirGoal.z, 0, dirGoal.x);

      let target = pred.clone().addScaledVector(dirGoal, -(ARENA.ballRadius + 3.1));

      // wrong side of the ball: swing around
      const carToBall = new THREE.Vector3(ball.pos.x - car.pos.x, 0, ball.pos.z - car.pos.z);
      const goalSide = carToBall.dot(dirGoal);
      if (goalSide > 0.5 && ballDist < 18) {
        target.addScaledVector(perp, state.strafeDir * (5 + ballDist * 0.35));
        target.x += state.strafeDir * 4;
      }

      // defensive positioning
      if (role === 'defender' || (role === 'attacker' && car.team === 0 && false)) {
        if (ballToOwn < 36) {
          target = new THREE.Vector3(
            clamp(ball.pos.x * 0.35, -9, 9),
            0,
            ownZ + Math.sign(ownZ) * -9,
          );
          if (ballToOwn < 18) {
            target = pred.clone().addScaledVector(
              new THREE.Vector3(0, 0, Math.sign(ownZ)),
              4,
            );
          }
        } else {
          target = pred.clone().addScaledVector(dirGoal, -7);
          target.x += (car.team === 0 ? -8 : 8);
        }
      }
      if (role === 'attacker' && world.teamSize > 1) {
        target.addScaledVector(perp, state.strafeDir * 2.5);
      }

      // grab boost when useful
      if (car.boost < 30 && ballDist > 14 && !danger) {
        let best = null;
        let bestD = 1e9;
        for (const pad of world.pads) {
          if (!pad.active) continue;
          const d = Math.hypot(pad.x - car.pos.x, pad.z - car.pos.z);
          const towardGoal = (pad.z - car.pos.z) * Math.sign(attackZ);
          if (d < bestD && d < 34 && towardGoal > -10) { bestD = d; best = pad; }
        }
        if (best && bestD < ballDist * 0.75) {
          target = new THREE.Vector3(best.x, 0, best.z);
          state.padTarget = best;
        } else state.padTarget = null;
      } else state.padTarget = null;

      if (kickoff) {
        const jitter = (rng() - 0.5) * 1.5;
        target = new THREE.Vector3(jitter, 0, 0);
      }

      target.x += state.mistake;
      target.z += state.mistake * 0.5;
      target.x = clamp(target.x, -ARENA.halfW + 3, ARENA.halfW - 3);
      target.z = clamp(target.z, -ARENA.halfL + 3, ARENA.halfL - 3);
      state.target.copy(target);
      state.hasTarget = true;
    }

    if (!state.hasTarget) state.target.set(0, 0, 0);
    const dx = state.target.x - car.pos.x;
    const dz = state.target.z - car.pos.z;
    const dist = Math.hypot(dx, dz);
    const desiredYaw = Math.atan2(dx, dz);
    const delta = wrap(desiredYaw - car.yaw);
    let steer = clamp(delta * 2.4, -1, 1);
    if (Math.abs(delta) > 0.08) steer += (rng() - 0.5) * cfg.noise * 0.4;
    steer = clamp(steer, -1, 1);

    let throttle = 1;
    if (dist < 2.2) throttle = 0.2;
    if (Math.abs(delta) > 1.35) throttle = 0.55;
    if (Math.abs(delta) > 2.2) throttle = 0.85;
    if (ball.pos.y > 6 && ballDist > 8) throttle = Math.min(1, throttle + 0.15);

    let boost = false;
    let jumping = false;
    let drift = false;

    const aligned = Math.abs(delta) < 0.42;
    if (aligned && car.boost > 5) {
      if (dist > 10) boost = rng() < cfg.boostChance;
      else if (ballDist > 7 && ballDist < 20 && rng() < cfg.boostChance * 0.7) boost = true;
    }
    if (kickoff && car.boost > 10 && aligned) boost = true;
    if (danger && car.boost > 20 && aligned) boost = true;

    // jump for aerial / flip into ball
    const ballHigh = ball.pos.y > 2.6;
    const closeToBall = ballDist < 6.8;
    if (closeToBall && aligned && car.onGround && state.jumpCooldown <= 0) {
      if (ballHigh && ball.pos.y < 13 && rng() < cfg.aerial) {
        jumping = true;
        state.jumpCooldown = 1.1;
      } else if (ballDist > 3.2 && ballDist < 6 && ball.pos.y < 4 && dist < 15) {
        // flip toward ball for a strong touch
        jumping = true;
        state.jumpCooldown = 0.9;
      }
    }
    if (!car.onGround && car.jumps === 1 && closeToBall && state.jumpCooldown <= 0) {
      jumping = true;
      state.jumpCooldown = 1.4;
    }
    if (Math.abs(delta) > 1.6 && car.onGround && car.vel.length() > 14) drift = true;
    if (car.onGround && state.padTarget && dist < 40 && car.boost < 90) drift = false;

    // aerial attitude: pitch toward ball height
    let airThrottle = 0;
    if (!car.onGround) {
      const dy = ball.pos.y - (car.pos.y + 1);
      airThrottle = clamp(dy * 0.2, -1, 1);
      if (car.pos.y > 1 && car.jumps === 1 && ball.pos.y > car.pos.y + 2 && car.boost > 12 && rng() < 0.5) {
        jumping = true;
        state.jumpCooldown = 1.5;
      }
      if (ball.pos.y > car.pos.y + 2 && car.boost > 8 && Math.abs(ball.pos.z - car.pos.z) < 18) boost = true;
    }

    return {
      throttle: car.onGround ? throttle : airThrottle,
      steer,
      boost,
      drift,
      jumpPressed: jumping,
      airRoll: 0,
    };
  };
}

import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { ARENA } from './constants.js';
import { createCarModel, radialGlowTexture } from './carModel.js';
import { Arena } from './arena.js';

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function makeBallTexture() {
  const W = 1024; const H = 512;
  const canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext('2d');
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#0a1520');
  bg.addColorStop(0.5, '#102434');
  bg.addColorStop(1, '#08121c');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);
  // hexagon tiling
  const hexR = 34;
  const hexW = Math.sqrt(3) * hexR;
  ctx.strokeStyle = 'rgba(140,240,255,.55)';
  ctx.lineWidth = 3;
  ctx.shadowColor = 'rgba(80,230,255,.8)';
  ctx.shadowBlur = 9;
  for (let row = -1; row < H / (hexR * 1.5) + 1; row++) {
    for (let col = -1; col < W / hexW + 1; col++) {
      const cx = col * hexW + (row % 2 ? hexW / 2 : 0);
      const cy = row * hexR * 1.5;
      ctx.beginPath();
      for (let i = 0; i < 6; i++) {
        const a = (Math.PI / 3) * i + Math.PI / 6;
        const x = cx + Math.cos(a) * hexR;
        const y = cy + Math.sin(a) * hexR;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.fillStyle = Math.random() > 0.5 ? 'rgba(40,110,150,.18)' : 'rgba(20,60,90,.22)';
      ctx.fill();
      ctx.stroke();
    }
  }
  ctx.shadowBlur = 0;
  // team bands
  ctx.fillStyle = 'rgba(53,200,255,.22)';
  ctx.fillRect(0, H * 0.08, W, 20);
  ctx.fillStyle = 'rgba(255,140,40,.2)';
  ctx.fillRect(0, H * 0.86, W, 20);
  // brand
  ctx.font = 'italic 900 80px "Arial Black", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(220,250,255,.5)';
  ctx.fillText('TURBO', W / 2, H / 2 - 10);
  ctx.fillStyle = 'rgba(255,180,100,.5)';
  ctx.fillText('STRIKE', W / 2, H / 2 + 75);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.anisotropy = 4;
  return tex;
}

function makeGlowTexture() {
  return radialGlowTexture('#ffffff');
}

class ParticleSystem {
  constructor(scene, count = 500) {
    this.count = count;
    this.pos = new Float32Array(count * 3);
    this.color = new Float32Array(count * 3);
    this.size = new Float32Array(count);
    this.alpha = new Float32Array(count);
    this.data = new Array(count).fill(null).map(() => ({ life: 0, maxLife: 1, vel: new THREE.Vector3(), grav: 0, drag: 0 }));
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.color, 3));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alpha, 1));
    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: {},
      vertexShader: `
        attribute float aSize; attribute float aAlpha; attribute vec3 aColor;
        varying vec3 vColor; varying float vAlpha;
        void main(){
          vColor = aColor; vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (260.0 / max(1.0, -mv.z));
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: `
        varying vec3 vColor; varying float vAlpha;
        void main(){
          float d = length(gl_PointCoord - vec2(0.5));
          if (d > 0.5) discard;
          float a = smoothstep(0.5, 0.06, d) * vAlpha;
          gl_FragColor = vec4(vColor, a);
        }`,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.geo = geo;
    this.cursor = 0;
    scene.add(this.points);
  }

  spawn({
    x, y, z, vx = 0, vy = 0, vz = 0, color = '#35f0ff', size = 2.2,
    life = 0.6, gravity = 0, drag = 0.9,
  }) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % this.count;
    const d = this.data[i];
    d.life = life; d.maxLife = life; d.grav = gravity; d.drag = drag;
    d.vel.set(vx, vy, vz);
    this.pos[i * 3] = x; this.pos[i * 3 + 1] = y; this.pos[i * 3 + 2] = z;
    const c = new THREE.Color(color);
    this.color[i * 3] = c.r; this.color[i * 3 + 1] = c.g; this.color[i * 3 + 2] = c.b;
    this.size[i] = size;
    this.alpha[i] = 1;
  }

  update(dt) {
    for (let i = 0; i < this.count; i++) {
      const d = this.data[i];
      if (d.life <= 0) { this.alpha[i] = 0; continue; }
      d.life -= dt;
      if (d.life <= 0) { this.alpha[i] = 0; continue; }
      d.vel.y -= d.grav * dt;
      const dragK = Math.pow(d.drag, dt * 60);
      d.vel.multiplyScalar(dragK);
      this.pos[i * 3] += d.vel.x * dt;
      this.pos[i * 3 + 1] += d.vel.y * dt;
      this.pos[i * 3 + 2] += d.vel.z * dt;
      const k = d.life / d.maxLife;
      this.alpha[i] = Math.min(1, k * 1.8);
      if (this.pos[i * 3 + 1] < 0.05) {
        this.pos[i * 3 + 1] = 0.05;
        d.vel.y *= -0.2;
      }
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}

export class Renderer {
  constructor(canvas, { quality = 'high' } = {}) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: quality !== 'low',
      powerPreference: 'high-performance',
      alpha: false,
    });
    this.quality = quality;
    this.setQuality(quality);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.12;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.1, 900);
    this.scene.fog = new THREE.FogExp2('#071322', 0.0032);
    this.scene.background = new THREE.Color('#050a12');

    const pmrem = new THREE.PMREMGenerator(this.renderer);
    const envScene = new RoomEnvironment();
    this.envMap = pmrem.fromScene(envScene, 0.04).texture;
    this.scene.environment = this.envMap;
    envScene.dispose?.();
    pmrem.dispose();

    // lights
    this.hemi = new THREE.HemisphereLight('#9fd4ff', '#0a1220', 1.15);
    this.scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight('#e6f7ff', 2.1);
    this.sun.position.set(-35, 60, 25);
    this.scene.add(this.sun);
    this.fill = new THREE.DirectionalLight('#ff9a5a', 0.55);
    this.fill.position.set(30, 24, -50);
    this.scene.add(this.fill);
    this.goalLightBlue = new THREE.PointLight('#35c8ff', 55, 70, 2);
    this.goalLightBlue.position.set(0, 12, -54);
    this.scene.add(this.goalLightBlue);
    this.goalLightOrange = new THREE.PointLight('#ff8a2e', 55, 70, 2);
    this.goalLightOrange.position.set(0, 12, 54);
    this.scene.add(this.goalLightOrange);

    this.arena = null;
    this.theme = null;
    this.world = null;
    this.carVisuals = new Map();
    this.particles = new ParticleSystem(this.scene, quality === 'low' ? 260 : 620);
    this.effects = [];
    this.cameraState = {
      mode: 'chase',
      menuAngle: 0,
      pos: new THREE.Vector3(0, 28, 100),
      look: new THREE.Vector3(0, 2, 0),
      shake: 0,
      fov: 70,
      goalFocus: 0,
      ballCam: true,
    };
    this.elapsed = 0;
    this.tmpQ = new THREE.Quaternion();
    this.tmpV = new THREE.Vector3();
    this.tmpV2 = new THREE.Vector3();
    this.ballTrailTimer = 0;
    this.boostTimers = new Map();
    this.onResize = () => this.resize();
    window.addEventListener('resize', this.onResize);
    this.resize();
    this.createBall();
  }

  setQuality(quality) {
    this.quality = quality;
    const dpr = window.devicePixelRatio || 1;
    const scale = quality === 'low' ? 1 : quality === 'medium' ? Math.min(dpr, 1.3) : Math.min(dpr, 1.8);
    this.renderer.setPixelRatio(scale);
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
  }

  resize() {
    if (!this.renderer) return;
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
  }

  setTheme(theme) {
    if (this.theme?.id === theme.id && this.arena) return;
    this.theme = theme;
    if (this.arena) this.arena.dispose();
    this.scene.fog = new THREE.FogExp2(theme.fog, 0.0034);
    this.scene.background = new THREE.Color(theme.skyTop);
    this.arena = new Arena(this.scene, theme);
    this.hemi.color.set(theme.ambient);
    this.hemi.groundColor.set(theme.fog);
    this.hemi.intensity = theme.id === 'sunset' ? 1.35 : 1.1;
    this.sun.color.set(theme.sun);
    this.sun.intensity = theme.id === 'sunset' ? 2.6 : 2.0;
    this.fill.intensity = theme.id === 'sunset' ? 0.9 : 0.5;
    this.scene.environmentIntensity = theme.id === 'sunset' ? 0.7 : 1.0;
  }

  createBall() {
    const group = new THREE.Group();
    const tex = makeBallTexture();
    const mat = new THREE.MeshStandardMaterial({
      map: tex,
      metalness: 0.55,
      roughness: 0.3,
      emissive: new THREE.Color('#8fe8ff'),
      emissiveMap: tex,
      emissiveIntensity: 0.5,
      envMapIntensity: 1.4,
    });
    const sphere = new THREE.Mesh(new THREE.SphereGeometry(ARENA.ballRadius, 40, 28), mat);
    group.add(sphere);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: makeGlowTexture(), color: '#6fe4ff', transparent: true, opacity: 0.38,
      blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    glow.scale.set(13, 13, 1);
    group.add(glow);
    // shadow
    const shadow = new THREE.Mesh(
      new THREE.PlaneGeometry(ARENA.ballRadius * 3.4, ARENA.ballRadius * 3.4),
      new THREE.MeshBasicMaterial({ map: makeGlowTexture(), color: '#000000', transparent: true, opacity: 0.5, depthWrite: false }),
    );
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = -ARENA.ballRadius + 0.06;
    group.add(shadow);
    const light = new THREE.PointLight('#7fe8ff', 26, 38, 2);
    light.position.y = 0;
    group.add(light);
    group.visible = false;
    this.scene.add(group);
    this.ballGroup = group;
    this.ballMesh = sphere;
    this.ballShadow = shadow;
    this.ballLight = light;
    this.ballTexture = tex;
  }

  loadWorld(world) {
    this.world = world;
    this.clearCars();
    this.setTheme(world.theme);
    this.ballGroup.visible = true;
    // pads
    if (this.padGroup) {
      this.scene.remove(this.padGroup);
      this.padGroup.traverse((o) => { o.geometry?.dispose(); o.material?.dispose?.(); });
    }
    this.padGroup = new THREE.Group();
    this.scene.add(this.padGroup);
    for (const pad of world.pads) {
      const g = new THREE.Group();
      const color = pad.big ? '#ffd23f' : '#35f0ff';
      const disc = new THREE.Mesh(
        new THREE.CircleGeometry(pad.big ? 3.0 : 1.7, pad.big ? 6 : 6),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }),
      );
      disc.rotation.x = -Math.PI / 2;
      disc.position.y = 0.08;
      g.add(disc);
      const ring = new THREE.Mesh(
        new THREE.RingGeometry(pad.big ? 3.0 : 1.7, pad.big ? 3.5 : 2.05, 24),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }),
      );
      ring.rotation.x = -Math.PI / 2;
      ring.position.y = 0.09;
      g.add(ring);
      const core = new THREE.Mesh(
        new THREE.CylinderGeometry(pad.big ? 0.22 : 0.12, pad.big ? 0.22 : 0.12, pad.big ? 1.5 : 0.6, 6),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.65, blending: THREE.AdditiveBlending, depthWrite: false }),
      );
      core.position.y = pad.big ? 0.8 : 0.35;
      g.add(core);
      if (pad.big) {
        const beam = new THREE.Mesh(
          new THREE.CylinderGeometry(1.2, 2.4, 9, 12, 1, true),
          new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.07, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }),
        );
        beam.position.y = 4.6;
        g.add(beam);
      }
      g.position.set(pad.x, 0, pad.z);
      g.userData = { disc, ring, core };
      this.padGroup.add(g);
    }
    // cars
    for (const car of world.cars) {
      this.addCar(car);
    }
    this.cameraState.shake = 0;
    this.cameraState.goalFocus = 0;
  }

  addCar(car) {
    const teamId = car.team;
    const glow = teamId === 0 ? '#35c8ff' : '#ff8a2e';
    const body = teamId === 0 ? '#1a5fb8' : '#c04a10';
    const plate = !car.isLocal || this.world?.mode === 'demo' || this.world?.mode === 'online-guest';
    const name = car.isLocal ? 'VOCÊ' : car.name;
    const model = createCarModel(car.def, {
      bodyColor: body,
      accentColor: car.def.paint.accent,
      glowColor: glow,
      rimColor: car.def.paint.rim,
      teamId,
      name: plate ? name : '',
      plate,
    });
    const pivot = new THREE.Group();
    model.group.position.y = -car.centerY;
    pivot.add(model.group);
    pivot.position.set(car.pos.x, car.pos.y + car.centerY, car.pos.z);
    pivot.quaternion.copy(car.quat);
    this.scene.add(pivot);
    this.carVisuals.set(car.id, { pivot, model, car });
  }

  clearCars() {
    for (const [, visual] of this.carVisuals) {
      this.scene.remove(visual.pivot);
      visual.model.group.traverse((o) => {
        if (o.geometry) o.geometry.dispose();
        if (o.material) {
          const mats = Array.isArray(o.material) ? o.material : [o.material];
          for (const m of mats) {
            if (m.map && m.map !== this.ballTexture) m.map.dispose?.();
            m.dispose?.();
          }
        }
      });
    }
    this.carVisuals.clear();
  }

  setCameraMode(mode) {
    this.cameraState.mode = mode;
  }

  toggleBallCam() {
    this.cameraState.ballCam = !this.cameraState.ballCam;
    return this.cameraState.ballCam;
  }

  addShake(amount) {
    this.cameraState.shake = Math.min(1.4, this.cameraState.shake + amount);
  }

  spawnBoost(car, dt) {
    if (!car.boostActive) return;
    const timerKey = car.id;
    const t = (this.boostTimers.get(timerKey) || 0) - dt;
    if (t > 0) { this.boostTimers.set(timerKey, t); return; }
    this.boostTimers.set(timerKey, 0.022);
    const q = car.quat;
    const back = this.tmpV.set(0, 0, -1).applyQuaternion(q);
    const side = this.tmpV2.set(1, 0, 0).applyQuaternion(q);
    for (const s of [-1, 1]) {
      const px = car.pos.x + back.x * (car.halfL + 0.4) + side.x * s * 0.45;
      const py = car.pos.y + 0.4 + back.z * (car.halfL + 0.4) + side.z * s * 0.45 + 0.4;
      const pz = car.pos.z + back.z * (car.halfL + 0.4) + side.z * s * 0.45;
      this.particles.spawn({
        x: px, y: py, z: pz,
        vx: back.x * 9 + (Math.random() - 0.5) * 2,
        vy: 0.4 + Math.random() * 1.2,
        vz: back.z * 9 + (Math.random() - 0.5) * 2,
        color: car.team === 0 ? '#35d8ff' : '#ff9a3c',
        size: 2.6 + Math.random() * 1.8,
        life: 0.24 + Math.random() * 0.16,
        drag: 0.92,
      });
    }
  }

  handleEvent(event, world) {
    if (!event) return;
    const p = event.pos;
    switch (event.type) {
      case 'hit': {
        if (!p) break;
        const count = Math.round(5 + event.power * 9);
        for (let i = 0; i < count; i++) {
          this.particles.spawn({
            x: p.x, y: p.y, z: p.z,
            vx: (Math.random() - 0.5) * 22, vy: Math.random() * 12, vz: (Math.random() - 0.5) * 22,
            color: Math.random() > 0.5 ? '#eaffff' : '#7fe8ff',
            size: 1.6 + Math.random() * 2.4,
            life: 0.3 + Math.random() * 0.3, gravity: 12, drag: 0.94,
          });
        }
        this.addShake(clamp(event.power * 0.24, 0.05, 0.45));
        break;
      }
      case 'jump': {
        const car = world?.getCar?.(event.carId);
        if (!car) break;
        for (let i = 0; i < 9; i++) {
          this.particles.spawn({
            x: car.pos.x + (Math.random() - 0.5) * 2, y: 0.2, z: car.pos.z + (Math.random() - 0.5) * 3,
            vx: (Math.random() - 0.5) * 7, vy: Math.random() * 2.4, vz: (Math.random() - 0.5) * 7,
            color: car.team === 0 ? '#7fe8ff' : '#ffb271', size: 2, life: 0.4, drag: 0.9,
          });
        }
        break;
      }
      case 'land': {
        const car = world?.getCar?.(event.carId);
        if (!car) break;
        for (let i = 0; i < 8; i++) {
          this.particles.spawn({
            x: car.pos.x + (Math.random() - 0.5) * 3, y: 0.15, z: car.pos.z + (Math.random() - 0.5) * 4,
            vx: (Math.random() - 0.5) * 9, vy: 0.6 + Math.random(), vz: (Math.random() - 0.5) * 9,
            color: '#a9c6de', size: 2.4, life: 0.45, drag: 0.88,
          });
        }
        break;
      }
      case 'drift': {
        if (!p) break;
        this.particles.spawn({
          x: p.x + (Math.random() - 0.5) * 2, y: 0.2, z: p.z + (Math.random() - 0.5) * 3,
          vx: (Math.random() - 0.5) * 4, vy: 0.4 + Math.random(), vz: (Math.random() - 0.5) * 4,
          color: '#c8d8e8', size: 2.8, life: 0.5, drag: 0.9,
        });
        break;
      }
      case 'boost': {
        if (!p) break;
        for (let i = 0; i < (event.big ? 26 : 8); i++) {
          const a = (i / 12) * Math.PI * 2;
          this.particles.spawn({
            x: p.x + Math.cos(a) * 1.4, y: p.y + Math.random() * 1.4, z: p.z + Math.sin(a) * 1.4,
            vx: Math.cos(a) * (3 + Math.random() * 4), vy: 2 + Math.random() * 4, vz: Math.sin(a) * (3 + Math.random() * 4),
            color: event.big ? '#ffd76a' : '#7fe8ff', size: event.big ? 3.4 : 2.2,
            life: 0.5 + Math.random() * 0.3, drag: 0.92, gravity: 3,
          });
        }
        break;
      }
      case 'demolish': {
        if (!p) break;
        for (let i = 0; i < 60; i++) {
          const a = Math.random() * Math.PI * 2;
          const sp = 6 + Math.random() * 22;
          this.particles.spawn({
            x: p.x, y: p.y + 1 + Math.random(), z: p.z,
            vx: Math.cos(a) * sp, vy: 3 + Math.random() * 14, vz: Math.sin(a) * sp,
            color: Math.random() > 0.4 ? '#ffb02e' : '#ffffff',
            size: 2 + Math.random() * 4, life: 0.5 + Math.random() * 0.7, gravity: 16, drag: 0.95,
          });
        }
        this.addShake(0.85);
        break;
      }
      case 'goal': {
        const z = event.team === 0 ? ARENA.halfL : -ARENA.halfL;
        const color = event.team === 0 ? '#35d8ff' : '#ff8a2e';
        for (let i = 0; i < 120; i++) {
          const a = Math.random() * Math.PI * 2;
          const sp = 4 + Math.random() * 26;
          this.particles.spawn({
            x: (Math.random() - 0.5) * 24, y: 1 + Math.random() * 12, z: z + (Math.random() - 0.5) * 8,
            vx: Math.cos(a) * sp, vy: 4 + Math.random() * 18, vz: Math.sin(a) * sp,
            color: Math.random() > 0.35 ? color : '#ffffff',
            size: 2.4 + Math.random() * 4.2, life: 0.8 + Math.random() * 1.1, gravity: 9, drag: 0.94,
          });
        }
        this.addShake(0.9);
        this.cameraState.goalFocus = 2.2;
        this.spawnShockwave(z, color);
        break;
      }
      case 'flip': {
        if (!p) break;
        for (let i = 0; i < 12; i++) {
          this.particles.spawn({
            x: p.x + (Math.random() - 0.5) * 2, y: p.y + 0.5, z: p.z,
            vx: (Math.random() - 0.5) * 8, vy: Math.random() * 3, vz: (Math.random() - 0.5) * 8,
            color: '#eafcff', size: 2.2, life: 0.35, drag: 0.9,
          });
        }
        break;
      }
      default: break;
    }
  }

  spawnShockwave(z, color) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(1, 1.6, 48),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(0, 0.3, z > 0 ? 55 : -55);
    this.scene.add(ring);
    this.effects.push({ mesh: ring, life: 1.1, maxLife: 1.1, grow: 22 });
    for (let i = 0; i < 3; i++) {
      const halo = new THREE.Mesh(
        new THREE.RingGeometry(2 + i * 1.2, 2.5 + i * 1.2, 48),
        new THREE.MeshBasicMaterial({ color: '#ffffff', transparent: true, opacity: 0.4, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
      );
      halo.rotation.x = -Math.PI / 2;
      halo.position.set(0, 0.4, z > 0 ? 55 : -55);
      this.scene.add(halo);
      this.effects.push({ mesh: halo, life: 0.9, maxLife: 0.9, grow: 10 + i * 5 });
    }
  }

  update(dt, world, { cameraMode = 'chase', carId = null, paused = false } = {}) {
    this.elapsed += dt;
    if (!world) { this.renderer.render(this.scene, this.camera); return; }
    this.world = world;
    for (const car of world.cars) {
      const visual = this.carVisuals.get(car.id);
      if (!visual) { this.addCar(car); continue; }
      this.updateCarVisual(visual, car, dt);
      this.spawnBoost(car, dt);
    }
    // ball
    const ball = world.ball;
    this.ballGroup.visible = true;
    this.ballGroup.position.copy(ball.pos);
    const speed = ball.vel.length();
    const axis = this.tmpV.set(-ball.vel.z, 0, ball.vel.x).normalize();
    if (axis.lengthSq() > 0.001) {
      this.ballMesh.rotateOnWorldAxis(axis, speed * dt / ball.radius * 0.9);
    }
    this.ballShadow.position.y = -ball.pos.y + 0.06;
    this.ballShadow.material.opacity = clamp(0.5 - ball.pos.y * 0.01, 0.08, 0.5);
    this.ballShadow.scale.setScalar(clamp(1 - ball.pos.y * 0.01, 0.4, 1));
    // ball trail
    this.ballTrailTimer -= dt;
    if (speed > 16 && this.ballTrailTimer <= 0) {
      this.ballTrailTimer = 0.026;
      for (let i = 0; i < 2; i++) {
        this.particles.spawn({
          x: ball.pos.x + (Math.random() - 0.5) * 1.4,
          y: ball.pos.y + (Math.random() - 0.5) * 1.4,
          z: ball.pos.z + (Math.random() - 0.5) * 1.4,
          vx: 0, vy: 0.3, vz: 0,
          color: '#9ff2ff', size: 2.4 + speed * 0.03,
          life: 0.3, drag: 1,
        });
      }
    }
    // pads
    for (let i = 0; i < world.pads.length; i++) {
      const pad = world.pads[i];
      const g = this.padGroup.children[i];
      if (!g) continue;
      g.visible = pad.active;
      const { ring, core } = g.userData;
      const pulse = 1 + Math.sin(this.elapsed * 3 + i) * 0.08;
      ring.scale.setScalar(pulse);
      core.scale.y = pad.big ? 1 + Math.sin(this.elapsed * 5 + i) * 0.25 : 1;
    }
    // arena
    this.arena?.update(dt, this.elapsed);
    this.arena?.updateScreens({
      blue: world.score[0],
      orange: world.score[1],
      time: world.matchTime,
      phase: world.phase,
      overtime: world.overtime,
    });
    // particles & effects
    this.particles.update(dt);
    for (let i = this.effects.length - 1; i >= 0; i--) {
      const e = this.effects[i];
      e.life -= dt;
      const k = e.life / e.maxLife;
      const s = 1 + (1 - k) * e.grow;
      e.mesh.scale.set(s, s, s);
      e.mesh.material.opacity = Math.max(0, k) * 0.8;
      if (e.life <= 0) {
        this.scene.remove(e.mesh);
        e.mesh.geometry.dispose();
        e.mesh.material.dispose();
        this.effects.splice(i, 1);
      }
    }
    // camera
    this.updateCamera(dt, world, { carId, mode: cameraMode, paused });
    this.renderer.render(this.scene, this.camera);
  }

  updateCarVisual(visual, car, dt) {
    const { pivot, model } = visual;
    pivot.visible = !car.hidden;
    pivot.position.set(car.pos.x, car.pos.y + car.centerY, car.pos.z);
    pivot.quaternion.copy(car.quat);
    if (car.flip) {
      const t = clamp(car.flip.t / car.flip.duration, 0, 1);
      const ease = Math.sin(t * Math.PI * 0.5);
      const angle = ease * Math.PI * 2;
      const axis = car.flip.axis === 'z' ? this.tmpV.set(0, 0, 1) : this.tmpV.set(1, 0, 0);
      this.tmpQ.setFromAxisAngle(axis, angle * (car.flip.axis === 'z' ? -car.flip.dir : 1));
      pivot.quaternion.multiply(this.tmpQ);
    }
    // wheels
    const steer = car.lastInput?.steer || 0;
    for (const wheel of model.wheels) {
      wheel.spin.rotation.x = car.wheelSpin;
      wheel.group.rotation.y = wheel.front ? steer * 0.4 : 0;
    }
    // flames
    const boosting = car.boostActive && car.boost > 0;
    model.flameGroup.visible = boosting;
    if (boosting) {
      const flicker = 0.85 + Math.sin(this.elapsed * 40 + car.pos.x) * 0.18;
      for (const f of model.flames) {
        f.cone.scale.set(1, flicker * (0.8 + Math.random() * 0.3), 1);
        f.inner.scale.set(1, flicker, 1);
      }
    }
    model.glowPlane.material.opacity = boosting ? 0.9 : 0.35 + Math.sin(this.elapsed * 2.5 + car.pos.z) * 0.06;
    // hit flash
    if (car.hitCooldown > 0) {
      model.bodyMat.emissive.set(car.team === 0 ? '#1e5f9e' : '#a23c0c');
      model.bodyMat.emissiveIntensity = 1.6;
    } else {
      model.bodyMat.emissive.set(car.team === 0 ? '#061a2a' : '#2a1002');
      model.bodyMat.emissiveIntensity = 0.8;
    }
    if (model.nameSprite) {
      model.nameSprite.visible = !car.hidden;
      model.nameSprite.material.opacity = car.isLocal ? 0.55 : 0.9;
    }
  }

  updateCamera(dt, world, { carId, mode, paused }) {
    const cam = this.camera;
    const state = this.cameraState;
    const local = carId ? world.cars.find((c) => c.id === carId) : world.cars.find((c) => c.isLocal);
    const ball = world.ball;
    if (mode === 'menu' || !local) {
      state.menuAngle += dt * 0.055;
      const radius = 108;
      const height = 40 + Math.sin(this.elapsed * 0.13) * 6;
      const targetPos = new THREE.Vector3(
        Math.sin(state.menuAngle) * radius,
        height,
        Math.cos(state.menuAngle) * radius,
      );
      state.pos.lerp(targetPos, 1 - Math.exp(-dt * 2.2));
      state.look.lerp(new THREE.Vector3(Math.sin(state.menuAngle * 0.6) * 8, 4, 0), 1 - Math.exp(-dt * 2));
      cam.position.copy(state.pos);
      cam.lookAt(state.look);
      cam.fov = 58;
      cam.updateProjectionMatrix();
      return;
    }
    const forward = this.tmpV.set(Math.sin(local.yaw), 0, Math.cos(local.yaw));
    const speed = local.vel.length();
    const dist = 10.6 + Math.min(4, speed * 0.06);
    const height = 4.4 + clamp(local.pos.y * 0.22, 0, 3) + (state.goalFocus > 0 ? 2 : 0);
    const ideal = new THREE.Vector3(
      local.pos.x - forward.x * dist,
      local.pos.y + height,
      local.pos.z - forward.z * dist,
    );
    // avoid camera going through walls
    ideal.x = clamp(ideal.x, -ARENA.halfW + 1.5, ARENA.halfW - 1.5);
    ideal.z = clamp(ideal.z, -ARENA.halfL + 1.5, ARENA.halfL - 1.5);
    ideal.y = clamp(ideal.y, 1.4, ARENA.height - 2);
    const smooth = 1 - Math.exp(-dt * (state.goalFocus > 0 ? 2.2 : 7.5));
    state.pos.lerp(ideal, smooth);

    let lookTarget;
    if (state.goalFocus > 0) {
      state.goalFocus -= dt;
      lookTarget = new THREE.Vector3(ball.pos.x, Math.max(1, ball.pos.y), ball.pos.z);
    } else if (state.ballCam) {
      lookTarget = new THREE.Vector3(
        ball.pos.x + ball.vel.x * 0.1,
        Math.max(1.2, ball.pos.y + 1),
        ball.pos.z + ball.vel.z * 0.1,
      );
    } else {
      lookTarget = new THREE.Vector3(
        local.pos.x + forward.x * 9,
        local.pos.y + 1.8,
        local.pos.z + forward.z * 9,
      );
    }
    state.look.lerp(lookTarget, 1 - Math.exp(-dt * (state.goalFocus > 0 ? 3 : 6)));
    cam.position.copy(state.pos);

    if (state.shake > 0.001) {
      const s = state.shake;
      cam.position.x += (Math.random() - 0.5) * s * 1.8;
      cam.position.y += (Math.random() - 0.5) * s * 1.2;
      cam.position.z += (Math.random() - 0.5) * s * 1.8;
      state.shake *= Math.exp(-dt * 5.5);
    }
    cam.lookAt(state.look);
    const targetFov = 68 + clamp(speed * 0.32, 0, 14) + (state.goalFocus > 0 ? 4 : 0);
    state.fov += (targetFov - state.fov) * Math.min(1, dt * 3);
    cam.fov = state.fov;
    cam.updateProjectionMatrix();
  }

  dispose() {
    window.removeEventListener('resize', this.onResize);
    this.clearCars();
    this.arena?.dispose();
    this.particles.points.geometry.dispose();
    this.particles.points.material.dispose();
    this.renderer.dispose();
  }
}

import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
import { createCarModel } from '../game/carModel.js';

export class CarPreview {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.25;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(34, 1, 0.1, 100);
    this.scene.environment = (() => {
      const pmrem = new THREE.PMREMGenerator(this.renderer);
      const env = new RoomEnvironment();
      const tex = pmrem.fromScene(env, 0.04).texture;
      env.dispose?.();
      pmrem.dispose();
      return tex;
    })();
    this.hemi = new THREE.HemisphereLight('#cfe8ff', '#0b1220', 1.4);
    this.scene.add(this.hemi);
    const key = new THREE.DirectionalLight('#ffffff', 3.2);
    key.position.set(4, 7, 5);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight('#59e6ff', 2.2);
    rim.position.set(-6, 3, -5);
    this.scene.add(rim);
    const warm = new THREE.PointLight('#ff9a52', 30, 20, 2);
    warm.position.set(-3, 2, 4);
    this.scene.add(warm);

    this.carGroup = null;
    this.angle = 0;
    this.visible = false;
    this.raf = null;
    this.last = performance.now();
    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(canvas.parentElement || canvas);
    this.resize();
  }

  resize() {
    const parent = this.canvas.parentElement;
    if (!parent) return;
    const w = parent.clientWidth || 480;
    const h = parent.clientHeight || 300;
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }

  setCar(def) {
    if (this.carDef === def) return;
    this.carDef = def;
    if (this.carGroup) {
      this.scene.remove(this.carGroup);
      this.carGroup.traverse((o) => {
        o.geometry?.dispose();
        if (o.material) {
          const mats = Array.isArray(o.material) ? o.material : [o.material];
          for (const m of mats) { m.map?.dispose?.(); m.dispose?.(); }
        }
      });
    }
    const model = createCarModel(def, {
      bodyColor: def.paint.body,
      accentColor: def.paint.accent,
      glowColor: def.paint.glow,
      rimColor: def.paint.rim,
      teamId: 0,
      plate: false,
    });
    const group = new THREE.Group();
    // scale & center the car nicely
    const box = new THREE.Box3().setFromObject(model.group);
    const height = box.max.y - box.min.y;
    const scale = 1.7 / height;
    model.group.scale.setScalar(scale);
    model.group.position.y = 0;
    group.add(model.group);
    // platform glow
    const glow = new THREE.Mesh(
      new THREE.CircleGeometry(4.2, 40),
      new THREE.MeshBasicMaterial({ color: def.paint.glow, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    glow.rotation.x = -Math.PI / 2;
    glow.position.y = 0.01;
    group.add(glow);
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(3.3, 3.55, 64),
      new THREE.MeshBasicMaterial({ color: def.paint.glow, transparent: true, opacity: 0.5, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.02;
    group.add(ring);
    this.scene.add(group);
    this.carGroup = group;
    this.model = model;
    this.camera.position.set(5.6, 3.1, 6.4);
    this.camera.lookAt(0, 0.9, 0);
    this.render(0);
  }

  setVisible(visible) {
    this.visible = visible;
    if (visible) {
      this.resize();
      if (!this.raf) {
        this.last = performance.now();
        const loop = (t) => {
          if (!this.visible) { this.raf = null; return; }
          const dt = Math.min(0.05, (t - this.last) / 1000);
          this.last = t;
          this.angle += dt * 0.42;
          this.render(dt);
          this.raf = requestAnimationFrame(loop);
        };
        this.raf = requestAnimationFrame(loop);
      }
    }
  }

  render(dt) {
    if (!this.carGroup) return;
    this.carGroup.rotation.y = this.angle;
    this.renderer.render(this.scene, this.camera);
  }

  dispose() {
    this.visible = false;
    this.resizeObserver.disconnect();
    this.renderer.dispose();
  }
}

import Peer from 'peerjs';

const PREFIX = 'tsx1';
const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

function randomCode() {
  let out = '';
  for (let i = 0; i < 5; i++) out += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
  return out;
}

const PEER_CONFIG = {
  debug: 0,
  config: {
    iceServers: [
      { urls: 'stun:stun.l.google.com:19302' },
      { urls: 'stun:stun1.l.google.com:19302' },
      { urls: 'stun:stun.cloudflare.com:3478' },
    ],
  },
};

export class NetClient {
  constructor() {
    this.peer = null;
    this.conn = null;
    this.code = null;
    this.role = null;
    this.handlers = {};
    this.closed = false;
    this.timeout = null;
    this.lastStatus = '';
  }

  on(event, cb) {
    (this.handlers[event] ||= []).push(cb);
    return this;
  }

  emit(event, payload) {
    for (const cb of this.handlers[event] || []) {
      try { cb(payload); } catch (err) { console.error(err); }
    }
  }

  status(text) {
    this.lastStatus = text;
    this.emit('status', text);
  }

  createRoom() {
    return new Promise((resolve, reject) => {
      this.close();
      this.closed = false;
      this.role = 'host';
      const tryHost = (attempt = 0) => {
        const code = randomCode();
        const id = `${PREFIX}-${code}-h`;
        this.status('Criando sala segura…');
        let settled = false;
        let peer;
        try {
          peer = new Peer(id, PEER_CONFIG);
        } catch (err) {
          reject(err);
          return;
        }
        this.peer = peer;
        const fail = (err) => {
          if (settled) return;
          settled = true;
          try { peer.destroy(); } catch {}
          if (attempt < 2 && (err?.type === 'unavailable-id' || err?.type === 'network')) {
            setTimeout(() => tryHost(attempt + 1), 700);
          } else {
            reject(err);
          }
        };
        peer.on('open', () => {
          if (settled) return;
          settled = true;
          this.code = code;
          this.status('Sala criada. Aguardando adversário…');
          this.emit('room', code);
          this.bindPeer();
          resolve(code);
        });
        peer.on('error', fail);
      };
      tryHost();
    });
  }

  bindPeer() {
    const peer = this.peer;
    if (!peer) return;
    peer.on('connection', (conn) => {
      if (this.conn && this.conn.open) {
        // room is full (1v1/2v2 lobby handles one guest)
        try { conn.close(); } catch {}
        return;
      }
      this.attachConnection(conn);
      this.status('Adversário conectado!');
      this.emit('guest', true);
    });
    peer.on('disconnected', () => {
      if (!this.closed) {
        this.status('Reconectando ao servidor…');
        setTimeout(() => { try { peer.reconnect(); } catch {} }, 1200);
      }
    });
    peer.on('error', (err) => {
      if (err?.type === 'peer-unavailable') return;
      this.emit('error', err?.message || String(err));
    });
    peer.on('close', () => {
      if (!this.closed) this.emit('close');
    });
  }

  joinRoom(code) {
    return new Promise((resolve, reject) => {
      this.close();
      this.closed = false;
      this.role = 'guest';
      const clean = String(code || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 5);
      if (clean.length < 4) { reject(new Error('Código inválido')); return; }
      this.code = clean;
      this.status('Procurando sala…');
      const peer = new Peer(PEER_CONFIG);
      this.peer = peer;
      let settled = false;
      const finish = (err) => {
        if (settled) return;
        settled = true;
        clearTimeout(this.timeout);
        this.status(err ? 'Falha na conexão' : 'Conectando…');
        if (err) {
          try { peer.destroy(); } catch {}
          reject(err);
        } else resolve();
      };
      this.timeout = setTimeout(() => finish(new Error('Sala não encontrada. Verifique o código.')), 18000);
      peer.on('open', () => {
        this.status('Conectando à sala…');
        const conn = peer.connect(`${PREFIX}-${clean}-h`, { reliable: true, serialization: 'json' });
        conn.on('open', () => {
          this.attachConnection(conn);
          finish();
        });
        conn.on('error', (err) => finish(err || new Error('Conexão recusada')));
      });
      peer.on('error', (err) => {
        if (err?.type === 'peer-unavailable') finish(new Error('Sala não encontrada. Verifique o código.'));
        else finish(new Error('Erro de rede: ' + (err?.type || 'desconhecido')));
      });
    });
  }

  attachConnection(conn) {
    this.conn = conn;
    conn.on('data', (data) => {
      if (data && typeof data === 'object') this.emit('data', data);
    });
    conn.on('close', () => {
      this.conn = null;
      if (!this.closed) this.emit('close');
    });
    conn.on('error', (err) => this.emit('error', err?.message || 'Erro na conexão'));
  }

  send(data) {
    if (this.conn && this.conn.open) {
      try { this.conn.send(data); return true; } catch { return false; }
    }
    return false;
  }

  get connected() {
    return !!(this.conn && this.conn.open);
  }

  close() {
    this.closed = true;
    clearTimeout(this.timeout);
    try { this.conn?.close(); } catch {}
    try { this.peer?.destroy(); } catch {}
    this.conn = null;
    this.peer = null;
    this.code = null;
    this.role = null;
  }
}

import * as THREE from 'three';
import { SaveStore, addXp, ACHIEVEMENTS, levelProgress } from '../core/save.js';
import { GameAudio } from '../core/audio.js';
import { Input } from '../core/input.js';
import { NetClient } from '../core/net.js';
import { Renderer } from './renderer.js';
import { World } from './physics.js';
import { makeBotController, difficultyLabel } from './bot.js';
import { ARENA } from './constants.js';
import { CARS, CAR_BY_ID, THEMES, TEAM, carPhysicalStats } from '../data/cars.js';
import { BOT_NAMES, getRank } from '../data/ranks.js';
import { UI } from '../ui/ui.js';

const IDLE_INPUT = { throttle: 0, steer: 0, boost: false, drift: false, jumpPressed: false, airRoll: 0 };
const rand = (arr) => arr[Math.floor(Math.random() * arr.length)];

export class Game {
  constructor(canvas) {
    this.save = new SaveStore();
    this.audio = new GameAudio(this.save.data.settings.volume);
    this.input = new Input();
    this.net = new NetClient();
    this.renderer = new Renderer(canvas, { quality: this.save.data.settings.quality });
    this.state = 'menu';
    this.mode = 'demo';
    this.world = null;
    this.localCarId = null;
    this.currentInput = { ...IDLE_INPUT };
    this.paused = false;
    this.pauseOverlay = false;
    this.acc = 0;
    this.lastT = performance.now();
    this.elapsed = 0;
    this.matchMeta = null;
    this.matchStats = null;
    this.matchFinished = false;
    this.pendingToasts = [];
    this.online = {
      status: 'idle',
      code: '',
      guestInfo: null,
      hostInfo: null,
      config: null,
      remoteInput: { ...IDLE_INPUT },
      guestJump: false,
      hostJump: false,
      lastSnapshot: null,
      snapTimer: 0,
      inputTimer: 0,
      rematchPending: false,
    };
    this.hudAccum = 0;
    this.hintsTimer = 0;
    this.boostPrev = null;
    this.demoThemeIndex = 0;
    this.lastConfig = null;
    this.isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;

    this.checkFreeCars(true);
    const daily = this.save.claimDaily();
    if (daily > 0) this.pendingToasts.push({ title: 'Bônus diário', text: `+${daily} créditos por voltar à arena!`, kind: 'gold' });

    this.ui = new UI(this);
    this.setupDemo();
    this.input.onPause = () => this.handlePause();
    this.bindNetwork();
    this.bindInputExtras();
    if (this.isTouch) this.input.bindTouch();

    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);
    setTimeout(() => this.flushToasts(), 500);
    this.audio.setVolume(this.save.data.settings.volume);
    this.audio.startCrowd();
  }

  // ---------- boot / profile ----------
  checkFreeCars(silent = false) {
    const unlocked = [];
    for (const car of CARS) {
      if (car.price === 0 && car.unlockLevel > 0 && this.save.data.level >= car.unlockLevel && !this.save.data.owned.includes(car.id)) {
        this.save.ownCar(car.id);
        unlocked.push(car);
      }
    }
    if (!this.save.data.owned.includes(this.save.data.car)) this.save.data.car = 'falcon';
    if (unlocked.length) {
      this.save.flush();
      if (!silent) {
        for (const car of unlocked) this.ui?.toast('Carro grátis desbloqueado', `${car.name} já está na sua garagem!`, 'gold');
      }
    }
    return unlocked;
  }

  flushToasts() {
    while (this.pendingToasts.length) {
      const t = this.pendingToasts.shift();
      this.ui.toast(t.title, t.text, t.kind);
    }
  }

  applySetting(key, value) {
    this.save.data.settings[key] = value;
    this.save.save();
    if (key === 'volume') this.audio.setVolume(value);
    if (key === 'quality') this.renderer.setQuality(value);
    if (key === 'camera') this.renderer.cameraState.ballCam = value === 'ball';
  }

  setPlayerName(name) {
    const clean = String(name || '').replace(/[<>&]/g, '').trim().slice(0, 16) || 'Piloto';
    this.save.data.name = clean;
    this.save.save();
    this.ui.refresh();
  }

  // ---------- demo backdrop ----------
  setupDemo() {
    this.mode = 'demo';
    this.state = this.state === 'menu' ? 'menu' : this.state;
    this.localCarId = null;
    this.paused = false;
    this.pauseOverlay = false;
    this.matchFinished = false;
    const theme = THEMES[this.demoThemeIndex % THEMES.length];
    const carA = rand(CARS);
    let carB = rand(CARS);
    if (carB.id === carA.id) carB = CARS[(CARS.indexOf(carA) + 4) % CARS.length];
    const setups = [
      { id: 'demo-a', team: 0, def: carA, isBot: true, name: rand(BOT_NAMES), difficulty: 3 },
      { id: 'demo-b', team: 1, def: carB, isBot: true, name: rand(BOT_NAMES), difficulty: 3 },
    ];
    const world = new World({ carSetups: setups, theme, mode: 'demo', duration: 9999, teamSize: 1 });
    world.setController('demo-a', makeBotController(3, 'attacker', Math.floor(Math.random() * 999)));
    world.setController('demo-b', makeBotController(3, 'attacker', Math.floor(Math.random() * 999)));
    this.world = world;
    this.renderer.loadWorld(world);
    this.renderer.setCameraMode('menu');
    this.renderer.cameraState.ballCam = true;
    this.renderer.cameraState.shake = 0;
    this.audio.stopEngine();
    this.audio.updateEngine(0, 0, false, false, false, false);
    this.input.setPlaying(false);
    this.ui?.setHUD(false);
    this.ui?.setOnlineWaiting(false);
    if (this.ui) this.ui.refresh();
  }

  returnToMenu() {
    this.net.close();
    this.online.status = 'idle';
    this.online.guestInfo = null;
    this.online.rematchPending = false;
    this.state = 'menu';
    this.paused = false;
    this.pauseOverlay = false;
    this.matchFinished = false;
    this.setupDemo();
    this.ui.hideResults();
    this.ui.hidePause();
    this.ui.showScreen('home');
    this.ui.setHUD(false);
    this.ui.setTouchVisible(false);
    this.ui.refresh();
    this.audio.ui('back');
  }

  // ---------- offline ----------
  startOffline(config = {}) {
    const {
      teamSize = 1, difficulty = 2, duration = 180, themeId = 'neon', ranked = false, mode = 'offline',
    } = config;
    this.lastConfig = { ...config, teamSize, difficulty, duration, themeId, ranked, mode };
    this.net.close();
    this.mode = mode;
    this.state = 'playing';
    this.paused = false;
    this.pauseOverlay = false;
    this.matchFinished = false;
    this.hintsTimer = 0;
    this.boostPrev = null;
    this.audio.init();
    const theme = THEMES.find((t) => t.id === themeId) || THEMES[0];
    const selected = CAR_BY_ID[this.save.data.car] || CARS[0];
    const names = [...BOT_NAMES].sort(() => Math.random() - 0.5);
    const setups = [{ id: 'local', team: 0, def: selected, isLocal: true, name: this.save.data.name }];
    const botNames = names.slice(0, Math.max(0, teamSize * 2 - 1));
    const usedCars = new Set([selected.id]);
    let ni = 0;
    const pickBotCar = () => {
      let car = rand(CARS);
      let guard = 0;
      while (usedCars.has(car.id) && guard++ < 10) car = rand(CARS);
      usedCars.add(car.id);
      return car;
    };
    for (let i = 1; i < teamSize; i++) {
      setups.push({ id: `ally-${i}`, team: 0, def: pickBotCar(), isBot: true, name: botNames[ni++] || 'Aliado', difficulty });
    }
    for (let i = 0; i < teamSize; i++) {
      setups.push({ id: `enemy-${i}`, team: 1, def: pickBotCar(), isBot: true, name: botNames[ni++] || 'Rival', difficulty });
    }
    const world = new World({ carSetups: setups, theme, mode, duration, teamSize });
    this.localCarId = 'local';
    world.setController('local', () => this.currentInput);
    let ai = 0;
    for (const car of world.cars) {
      if (car.isBot) {
        const role = car.team === 0 ? (teamSize > 1 ? 'defender' : 'attacker') : 'attacker';
        world.setController(car.id, makeBotController(difficulty, role, 100 + ai * 37 + Math.floor(Math.random() * 50)));
        ai++;
      }
    }
    this.attachWorld(world, { mode, ranked });
    this.ui.setHUD(true);
    this.ui.hideScreens();
    this.ui.setTouchVisible(this.isTouch);
    this.ui.showBanner('3', 'count', 900);
    this.audio.countdown(3);
    this.ui.refresh();
    this.audio.startEngine();
    this.audio.startCrowd();
    this.audio.crowdIntensity(0.15);
    this.ui.setBlueLabel(this.save.data.name);
    this.ui.setOrangeLabel(`${difficultyLabel(difficulty)} • IA`);
  }

  startRankedAI(config = {}) {
    const rank = getRank(this.save.data.offline.mmr);
    const difficulty = Math.min(4, Math.max(1, Math.floor((this.save.data.offline.mmr - 300) / 300) + 1));
    this.ui.toast(`Ranqueada local • ${rank.name}`, `${difficultyLabel(difficulty)} — valendo MMR offline`, 'orange');
    this.startOffline({ ...config, ranked: true, difficulty, mode: 'offline-ranked' });
  }

  attachWorld(world, meta = {}) {
    this.world = world;
    this.matchMeta = {
      ...meta,
      startedAt: performance.now(),
      duration: world.duration,
      localTeam: this.localCarId === 'guest' ? 1 : 0,
    };
    this.matchStats = { goals: 0, saves: 0, demos: 0, boost: 0, shots: 0 };
    this.acc = 0;
    this.matchFinished = false;
    this.renderer.loadWorld(world);
    this.renderer.setCameraMode('chase');
    this.renderer.cameraState.ballCam = this.save.data.settings.camera !== 'car';
    this.renderer.cameraState.goalFocus = 0;
    const car = world.cars.find((c) => c.id === this.localCarId || c.isLocal);
    if (car) {
      const f = new THREE.Vector3(Math.sin(car.yaw), 0, Math.cos(car.yaw));
      this.renderer.cameraState.pos.set(car.pos.x - f.x * 12, 4.8, car.pos.z - f.z * 12);
      this.renderer.cameraState.look.set(car.pos.x, 1.5, car.pos.z);
      this.renderer.cameraState.shake = 0;
      this.renderer.cameraState.fov = 70;
    }
    this.boostPrev = car ? car.boost : 33;
  }

  // ---------- camera / pause / input ----------
  bindInputExtras() {
    this.input.onPause = () => this.handlePause();
  }

  handlePause() {
    if (this.state === 'results') return;
    if (this.state !== 'playing') return;
    if (this.online.status === 'connected' && this.pauseOverlay) {
      this.closePause();
      return;
    }
    if (this.pauseOverlay) { this.closePause(); return; }
    this.pauseOverlay = true;
    const online = this.mode.startsWith('online');
    if (!online) this.paused = true;
    this.input.setPlaying(false);
    this.ui.showPause({ online });
    this.ui.setTouchVisible(false);
    this.audio.ui('click');
    if (!online) this.audio.updateEngine(0, 0, false, false, false, false);
  }

  closePause() {
    this.pauseOverlay = false;
    this.paused = false;
    this.ui.hidePause();
    this.ui.setTouchVisible(this.isTouch && this.state === 'playing');
    this.input.setPlaying(true);
    this.audio.ui('back');
  }

  quitMatch() {
    this.ui.hidePause();
    this.ui.hideResults();
    this.returnToMenu();
  }

  // ---------- online ----------
  async hostRoom(config = {}) {
    this.audio.init();
    this.online.config = {
      teamSize: config.teamSize || 1,
      duration: config.duration || 180,
      themeId: config.themeId || 'neon',
    };
    this.online.status = 'hosting';
    this.online.guestInfo = null;
    this.ui.setOnlineWaiting(true);
    this.ui.setOnlineStatus('Criando sala segura…', 'warn');
    try {
      const code = await this.net.createRoom();
      this.online.code = code;
      this.ui.setRoomCode(code);
      this.ui.setOnlineStatus('Sala pronta • aguardando adversário', 'on');
      this.ui.refresh();
    } catch (err) {
      this.online.status = 'error';
      this.ui.setOnlineStatus(`Não foi possível criar a sala: ${err?.message || err}`, 'error');
      this.ui.setOnlineWaiting(false);
      this.ui.toast('Falha ao criar sala', 'Verifique sua conexão e tente novamente.', 'orange');
    }
  }

  async joinRoom(code) {
    this.audio.init();
    this.online.status = 'joining';
    this.ui.setOnlineWaiting(true);
    this.ui.setOnlineStatus('Procurando a sala…', 'warn');
    try {
      await this.net.joinRoom(code);
      this.ui.setOnlineStatus('Conectado! Sincronizando partida…', 'on');
      this.net.send({
        type: 'hello',
        name: this.save.data.name,
        carId: this.save.data.car,
        mmr: this.save.data.online.mmr,
      });
      this.online.status = 'joining-wait';
    } catch (err) {
      this.online.status = 'error';
      this.ui.setOnlineWaiting(false);
      this.ui.setOnlineStatus(err?.message || 'Falha ao entrar na sala', 'error');
      this.ui.toast('Sala indisponível', err?.message || 'Confira o código e tente novamente.', 'orange');
    }
  }

  cancelOnline() {
    this.net.close();
    this.online.status = 'idle';
    this.online.guestInfo = null;
    this.ui.setOnlineWaiting(false);
    this.ui.setRoomCode('');
    this.ui.setOnlineStatus('Pronto para jogar online', 'on');
    this.ui.refresh();
  }

  bindNetwork() {
    this.net.on('status', (text) => {
      if (this.online.status === 'hosting' || this.online.status === 'joining') this.ui.setOnlineStatus(text, 'warn');
    });
    this.net.on('room', (code) => {
      this.online.code = code;
      this.ui.setRoomCode(code);
    });
    this.net.on('data', (data) => this.onNetData(data));
    this.net.on('guest', () => {
      this.ui.setOnlineStatus('Adversário conectado! Preparando kickoff…', 'on');
    });
    this.net.on('close', () => {
      if (['online-host', 'online-guest'].includes(this.mode) && this.state === 'playing') {
        this.ui.toast('Conexão encerrada', 'O adversário saiu da partida.', 'orange');
        this.ui.setOnlineWaiting(false);
        setTimeout(() => this.returnToMenu(), 600);
      } else {
        this.ui.setOnlineStatus('Conexão encerrada', 'error');
        this.ui.setOnlineWaiting(false);
      }
    });
    this.net.on('error', (msg) => {
      this.ui.setOnlineStatus(`Erro de rede: ${msg}`, 'error');
    });
  }

  onNetData(data) {
    if (!data || typeof data !== 'object') return;
    if (this.mode === 'online-host') {
      if (data.type === 'hello') {
        this.online.guestInfo = {
          name: String(data.name || 'Rival').slice(0, 16),
          carId: CAR_BY_ID[data.carId] ? data.carId : 'falcon',
          mmr: Number(data.mmr) || 600,
        };
        this.ui.setOnlineStatus(`Adversário: ${this.online.guestInfo.name}`, 'on');
        this.beginOnlineHostMatch();
      } else if (data.type === 'input' && data.input) {
        this.online.remoteInput = { ...IDLE_INPUT, ...data.input, jumpPressed: false };
      } else if (data.type === 'jump') {
        this.online.guestJump = true;
      } else if (data.type === 'rematch') {
        this.online.rematchPending = false;
        this.beginOnlineHostMatch();
      }
    } else if (this.mode === 'online-guest' || this.online.status === 'joining-wait') {
      if (data.type === 'welcome') {
        this.online.hostInfo = data;
        this.beginOnlineGuestMatch(data);
      } else if (data.type === 'snap') {
        if (this.world && this.mode === 'online-guest') {
          this.online.lastSnapshot = data;
          this.world.applySnapshot(data, 'guest');
        }
      } else if (data.type === 'goal') {
        if (this.world) {
          this.world.score = [...data.score];
          this.world.matchTime = data.time ?? this.world.matchTime;
          this.presentGoal(data.team, { name: data.scorer, ownGoal: data.ownGoal }, data.score);
        }
      } else if (data.type === 'end') {
        this.finishMatch(data.winner, { fromNet: true });
      } else if (data.type === 'event') {
        this.handleEvent(data.event);
      }
    }
  }

  beginOnlineHostMatch() {
    const guest = this.online.guestInfo;
    if (!guest) return;
    const cfg = this.online.config || { teamSize: 1, duration: 180, themeId: 'neon' };
    const theme = THEMES.find((t) => t.id === cfg.themeId) || THEMES[0];
    const hostDef = CAR_BY_ID[this.save.data.car] || CARS[0];
    const guestDef = CAR_BY_ID[guest.carId] || CARS[0];
    const teamSize = cfg.teamSize || 1;
    const setups = [
      { id: 'host', team: 0, def: hostDef, isLocal: true, name: this.save.data.name },
      { id: 'guest', team: 1, def: guestDef, isGuest: true, name: guest.name },
    ];
    const botDefs = [];
    const used = new Set([hostDef.id, guestDef.id]);
    const pick = () => {
      let c = rand(CARS); let g = 0;
      while (used.has(c.id) && g++ < 8) c = rand(CARS);
      used.add(c.id); return c;
    };
    for (let i = 1; i < teamSize; i++) {
      const def = pick();
      const name = rand(BOT_NAMES);
      setups.push({ id: `ally-${i}`, team: 0, def, isBot: true, name, difficulty: 3 });
      botDefs.push({ id: `ally-${i}`, team: 0, defId: def.id, name });
    }
    for (let i = 0; i < teamSize; i++) {
      const def = pick();
      const name = rand(BOT_NAMES);
      setups.push({ id: `guest-ally-${i}`, team: 1, def, isBot: true, name, difficulty: 3 });
      botDefs.push({ id: `guest-ally-${i}`, team: 1, defId: def.id, name });
    }
    const world = new World({ carSetups: setups, theme, mode: 'online-host', duration: cfg.duration, teamSize });
    this.localCarId = 'host';
    world.setController('host', () => this.currentInput);
    world.setController('guest', () => {
      if (this.online.guestJump) {
        this.online.guestJump = false;
        return { ...this.online.remoteInput, jumpPressed: true };
      }
      return this.online.remoteInput;
    });
    let ai = 1;
    for (const car of world.cars) {
      if (car.isBot) {
        world.setController(car.id, makeBotController(3, car.team === 0 ? 'defender' : 'attacker', 700 + ai * 41));
        ai++;
      }
    }
    this.net.send({
      type: 'welcome',
      hostName: this.save.data.name,
      hostCarId: hostDef.id,
      guestCarId: guestDef.id,
      guestName: guest.name,
      hostMmr: this.save.data.online.mmr,
      guestMmr: guest.mmr,
      teamSize,
      duration: cfg.duration,
      themeId: theme.id,
      bots: botDefs,
      rematch: this.matchFinished,
    });
    this.mode = 'online-host';
    this.state = 'playing';
    this.paused = false;
    this.pauseOverlay = false;
    this.matchFinished = false;
    this.ui.hideResults();
    this.ui.hidePause();
    this.ui.hideScreens();
    this.ui.setHUD(true);
    this.ui.setTouchVisible(this.isTouch);
    this.ui.setOnlineWaiting(false);
    this.attachWorld(world, { mode: 'online-host', ranked: true, online: true, opponentMmr: guest.mmr, guestName: guest.name });
    this.audio.startEngine();
    this.audio.startCrowd();
    this.audio.crowdIntensity(0.2);
    this.online.status = 'connected';
    this.ui.showBanner('3', 'count', 900);
    this.audio.countdown(3);
    this.ui.setBlueLabel(this.save.data.name);
    this.ui.setOrangeLabel(guest.name);
    this.ui.toast('Partida online', `${guest.name} entrou na arena.`, 'gold');
    this.ui.refresh();
  }

  beginOnlineGuestMatch(data) {
    const theme = THEMES.find((t) => t.id === data.themeId) || THEMES[0];
    const hostDef = CAR_BY_ID[data.hostCarId] || CARS[0];
    const guestDef = CAR_BY_ID[data.guestCarId] || CAR_BY_ID[this.save.data.car] || CARS[0];
    const teamSize = data.teamSize || 1;
    const bots = Array.isArray(data.bots) ? data.bots : [];
    const setups = [
      { id: 'host', team: 0, def: hostDef, name: data.hostName || 'Host', isBot: false },
      { id: 'guest', team: 1, def: guestDef, isLocal: true, name: this.save.data.name },
    ];
    for (const bot of bots) {
      const def = CAR_BY_ID[bot.defId] || CARS[0];
      setups.push({ id: bot.id, team: bot.team, def, isBot: true, name: bot.name, difficulty: 3 });
    }
    const world = new World({ carSetups: setups, theme, mode: 'online-guest', duration: data.duration || 180, teamSize, authorative: false });
    this.localCarId = 'guest';
    this.hostRemoteInput = { ...IDLE_INPUT };
    world.setController('guest', () => this.currentInput);
    world.setController('host', () => this.hostRemoteInput);
    this.mode = 'online-guest';
    this.state = 'playing';
    this.paused = false;
    this.pauseOverlay = false;
    this.matchFinished = false;
    this.ui.hideResults();
    this.ui.hidePause();
    this.ui.hideScreens();
    this.ui.setHUD(true);
    this.ui.setTouchVisible(this.isTouch);
    this.ui.setOnlineWaiting(false);
    this.attachWorld(world, {
      mode: 'online-guest',
      ranked: true,
      online: true,
      opponentMmr: Number(data.hostMmr) || 600,
      hostName: data.hostName || 'Host',
    });
    this.audio.startEngine();
    this.audio.startCrowd();
    this.audio.crowdIntensity(0.2);
    this.online.status = 'connected';
    this.ui.showBanner('3', 'count', 900);
    this.audio.countdown(3);
    this.ui.setBlueLabel(data.hostName || 'Host');
    this.ui.setOrangeLabel(this.save.data.name);
    this.ui.toast('Partida online', `Conectado à sala de ${data.hostName || 'Host'}.`, 'gold');
    this.ui.refresh();
  }

  requestRematch() {
    if (this.mode === 'online-host') {
      if (!this.net.connected) { this.returnToMenu(); return; }
      this.beginOnlineHostMatch();
    } else if (this.mode === 'online-guest') {
      if (!this.net.connected) { this.returnToMenu(); return; }
      this.net.send({ type: 'rematch' });
      this.ui.toast('Revanche solicitada', 'Aguardando o host iniciar a nova partida…', 'gold');
    } else if (this.lastConfig) {
      this.ui.hideResults();
      if (this.matchMeta?.ranked) this.startRankedAI({ ...this.lastConfig, ranked: true });
      else this.startOffline(this.lastConfig);
    }
  }

  // ---------- loop ----------
  loop(now) {
    requestAnimationFrame(this.loop);
    const rawDt = Math.min(0.05, Math.max(0, (now - this.lastT) / 1000));
    this.lastT = now;
    this.elapsed += rawDt;
    if (!this.world) return;

    if (this.state === 'menu') {
      this.acc += rawDt;
      const step = 1 / 120;
      let guard = 0;
      while (this.acc >= step && guard++ < 8) {
        this.world.step(step);
        this.acc -= step;
      }
      this.world.events.length = 0;
      this.renderer.update(rawDt, this.world, { cameraMode: 'menu' });
      return;
    }

    if (this.state === 'playing' || this.state === 'results') {
      const online = this.mode.startsWith('online');
      const running = this.state === 'playing' && (!this.pauseOverlay || online) && !this.matchFinished;
      if (this.state === 'playing' && !this.pauseOverlay) {
        this.currentInput = this.input.read();
        if (this.currentInput.cameraToggle) {
          this.renderer.toggleBallCam();
          this.ui.toast('Câmera', this.renderer.cameraState.ballCam ? 'Câmera na bola' : 'Câmera no carro', 'cyan');
        }
        if (online && this.mode === 'online-guest') {
          this.online.inputTimer += rawDt;
          if (this.online.inputTimer >= 0.033) {
            this.online.inputTimer = 0;
            this.net.send({
              type: 'input',
              input: {
                throttle: this.currentInput.throttle,
                steer: this.currentInput.steer,
                boost: this.currentInput.boost,
                drift: this.currentInput.drift,
                airRoll: this.currentInput.airRoll,
              },
            });
            if (this.currentInput.jumpPressed) this.net.send({ type: 'jump' });
          }
        }
        if (online && this.mode === 'online-host') {
          this.online.snapTimer += rawDt;
          if (this.online.snapTimer >= 0.05 && this.net.connected) {
            this.online.snapTimer = 0;
            const snap = this.world.getSnapshot({
              hi: {
                throttle: this.currentInput.throttle,
                steer: this.currentInput.steer,
                boost: this.currentInput.boost,
                drift: this.currentInput.drift,
                airRoll: this.currentInput.airRoll,
              },
            });
            this.net.send({ type: 'snap', ...snap });
          }
        }
      }

      if (running) {
        this.acc += rawDt;
        const step = 1 / 120;
        let guard = 0;
        this.world.events.length = 0;
        while (this.acc >= step && guard++ < 10) {
          this.world.step(step);
          this.currentInput.jumpPressed = false;
          if (this.online.guestJump) {
            // will be consumed next controller call
          }
          this.acc -= step;
        }
        if (this.acc > 0.25) this.acc = 0;
        this.processEvents();
        this.trackStats();
        // guest: feed host input from latest snapshot for prediction
        if (this.mode === 'online-guest' && this.online.lastSnapshot?.hi) {
          const hi = this.online.lastSnapshot.hi;
          this.hostRemoteInput = { ...this.hostRemoteInput, ...hi, jumpPressed: false };
          if (this.online.lastSnapshot.phase) this.world.phase = this.online.lastSnapshot.phase;
          if (Array.isArray(this.online.lastSnapshot.score)) this.world.score = [...this.online.lastSnapshot.score];
          if (typeof this.online.lastSnapshot.t === 'number') this.world.matchTime = this.online.lastSnapshot.t;
          if (this.online.lastSnapshot.overtime) this.world.overtime = true;
        }
      }
      this.updateHud(rawDt);
      this.updateEngineAudio();
      if (this.state === 'playing' && this.hintsTimer < 100) this.hintsTimer += rawDt;

      this.renderer.update(rawDt, this.world, {
        cameraMode: 'chase',
        carId: this.localCarId,
        paused: this.pauseOverlay,
      });
      if (this.mode === 'demo') return;
    }
  }

  trackStats() {
    const car = this.world.cars.find((c) => c.id === this.localCarId);
    if (car && this.boostPrev != null) {
      const used = this.boostPrev - car.boost;
      if (used > 0 && used < 5) this.matchStats.boost += used;
    }
    if (car) this.boostPrev = car.boost;
  }

  processEvents() {
    const events = this.world.events;
    if (!events.length) return;
    for (const event of events) {
      this.handleEvent(event);
    }
    events.length = 0;
  }

  handleEvent(event) {
    if (!event) return;
    const localCar = this.world?.cars.find((c) => c.id === this.localCarId);
    const near = event.pos && localCar
      ? Math.hypot(event.pos.x - localCar.pos.x, event.pos.z - localCar.pos.z) < 34
      : false;
    switch (event.type) {
      case 'hit': {
        this.renderer.handleEvent(event, this.world);
        if (near) this.audio.hit(event.power);
        if (this.mode.startsWith('online') && this.mode === 'online-host') {
          this.net.send({ type: 'event', event: { type: 'hit', pos: event.pos, power: event.power } });
        }
        break;
      }
      case 'jump': case 'flip': case 'land': case 'drift': {
        this.renderer.handleEvent(event, this.world);
        if (near) {
          if (event.type === 'jump') this.audio.jump();
          if (event.type === 'flip') this.audio.flip();
          if (event.type === 'land') this.audio.land();
        }
        break;
      }
      case 'boost': {
        this.renderer.handleEvent(event, this.world);
        if (event.carId === this.localCarId) this.audio.boostPickup(event.big);
        break;
      }
      case 'save': {
        if (event.carId === this.localCarId) {
          this.matchStats.saves += 1;
          this.ui.showBanner('DEFESA!', 'sub', 700);
        }
        break;
      }
      case 'demolish': {
        this.renderer.handleEvent(event, this.world);
        this.audio.demolish();
        if (event.attackerId === this.localCarId) this.matchStats.demos += 1;
        if (event.carId === this.localCarId) this.ui.showBanner('DEMOLIDO', 'loss', 1200);
        if (this.mode === 'online-host') this.net.send({ type: 'event', event: { type: 'demolish', pos: event.pos } });
        break;
      }
      case 'wallHit': case 'ballBounce': {
        if (near) this.audio.hit(Math.min(0.7, (event.power || 10) / 40));
        break;
      }
      case 'countdown': {
        this.ui.showBanner(String(event.n), 'count', 700);
        this.audio.countdown(event.n);
        break;
      }
      case 'go': {
        this.ui.showBanner('VAI!', 'goal', 600);
        this.audio.countdown(0);
        this.hintsTimer = 0;
        break;
      }
      case 'overtime': {
        this.ui.showBanner('PRORROGAÇÃO', 'goal', 1800);
        this.ui.toast('Prorrogação', 'O próximo gol decide a partida!', 'orange');
        break;
      }
      case 'goal': {
        this.presentGoal(event.team, event.scorer, this.world.score);
        if (this.mode === 'online-host') {
          this.net.send({
            type: 'goal',
            team: event.team,
            scorer: event.scorer?.name || '',
            ownGoal: event.scorer?.ownGoal,
            score: [...this.world.score],
            time: this.world.matchTime,
          });
        }
        break;
      }
      case 'end': {
        if (this.mode === 'online-host') {
          this.net.send({ type: 'end', winner: event.winner, score: event.score });
        }
        if (!this.matchFinished) this.finishMatch(event.winner, { fromNet: false });
        break;
      }
      default: break;
    }
  }

  presentGoal(team, scorer, score) {
    const localTeam = this.matchMeta?.localTeam ?? 0;
    const isLocalGoal = team === localTeam;
    const label = scorer?.ownGoal ? 'GOL CONTRA!' : isLocalGoal ? 'GOL!' : 'GOL SOFRIDO';
    this.ui.showBanner(label, `goal ${team === 1 ? 'orange' : ''}`, 2200);
    this.ui.flash(team === 0 ? 'blue' : 'orange');
    this.audio.goal(team === 0);
    this.renderer.handleEvent({ type: 'goal', team }, this.world);
    this.audio.crowdIntensity(0.75);
    setTimeout(() => this.audio.crowdIntensity(0.25), 2800);
    if (this.world) {
      this.world.score = [...score];
      this.ui.setScore(score);
    }
    if (scorer && scorer.carId && scorer.carId === this.localCarId && !scorer.ownGoal) {
      this.matchStats.goals += 1;
    }
  }

  updateHud(dt) {
    this.ui.updateHUD(this.world, this.world.cars.find((c) => c.id === this.localCarId), {
      ballCam: this.renderer.cameraState.ballCam,
      touch: this.isTouch,
      hints: this.hintsTimer < 14,
      mode: this.mode,
    });
    // screen labels
    const blue = this.world.cars.find((c) => c.team === 0 && !c.isBot);
    const orange = this.world.cars.find((c) => c.team === 1 && !c.isBot);
    if (blue) this.ui.setBlueLabel(blue.isLocal ? this.save.data.name : blue.name);
    if (orange) this.ui.setOrangeLabel(orange.isLocal ? `${this.save.data.name} (você)` : orange.name);
  }

  updateEngineAudio() {
    const car = this.world?.cars.find((c) => c.id === this.localCarId);
    if (!car) return;
    const speed = Math.hypot(car.vel.x, car.vel.z);
    this.audio.updateEngine(speed, car.lastInput?.throttle || 0, car.boostActive, car.drifting, !car.onGround, this.state === 'playing' && !this.pauseOverlay);
  }

  // ---------- end of match ----------
  finishMatch(winner, { fromNet = false } = {}) {
    if (this.matchFinished || !this.world) return;
    if (this.mode === 'demo') return;
    this.matchFinished = true;
    this.state = 'results';
    this.input.setPlaying(false);
    this.ui.setTouchVisible(false);
    const localTeam = this.matchMeta?.localTeam ?? 0;
    const won = winner === localTeam;
    const draw = winner === null || winner === undefined;
    const stats = this.matchStats || { goals: 0, saves: 0, demos: 0, boost: 0 };
    const meta = this.matchMeta || {};
    const ranked = !!meta.ranked;
    let rankBefore = null;
    let rankAfter = null;
    let delta = 0;
    if (ranked) {
      const isOnline = this.mode.startsWith('online');
      const board = isOnline ? this.save.data.online : this.save.data.offline;
      const beforeMmr = board.mmr;
      const opp = meta.opponentMmr ?? (isOnline ? 620 : 500 + (meta.difficulty || 2) * 260);
      const expected = 1 / (1 + 10 ** ((opp - beforeMmr) / 420));
      const scoreVal = draw ? 0.5 : won ? 1 : 0;
      const streakBonus = won && board.streak >= 2 ? 2 : 0;
      delta = Math.round(30 * (scoreVal - expected)) + streakBonus;
      delta = Math.max(-34, Math.min(36, delta));
      board.mmr = Math.max(0, beforeMmr + delta);
      if (won) { board.wins += 1; board.streak += 1; } else if (!draw) { board.losses += 1; board.streak = 0; }
      board.best = Math.max(board.best || 0, board.mmr);
      rankBefore = getRank(beforeMmr);
      rankAfter = getRank(board.mmr);
      this.save.data.bestRank = Math.max(this.save.data.bestRank || 0, board.mmr);
    }
    // rewards
    const winBonus = won ? 170 : draw ? 110 : 80;
    const rankedBonus = ranked ? 60 : 0;
    const onlineBonus = this.mode.startsWith('online') ? 80 : 0;
    let credits = winBonus + rankedBonus + onlineBonus + stats.goals * 18 + stats.saves * 12 + stats.demos * 15;
    let xp = (won ? 220 : draw ? 140 : 100) + stats.goals * 22 + stats.saves * 12 + stats.demos * 10;
    this.save.data.credits += credits;
    const levelRes = addXp(this.save.data, xp);
    if (levelRes.bonus) this.save.data.credits += levelRes.bonus;
    // stats
    const s = this.save.data.stats;
    s.matches += 1;
    if (won) s.wins += 1;
    s.goals += stats.goals;
    s.saves += stats.saves;
    s.demolitions += stats.demos;
    s.boost += Math.round(stats.boost);
    if (this.mode.startsWith('online')) {
      if (won) s.onlineWins = (s.onlineWins || 0) + 1;
    }
    this.save.flush();
    const unlockedCars = this.checkFreeCars(false);
    const achievements = this.save.checkAchievements();
    this.save.flush();

    if (won) { this.audio.win(); } else if (draw) { this.audio.whistle(); } else { this.audio.lose(); }
    this.audio.crowdIntensity(won ? 0.7 : 0.25);
    setTimeout(() => this.audio.crowdIntensity(0.12), 3200);
    this.audio.stopEngine();

    const result = {
      won, draw,
      score: [...this.world.score],
      localTeam,
      mode: this.mode,
      ranked,
      online: this.mode.startsWith('online'),
      opponentName: meta.guestName || meta.hostName || this.world.cars.find((c) => c.team !== localTeam && !c.isBot)?.name || 'Rival',
      duration: Math.round(this.world.duration - this.world.matchTime),
      stats,
      credits,
      xp,
      levelUps: levelRes.leveled,
      levelBonus: levelRes.bonus,
      rankBefore, rankAfter, delta,
      unlockedCars,
      achievements,
      overtime: this.world.overtime,
      level: this.save.data.level,
      xpProgress: levelProgress(this.save.data),
      rematchEnabled: this.mode.startsWith('online') ? this.net.connected : true,
    };
    this.ui.showResults(result);
    this.ui.refresh();
    this.online.rematchPending = false;
    for (const car of unlockedCars) {
      this.ui.toast('Carro grátis desbloqueado', `${car.name} está na garagem!`, 'gold');
      this.audio.ui('levelup');
    }
    for (const a of achievements) {
      this.ui.toast('Conquista desbloqueada', `${a.name} • +${a.reward} créditos`, 'gold');
    }
    this.ui.setHUD(false);
    this.ui.setOnlineWaiting(false);
  }

  // ---------- garage ----------
  buyCar(id) {
    const car = CAR_BY_ID[id];
    if (!car) return false;
    if (this.save.data.owned.includes(id)) {
      this.selectCar(id);
      return true;
    }
    if (car.unlockLevel > 0 && car.price === 0 && this.save.data.level < car.unlockLevel) {
      this.ui.toast('Ainda bloqueado', `Alcance o nível ${car.unlockLevel} para ganhar este carro grátis.`, 'orange');
      this.audio.ui('error');
      return false;
    }
    if (car.price > 0 && this.save.data.credits < car.price) {
      this.ui.toast('Créditos insuficientes', `Faltam ${(car.price - this.save.data.credits).toLocaleString('pt-BR')} créditos. Jogue partidas para ganhar mais.`, 'orange');
      this.audio.ui('error');
      return false;
    }
    if (car.price > 0) {
      this.save.data.credits -= car.price;
    }
    this.save.ownCar(id);
    this.save.data.car = id;
    this.save.flush();
    this.audio.ui('buy');
    this.ui.toast('Carro desbloqueado', `${car.name} adicionado à garagem.`, 'gold');
    this.save.checkAchievements().forEach((a) => this.ui.toast('Conquista desbloqueada', `${a.name} • +${a.reward} créditos`, 'gold'));
    this.ui.refresh();
    return true;
  }

  selectCar(id) {
    if (!this.save.data.owned.includes(id)) return false;
    this.save.data.car = id;
    this.save.flush();
    this.audio.ui('click');
    this.ui.toast('Carro equipado', `${CAR_BY_ID[id]?.name || id} selecionado.`, 'cyan');
    this.ui.refresh();
    return true;
  }

  get selectedCar() {
    return CAR_BY_ID[this.save.data.car] || CARS[0];
  }

  get rankOnline() { return getRank(this.save.data.online.mmr); }
  get rankOffline() { return getRank(this.save.data.offline.mmr); }
}

