  }
  this.attachWorld(world, { mode, ranked });
  this.ui.setHUD(true);
  this.ui.hideScreens();
  this.ui.setTouchVisible(this.isTouch);
  this.ui.showBanner('3', 'count', 900);
  this.audio.countdown(3);
