import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.stack));
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.locator('[data-nav="play"]').first().click();
await page.waitForTimeout(400);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(5000);
console.log('STATE', await page.evaluate(() => {
  const g = window.turboStrike;
  const c = g.world.cars.find((x) => x.id === 'local');
  return { phase: g.world.phase, countdown: g.world.countdown, playing: g.input.playing, state: g.state, pause: g.pauseOverlay, keys: [...g.input.keys], input: g.currentInput, pos: c.pos.toArray(), vel: c.vel.toArray() };
}));
await page.evaluate(() => document.body.focus());
await page.keyboard.down('w');
await page.waitForTimeout(1200);
console.log('HELD', await page.evaluate(() => {
  const g = window.turboStrike;
  const c = g.world.cars.find((x) => x.id === 'local');
  return { keys: [...g.input.keys], input: g.currentInput, phase: g.world.phase, pos: c.pos.toArray().map((v) => +v.toFixed(2)), vel: c.vel.toArray().map((v) => +v.toFixed(2)), modelPos: c.model?.position?.toArray?.() };
}));
await page.keyboard.up('w');
await page.screenshot({ path: '/tmp/opencode/drive.png' });
console.log('ERRORS', errors.join('\n'));
await browser.close();

