import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 760 } });
await page.addInitScript(() => {
  try {
    localStorage.setItem('turbo-strike-save-v1', JSON.stringify({
      credits: 5000,
      settings: { quality: 'low', volume: 0 },
    }));
  } catch {}
});
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.stack));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
page.on('response', (r) => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });

const log = (...a) => console.log(...a);
const ev = (fn, arg) => page.evaluate(fn, arg);

await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1800);
log('1 HOME', JSON.stringify(await ev(() => ({
  booted: !!window.turboStrike,
  loading: getComputedStyle(document.getElementById('loading')).display,
  title: document.querySelector('.brand-title')?.textContent,
  cars: window.turboStrike.world.cars.length,
  menuState: window.turboStrike.state,
}))));

for (const [nav, expected] of [['garage', 'Garagem'], ['leaderboard', 'Ranking'], ['settings', 'Ajustes'], ['howto', 'Como Jogar'], ['online', 'Multijogador Online'], ['play', 'Jogar Offline']]) {
  await page.locator(`[data-nav="${nav}"]`).first().click();
  await page.waitForTimeout(350);
  const heading = await ev(() => document.querySelector('.shell-title h1')?.textContent || document.querySelector('.hero-title')?.textContent);
  log(`2 NAV ${nav}`, JSON.stringify({ heading, ok: String(heading).includes(expected) }));
}

// GARAGE
await page.locator('[data-nav="garage"]').first().click();
await page.waitForTimeout(900);
const garage0 = await ev(() => ({
  items: document.querySelectorAll('.car-item').length,
  equipped: window.turboStrike.save.data.car,
  credits: window.turboStrike.save.data.credits,
}));
log('3 GARAGE', JSON.stringify(garage0));
await page.locator('[data-car="raptor"]').click();
await page.waitForTimeout(400);
await page.locator('[data-action="equip-car"]').click();
await page.waitForTimeout(500);
log('3 EQUIP', JSON.stringify(await ev(() => ({ car: window.turboStrike.save.data.car, toast: document.querySelector('.toast')?.textContent?.trim() }))));

// OFFLINE 2v2
await page.locator('[data-nav="play"]').first().click();
await page.waitForTimeout(300);
await page.locator('[data-action="play-opt"][data-key="teamSize"][data-value="2"]').click();
await page.waitForTimeout(300);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(2500);
log('4 MATCH START', JSON.stringify(await ev(() => ({
  state: window.turboStrike.state,
  mode: window.turboStrike.mode,
  cars: window.turboStrike.world.cars.map((c) => ({ id: c.id, team: c.team, bot: c.isBot, pos: c.pos.toArray().map((v) => Math.round(v)) })),
  hud: !document.getElementById('hud').classList.contains('hidden'),
  teamSize: window.turboStrike.world.teamSize,
}))));

// Force play + drive through physics directly
const drive = await ev(() => {
  const g = window.turboStrike;
  const w = g.world;
  w.phase = 'play';
  w.countdown = 0;
  g.currentInput = { throttle: 1, steer: 0, boost: true, drift: false, jumpPressed: false, airRoll: 0 };
  const car = w.cars.find((c) => c.isLocal);
  const start = car.pos.clone();
  const startBoost = car.boost;
  for (let i = 0; i < 240; i++) { w.step(1 / 120); g.currentInput.jumpPressed = false; }
  g.processEvents();
  return {
    start: start.toArray().map((v) => +v.toFixed(2)),
    end: car.pos.toArray().map((v) => +v.toFixed(2)),
    moved: +start.distanceTo(car.pos).toFixed(2),
    speed: +car.vel.length().toFixed(2),
    boostBefore: Math.round(startBoost), boostAfter: Math.round(car.boost),
    onGround: car.onGround,
  };
});
log('4 DRIVE', JSON.stringify(drive));

// Jump test
const jump = await ev(() => {
  const g = window.turboStrike; const w = g.world; const car = w.cars.find((c) => c.isLocal);
  g.currentInput.jumpPressed = true;
  w.step(1 / 120);
  const y1 = car.pos.y;
  for (let i = 0; i < 20; i++) { g.currentInput.jumpPressed = false; w.step(1 / 120); }
  return { yAfter: +car.pos.y.toFixed(2), rose: car.pos.y > 0.6 || y1 > 0.6, jumps: car.jumps };
});
log('4 JUMP', JSON.stringify(jump));

// Force a blue goal
const goal = await ev(() => {
  const g = window.turboStrike; const w = g.world;
  const car = w.cars.find((c) => c.isLocal);
  w.phase = 'play';
  w.ball.pos.set(0, 3, 61.8);
  w.ball.vel.set(0, 0, 2);
  w.ball.lastTouch = car;
  w.events.length = 0;
  w.checkGoal();
  g.processEvents();
  return { score: w.score, phase: w.phase, banner: document.getElementById('banner')?.textContent, goals: g.matchStats.goals };
});
log('5 GOAL', JSON.stringify(goal));

// Force end of match
const ended = await ev(() => {
  const g = window.turboStrike; const w = g.world;
  const creditsBefore = g.save.data.credits;
  const matchesBefore = g.save.data.stats.matches;
  w.phase = 'play'; w.matchTime = 0.001; w.score = [2, 0];
  w.step(1 / 120);
  g.processEvents();
  return {
    state: g.state, finished: g.matchFinished,
    resultsVisible: document.getElementById('results-overlay').classList.contains('active'),
    resultsTitle: document.querySelector('#results-overlay .result-title')?.textContent,
    creditsBefore, creditsAfter: g.save.data.credits,
    matchesBefore, matchesAfter: g.save.data.stats.matches,
    level: g.save.data.level,
    rankDelta: document.querySelector('.rank-delta')?.textContent?.trim().slice(0, 40),
  };
});
log('6 RESULT', JSON.stringify(ended));
await page.screenshot({ path: '/tmp/opencode/05-results.png' });

// Back to menu
await page.locator('[data-action="menu"]').click();
await page.waitForTimeout(700);
log('7 MENU BACK', JSON.stringify(await ev(() => ({ state: window.turboStrike.state, mode: window.turboStrike.mode, screen: document.querySelector('#screen-root .screen')?.className }))));

// RANKED QUICK
await page.locator('[data-action="ranked-quick"]').click();
await page.waitForTimeout(400);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(2000);
const ranked = await ev(() => {
  const g = window.turboStrike;
  const before = g.save.data.offline.mmr;
  const w = g.world;
  w.phase = 'play'; w.matchTime = 0.001; w.score = [1, 0];
  w.step(1 / 120); g.processEvents();
  return {
    mode: g.mode, ranked: g.matchMeta?.ranked, mmrBefore: before, mmrAfter: g.save.data.offline.mmr,
    winDelta: document.querySelector('.rank-delta')?.textContent?.trim().slice(0, 30),
    results: document.getElementById('results-overlay').classList.contains('active'),
  };
});
log('8 RANKED', JSON.stringify(ranked));
await page.locator('[data-action="menu"]').click();
await page.waitForTimeout(700);

// ONLINE room
await page.locator('[data-nav="online"]').first().click();
await page.waitForTimeout(400);
await page.locator('[data-action="host-room"]').click();
await page.waitForTimeout(9000);
const online = await ev(() => ({
  status: window.turboStrike.online.status,
  code: window.turboStrike.online.code,
  codeLen: (window.turboStrike.online.code || '').length,
  statusText: document.getElementById('online-status-text')?.textContent,
  roomBox: document.getElementById('room-code-box')?.textContent,
  hasPeer: !!window.turboStrike.net.peer,
}));
log('9 ONLINE HOST', JSON.stringify(online));
if (online.code) {
  await page.screenshot({ path: '/tmp/opencode/06-online-room.png' });
  await page.locator('[data-action="cancel-room"]').click();
  await page.waitForTimeout(600);
  log('9 ONLINE CANCEL', JSON.stringify(await ev(() => ({ status: window.turboStrike.online.status, code: window.turboStrike.online.code, text: document.getElementById('online-status-text')?.textContent }))));
}

// Invalid join
await page.locator('[data-action="nav"]').first().click();
await page.waitForTimeout(300);
await page.locator('[data-nav="online"]').first().click();
await page.waitForTimeout(400);
await page.locator('#room-code-input').fill('ZZZZZ');
await page.locator('[data-action="join-room"]').click();
await page.waitForTimeout(7000);
log('10 INVALID JOIN', JSON.stringify(await ev(() => ({ status: window.turboStrike.online.status, text: document.getElementById('online-status-text')?.textContent, toast: document.querySelector('.toast')?.textContent?.trim() }))));

log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

