import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
async function makePage(name) {
  const ctx = await browser.newContext({ viewport: { width: 900, height: 620 } });
  const page = await ctx.newPage();
  await page.addInitScript((n) => {
    try {
      localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ name: n, credits: 3000, settings: { quality: 'low', volume: 0 } }));
    } catch {}
  }, name);
  page.on('pageerror', (e) => errors.push(name + ' PAGEERROR ' + e.stack));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(name + ' CONSOLE ' + m.text()); });
  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load', timeout: 45000 });
  await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
  return page;
}
const host = await makePage('HostTeste');
const guest = await makePage('GuestTeste');

await host.locator('[data-nav="online"]').first().click();
await host.waitForTimeout(400);
await host.locator('[data-action="host-room"]').click();
await host.waitForFunction(() => window.turboStrike.online.code?.length === 5, null, { timeout: 25000 });
const code = await host.evaluate(() => window.turboStrike.online.code);
console.log('ROOM_CODE', code);

await guest.locator('[data-nav="online"]').first().click();
await guest.waitForTimeout(400);
await guest.locator('#room-code-input').fill(code);
await guest.locator('[data-action="join-room"]').click();

await host.waitForFunction(() => window.turboStrike.mode === 'online-host' && window.turboStrike.state === 'playing', null, { timeout: 30000 }).catch(() => {});
await guest.waitForFunction(() => window.turboStrike.mode === 'online-guest' && window.turboStrike.state === 'playing', null, { timeout: 30000 }).catch(() => {});

const info = (p) => p.evaluate(() => {
  const g = window.turboStrike;
  return {
    mode: g.mode, state: g.state, status: g.online.status, code: g.online.code,
    localCarId: g.localCarId, cars: g.world?.cars.map((c) => ({ id: c.id, team: c.team, pos: c.pos.toArray().map((v) => +v.toFixed(1)) })),
    score: g.world?.score, hud: !document.getElementById('hud').classList.contains('hidden'),
    netConnected: g.net.connected, peerOpen: !!g.net.peer?.open,
  };
});
console.log('HOST', JSON.stringify(await info(host)));
console.log('GUEST', JSON.stringify(await info(guest)));

// Move guest and see host remote input / snapshot sync
await guest.evaluate(() => { const g = window.turboStrike; g.world.phase = 'play'; g.world.countdown = 0; });
await host.evaluate(() => { const g = window.turboStrike; g.world.phase = 'play'; g.world.countdown = 0; });
await guest.keyboard.down('w');
await guest.keyboard.down('Shift');
await guest.waitForTimeout(2500);
await guest.keyboard.up('Shift');
await guest.keyboard.up('w');
await guest.waitForTimeout(600);
const sync = {
  host: await host.evaluate(() => {
    const g = window.turboStrike;
    const guestCar = g.world.cars.find((c) => c.id === 'guest');
    return { remoteInput: g.online.remoteInput, guestPos: guestCar.pos.toArray().map((v) => +v.toFixed(2)), snapshotSent: g.online.snapTimer >= 0 };
  }),
  guest: await guest.evaluate(() => {
    const g = window.turboStrike;
    const car = g.world.cars.find((c) => c.id === 'guest');
    return { pos: car.pos.toArray().map((v) => +v.toFixed(2)), lastSnapshot: !!g.online.lastSnapshot, hostPos: g.world.cars.find((c) => c.id === 'host')?.pos.toArray().map((v) => +v.toFixed(2)) };
  }),
};
console.log('SYNC', JSON.stringify(sync));
await host.screenshot({ path: '/tmp/opencode/07-online-host.png' });
await guest.screenshot({ path: '/tmp/opencode/08-online-guest.png' });

// Host scores, guest should receive goal
const goal = await host.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  g.net.send({ type: 'goal', team: 0, scorer: 'HostTeste', score: [1, 0], time: w.matchTime });
  return true;
});
await guest.waitForTimeout(1200);
console.log('GOAL_SYNC', JSON.stringify(await guest.evaluate(() => ({ score: window.turboStrike.world.score, hudScore: document.getElementById('score-blue')?.textContent }))));

// Leaving host should end guest connection
await host.evaluate(() => window.turboStrike.net.close());
await guest.waitForTimeout(1500);
console.log('DISCONNECT', JSON.stringify(await guest.evaluate(() => ({ status: window.turboStrike.online.status, state: window.turboStrike.state, text: document.getElementById('online-status-text')?.textContent }))));

console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

