import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];

const ctx = await browser.newContext({ viewport: { width: 1100, height: 760 } });
const page = await ctx.newPage();
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.stack));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ credits: 5000, settings: { quality: 'low', volume: 0.5 } })); } catch {} });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });

// BUY CAR
await page.locator('[data-nav="garage"]').first().click();
await page.waitForTimeout(700);
await page.locator('[data-car="viper"]').click();
await page.waitForTimeout(350);
const beforeBuy = await page.evaluate(() => ({ credits: window.turboStrike.save.data.credits, owned: window.turboStrike.save.data.owned.includes('viper'), button: document.querySelector('[data-action="buy-car"]')?.textContent?.trim() }));
await page.locator('[data-action="buy-car"]').click();
await page.waitForTimeout(600);
const afterBuy = await page.evaluate(() => ({ credits: window.turboStrike.save.data.credits, owned: window.turboStrike.save.data.owned.includes('viper'), car: window.turboStrike.save.data.car, toast: document.querySelector('.toast')?.textContent?.trim(), wallet: document.querySelector('.wallet-pill span')?.textContent }));
console.log('BUY', JSON.stringify({ beforeBuy, afterBuy }));

// insufficient (phantom 5200 > 4350)
const poor = await page.evaluate(() => {
  const g = window.turboStrike;
  const before = g.save.data.credits;
  const ok = g.buyCar('phantom');
  return { ok, before, after: g.save.data.credits, owned: g.save.data.owned.includes('phantom'), disabled: document.querySelector('[data-action="buy-car"]')?.disabled };
});
console.log('INSUFFICIENT', JSON.stringify(poor));

// SETTINGS
await page.locator('.back-btn').first().click();
await page.waitForTimeout(350);
await page.locator('[data-nav="settings"]').first().click();
await page.waitForTimeout(500);
const settingsBefore = await page.evaluate(() => ({ settings: window.turboStrike.save.data.settings, quality: window.turboStrike.renderer.quality, ballCam: window.turboStrike.renderer.cameraState.ballCam }));
await page.locator('[data-action="set-camera"][data-value="car"]').click();
await page.waitForTimeout(350);
await page.locator('[data-action="set-quality"][data-value="medium"]').click();
await page.waitForTimeout(350);
await page.locator('[data-action="set-shake"][data-value="0"]').click();
await page.waitForTimeout(400);
const settingsAfter = await page.evaluate(() => ({ settings: window.turboStrike.save.data.settings, quality: window.turboStrike.renderer.quality, ballCam: window.turboStrike.renderer.cameraState.ballCam }));
console.log('SETTINGS', JSON.stringify({ settingsBefore, settingsAfter }));

// reload persistence
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
console.log('PERSIST', JSON.stringify(await page.evaluate(() => {
  const g = window.turboStrike;
  return { credits: g.save.data.credits, car: g.save.data.car, owned: g.save.data.owned.length, settings: g.save.data.settings };
})));

// LEADERBOARD TABS
await page.locator('[data-nav="leaderboard"]').first().click();
await page.waitForTimeout(500);
const board1 = await page.evaluate(() => ({ rows: document.querySelectorAll('.board-row, .lb-row, .leader-row').length, head: document.querySelector('.shell-title h1')?.textContent, tabs: [...document.querySelectorAll('[data-action="board-tab"]')].map((b) => b.textContent.trim()) }));
await page.locator('[data-action="board-tab"][data-value="offline"]').click();
await page.waitForTimeout(450);
const board2 = await page.evaluate(() => ({ rows: document.querySelectorAll('.board-row, .lb-row, .leader-row').length, head: document.querySelector('.shell-title h1')?.textContent }));
console.log('LEADERBOARD', JSON.stringify({ board1, board2 }));

// REMATCH from results already tested; test HUD updates during match
await page.locator('.back-btn').first().click();
await page.waitForTimeout(300);
await page.locator('[data-nav="play"]').first().click();
await page.waitForTimeout(300);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(2200);
const hud = await page.evaluate(() => {
  const g = window.turboStrike;
  return { score: [document.getElementById('score-blue').textContent, document.getElementById('score-orange').textContent], clock: document.getElementById('clock').textContent, speed: document.getElementById('speed').textContent, boost: document.getElementById('boost-value').textContent, labels: [document.getElementById('blue-sub').textContent, document.getElementById('orange-sub').textContent] };
});
console.log('HUD', JSON.stringify(hud));
await page.screenshot({ path: '/tmp/opencode/11-desktop-match.png' });

// MOBILE
const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const mob = await mctx.newPage();
mob.on('pageerror', (e) => errors.push('MOBILE PAGEERROR ' + e.stack));
mob.on('console', (m) => { if (m.type() === 'error') errors.push('MOBILE CONSOLE ' + m.text()); });
await mob.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ credits: 2000, settings: { quality: 'low', volume: 0 } })); } catch {} });
await mob.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await mob.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
await mob.waitForTimeout(800);
console.log('MOBILE HOME', JSON.stringify(await mob.evaluate(() => ({ isTouch: window.turboStrike.isTouch, width: innerWidth, rotHint: getComputedStyle(document.getElementById('rotate-hint')).display, homeVisible: !!document.querySelector('.home') }))));
await mob.screenshot({ path: '/tmp/opencode/12-mobile-home.png' });
await mob.locator('[data-nav="play"]').first().click();
await mob.waitForTimeout(500);
await mob.locator('[data-action="start-offline"]').click();
await mob.waitForTimeout(2600);
const mobileMatch = await mob.evaluate(() => ({
  isTouch: window.turboStrike.isTouch,
  hud: !document.getElementById('hud').classList.contains('hidden'),
  touchVisible: document.getElementById('touch-controls').classList.contains('visible') && !document.getElementById('touch-controls').classList.contains('hidden'),
  touchBound: window.turboStrike.input.touchBound,
  buttons: ['tb-jump', 'tb-boost', 'tb-drift', 'tb-cam', 'tb-menu'].map((id) => !!document.getElementById(id)),
}));
console.log('MOBILE MATCH', JSON.stringify(mobileMatch));
// joystick drag up
const zone = await mob.locator('#joy-zone').boundingBox();
if (zone) {
  const cx = zone.x + zone.width / 2, cy = zone.y + zone.height / 2;
  await mob.mouse.move(cx, cy);
  await mob.mouse.down();
  await mob.mouse.move(cx, cy - zone.height * 0.4, { steps: 5 });
  await mob.evaluate(() => { const g = window.turboStrike; g.world.phase = 'play'; g.world.countdown = 0; });
  await mob.waitForTimeout(1000);
  const touch = await mob.evaluate(() => { const g = window.turboStrike; const c = g.world.cars.find((x) => x.id === 'local'); return { touch: g.input.touch, pos: c.pos.toArray().map((v) => +v.toFixed(2)) }; });
  await mob.mouse.up();
  console.log('MOBILE JOYSTICK', JSON.stringify(touch));
}
await mob.screenshot({ path: '/tmp/opencode/13-mobile-match.png' });
console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

