import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 760 } });
await page.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ credits: 1000, settings: { quality: 'low', volume: 0 } })); } catch {} });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
await page.locator('[data-nav="play"]').first().click();
await page.waitForTimeout(300);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(2000);
await page.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  w.phase = 'play'; w.matchTime = 0.001; w.score = [1, 0];
  w.step(1 / 120); g.processEvents();
});
await page.waitForTimeout(1200);
const info = await page.evaluate(() => {
  const card = document.querySelector('#results-overlay .result-card');
  const actions = document.querySelector('#results-overlay .result-actions');
  const btns = [...document.querySelectorAll('#results-overlay .result-actions .btn')];
  const rect = (el) => el ? { x: Math.round(el.getBoundingClientRect().x), y: Math.round(el.getBoundingClientRect().y), w: Math.round(el.getBoundingClientRect().width), h: Math.round(el.getBoundingClientRect().height), display: getComputedStyle(el).display, visibility: getComputedStyle(el).visibility, opacity: getComputedStyle(el).opacity, color: getComputedStyle(el).color, bg: getComputedStyle(el).backgroundColor, zIndex: getComputedStyle(el).zIndex } : null;
  return {
    overlay: rect(document.getElementById('results-overlay')),
    card: rect(card),
    actions: rect(actions),
    buttons: btns.map((b) => ({ text: b.textContent.trim(), ...rect(b) })),
    cardHTMLTail: card?.innerHTML.slice(-500),
    scrollH: card?.scrollHeight, clientH: card?.clientHeight,
  };
});
console.log(JSON.stringify(info, null, 2));
await page.screenshot({ path: '/tmp/opencode/14-results-check.png' });
await browser.close();

