import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];

// Desktop pause
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
await page.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ credits: 1000, settings: { quality: 'low', volume: 0 } })); } catch {} });
page.on('pageerror', (e) => errors.push(e.stack));
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
await page.locator('[data-nav="play"]').first().click();
await page.waitForTimeout(300);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(1800);
await page.keyboard.press('Escape');
await page.waitForTimeout(700);
console.log('PAUSE', JSON.stringify(await page.evaluate(() => {
  const btns = [...document.querySelectorAll('#pause-overlay .btn')].map((b) => ({ text: b.textContent.trim(), h: Math.round(b.getBoundingClientRect().height), w: Math.round(b.getBoundingClientRect().width) }));
  return { active: document.getElementById('pause-overlay').classList.contains('active'), btns, cardH: Math.round(document.querySelector('#pause-overlay .result-card').getBoundingClientRect().height) };
})));
await page.screenshot({ path: '/tmp/opencode/15-pause-fixed.png' });
await page.locator('[data-action="resume"]').click();
await page.waitForTimeout(600);
console.log('RESUME', JSON.stringify(await page.evaluate(() => ({ pause: window.turboStrike.pauseOverlay, state: window.turboStrike.state, playing: window.turboStrike.input.playing }))));

// Mobile result
const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const mob = await mctx.newPage();
mob.on('pageerror', (e) => errors.push('MOBILE ' + e.stack));
await mob.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ credits: 1000, settings: { quality: 'low', volume: 0 }, offline: { mmr: 1200, wins: 4, losses: 2, streak: 2, best: 1200 } })); } catch {} });
await mob.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await mob.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
await mob.locator('[data-nav="play"]').first().click();
await mob.waitForTimeout(400);
await mob.locator('[data-action="start-offline"]').click();
await mob.waitForTimeout(2000);
await mob.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  w.phase = 'play'; w.matchTime = 0.001; w.score = [2, 1];
  w.step(1 / 120); g.processEvents();
});
await mob.waitForTimeout(1000);
console.log('MOBILE RESULT', JSON.stringify(await mob.evaluate(() => {
  const card = document.querySelector('#results-overlay .result-card');
  const r = card.getBoundingClientRect();
  const btns = [...document.querySelectorAll('#results-overlay .btn')].map((b) => { const x = b.getBoundingClientRect(); return { text: b.textContent.trim(), y: Math.round(x.y), h: Math.round(x.height) }; });
  return { card: { y: Math.round(r.y), h: Math.round(r.height), w: Math.round(r.width) }, viewport: [innerWidth, innerHeight], btns, canScroll: card.scrollHeight > card.clientHeight, overflow: getComputedStyle(document.getElementById('results-overlay')).overflow };
})));
await mob.screenshot({ path: '/tmp/opencode/16-mobile-results.png' });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

