import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 760 } });
await page.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ credits: 1000, settings: { quality: 'low', volume: 0 } })); } catch {} });
const errors = [];
page.on('pageerror', (e) => errors.push(e.stack));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 15000 });
await page.locator('[data-nav="play"]').first().click();
await page.waitForTimeout(300);
await page.locator('[data-action="play-opt"][data-key="teamSize"][data-value="3"]').click();
await page.waitForTimeout(250);
await page.locator('[data-action="play-opt"][data-key="duration"][data-value="120"]').click();
await page.waitForTimeout(250);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(1800);
const sim = await page.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  w.phase = 'play'; w.countdown = 0;
  const samples = [];
  let goals = 0;
  const start = performance.now();
  for (let i = 0; i < 7200; i++) { // 60s at 120Hz
    w.step(1 / 120);
    g.processEvents();
    if (i % 600 === 0) {
      samples.push({ t: +w.elapsed.toFixed(1), score: [...w.score], ball: w.ball.pos.toArray().map((v) => +v.toFixed(1)), cars: w.cars.filter((c) => c.y > 2).length });
    }
    if (w.phase === 'ended') break;
  }
  goals = w.score ? w.score[0] + w.score[1] : 0;
  const bad = [];
  for (const c of w.cars) {
    for (const key of ['pos', 'vel', 'quat']) {
      const vals = [...(key === 'quat' ? [c.quat.x, c.quat.y, c.quat.z, c.quat.w] : c.pos.toArray())];
      if (key === 'vel') vals.splice(0, vals.length, ...c.vel.toArray());
      if (vals.some((v) => !Number.isFinite(v))) bad.push(`${c.id}.${key}`);
    }
  }
  return { phase: w.phase, score: w.score, elapsed: +w.elapsed.toFixed(1), matchTime: +w.matchTime.toFixed(1), samples, state: g.state, results: document.getElementById('results-overlay').classList.contains('active'), bad, wallMs: Math.round(performance.now() - start), touches: w.cars.map((c) => c.touches), ballSpeed: +w.ball.vel.length().toFixed(1) };
});
console.log('SIM', JSON.stringify(sim));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

