await page.keyboard.press('Escape'); await wait(500);
await page.locator('[data-action="quit"]').click(); await wait(800);
console.log('QUIT', JSON.stringify(await page.evaluate(() => ({ state: window.turboStrike.state, mode: window.turboStrike.mode, playing: window.turboStrike.input.playing, screen: document.querySelector('#screen-root .screen')?.className }))));

// online host then back cancels
