await page.waitForFunction(() => window.turboStrike.online.code?.length === 5, null, { timeout: 25000 });
console.log('HOSTED', JSON.stringify(await page.evaluate(() => ({ status: window.turboStrike.online.status, code: window.turboStrike.online.code, uiCode: window.turboStrike.ui.roomCode }))));
await page.locator('.back-btn').first().click(); await wait(900);
console.log('BACK CANCEL', JSON.stringify(await page.evaluate(() => ({ status: window.turboStrike.online.status, code: window.turboStrike.online.code, uiCode: window.turboStrike.ui.roomCode, screen: document.querySelector('#screen-root .screen')?.className, peer: window.turboStrike.net.peer }))));
await page.locator('[data-nav="online"]').first().click(); await wait(400);
console.log('ONLINE RESET', JSON.stringify(await page.evaluate(() => ({ roomBox: document.getElementById('room-code-box')?.textContent, action: document.getElementById('host-create-btn')?.dataset.action, inputDisabled: document.getElementById('room-code-input')?.disabled }))));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

