process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = join(process.cwd(), 'screenshots');
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });

// Desktop: home + gameplay
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => { try { localStorage.setItem('turbo-strike-save-v1', JSON.stringify({ name: 'Piloto', credits: 4800, level: 7, xp: 180, settings: { quality: 'high', volume: 0 }, owned: ['falcon', 'raptor', 'bolt', 'viper'], online: { mmr: 940, wins: 12, losses: 6, streak: 3, best: 980 }, offline: { mmr: 810, wins: 8, losses: 4, streak: 2, best: 840 }, stats: { matches: 22, wins: 14, goals: 31, saves: 18, demolitions: 4, boost: 6000, ownGoals: 0 } })); } catch {} });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.waitForFunction(() => getComputedStyle(document.getElementById('loading')).display === 'none', null, { timeout: 20000 });
await page.waitForTimeout(1500);
await page.screenshot({ path: join(out, 'final-home.png') });

await page.locator('[data-nav="play"]').first().click();
