await page.locator('[data-action="play-opt"][data-key="teamSize"][data-value="2"]').click();
await page.waitForTimeout(300);
await page.locator('[data-action="start-offline"]').click();
await page.waitForTimeout(2200);

// Make an action shot: force play, drive toward the ball, then capture
await page.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  w.phase = 'play'; w.countdown = 0;
  const car = w.cars.find((c) => c.isLocal);
  car.pos.set(0, 0, -6);
  car.yaw = 0;
  g.renderer.cameraState.pos.set(0, 7, -18);
  g.renderer.cameraState.look.set(0, 3, 4);
});
await page.waitForTimeout(700);
const ballShot = await page.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  w.ball.pos.set(2, 7, 12);
  w.ball.vel.set(-2, 1, 6);
  const car = w.cars.find((c) => c.isLocal);
  w.ball.lastTouch = car;
  w.score = [1, 0];
  g.ui.setScore([1, 0]);
  g.ui.showBanner('GOL!', 'goal', 4000);
  g.ui.flash('blue');
  g.renderer.handleEvent({ type: 'goal', team: 0 }, w);
  return { score: w.score };
});
