await mob.locator('[data-action="start-offline"]').click();
await mob.waitForTimeout(2400);
await mob.evaluate(() => {
  const g = window.turboStrike; const w = g.world;
  w.phase = 'play'; w.countdown = 0;
  const car = w.cars.find((c) => c.isLocal);
  car.pos.set(0, 0, -6);
  car.yaw = 0;
  w.ball.pos.set(1, 6, 10);
  w.score = [1, 0];
  g.ui.setScore([1, 0]);
});
await mob.waitForTimeout(800);
await mob.screenshot({ path: join(out, 'final-mobile-gameplay.png') });
