#screen-root { position: absolute; inset: 0; z-index: 30; pointer-events: none; }
.screen {
  position: absolute; inset: 0; pointer-events: auto;
  opacity: 0; visibility: hidden; transform: scale(1.015);
  transition: opacity 0.35s ease, visibility 0.35s, transform 0.5s cubic-bezier(.2,.8,.2,1);
  display: flex; flex-direction: column; overflow: hidden;
}
.screen.active { opacity: 1; visibility: visible; transform: none; }
.screen.home { background: linear-gradient(100deg, rgba(3,5,11,.97) 0%, rgba(3,5,11,.88) 28%, rgba(3,5,11,.3) 60%, rgba(3,5,11,.55) 100%); }
.screen.panel-screen { background: radial-gradient(ellipse at 20% 0%, rgba(37, 72, 120, 0.22), transparent 55%), rgba(3, 6, 12, 0.82); backdrop-filter: blur(9px); }
.screen::before {
  content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .35;
  background-image: linear-gradient(rgba(100,170,255,.045) 1px, transparent 1px), linear-gradient(90deg, rgba(100,170,255,.045) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse at 50% 50%, black 10%, transparent 78%);
}

/* ---------- BRAND ---------- */
.brand { display: flex; flex-direction: column; gap: 2px; }
.brand-line { display: flex; align-items: center; gap: 12px; }
.brand-mark {
  width: 44px; height: 44px; border: 2px solid rgba(53,240,255,.55); border-radius: 12px;
  display: grid; place-items: center; position: relative; background: rgba(6, 16, 27, 0.7);
  box-shadow: 0 0 24px rgba(53, 240, 255, 0.18), inset 0 0 18px rgba(53, 240, 255, 0.1);
  transform: rotate(-4deg);
}
.brand-mark svg { width: 26px; height: 26px; }
.brand-title { font-family: var(--display); font-style: italic; font-size: 24px; letter-spacing: 2px; line-height: 1; }
.brand-title em { color: var(--orange); font-style: italic; }
.brand-sub { font-size: 9px; letter-spacing: 4.5px; color: var(--muted); font-weight: 700; margin-left: 56px; }

.home-inner {
  position: relative; z-index: 2; height: 100%; display: grid;
  grid-template-columns: minmax(360px, 480px) 1fr; padding: clamp(22px, 3.4vw, 46px) clamp(22px, 4vw, 64px);
}
.home-left { display: flex; flex-direction: column; justify-content: space-between; gap: 18px; min-height: 0; }
.hero-block { margin-top: clamp(10px, 6vh, 64px); }
