  display: inline-flex; align-items: center; gap: 8px; font-size: 10px; font-weight: 800;
  letter-spacing: 3.5px; color: var(--cyan); text-transform: uppercase; margin-bottom: 14px;
}
.eyebrow::before { content: ""; width: 26px; height: 2px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.hero-title {
  font-family: var(--display); font-style: italic; font-weight: 900;
  font-size: clamp(52px, 6.2vw, 92px); line-height: .84; letter-spacing: -2px;
  text-transform: uppercase; filter: drop-shadow(0 8px 40px rgba(0,0,0,.6));
}
.hero-title span { display: block; }
.hero-title .line-2 {
  background: linear-gradient(93deg, #fff 0%, #8fe9ff 34%, var(--cyan) 52%, #ff9a4d 78%, var(--orange) 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
