.menu-stack { display: flex; flex-direction: column; gap: 9px; width: min(100%, 400px); margin-top: 26px; }
.menu-btn {
  position: relative; display: flex; align-items: center; gap: 14px; width: 100%;
  padding: 14px 18px; text-align: left; color: #d8e6f8;
  background: linear-gradient(90deg, rgba(16, 27, 45, 0.86), rgba(10, 18, 31, 0.5));
